import { useEffect, useMemo, useRef, useState } from "react";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Sparkles, Send, Loader2 } from "lucide-react";
import { invokeAiCached } from "@/lib/aiCache";
import { useAbortOnUnmount } from "@/hooks/useAbortOnUnmount";
import { toast } from "sonner";

type Msg = { role: "user" | "assistant"; content: string };

/**
 * `seedContext` is a hidden hint that frames the conversation for the AI
 * (e.g. "the user is looking at an empty day"). It is NOT shown in the
 * textarea — earlier versions dumped this raw instruction into the input,
 * which looked like a weird half-written prompt to the user.
 */
export function AskAiSheet({
  open,
  onOpenChange,
  initialPrompt,
  seedContext,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  initialPrompt?: string | null;
  seedContext?: string | null;
}) {
  const [messages, setMessages] = useState<Msg[]>([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const scrollerRef = useRef<HTMLDivElement>(null);
  // Aborts the in-flight AI request when the sheet closes / unmounts so we
  // don't `setState` after unmount or surface a stale error toast.
  const getSignal = useAbortOnUnmount();

  useEffect(() => {
    if (open) {
      setInput(initialPrompt || "");
      setMessages([]);
    }
  }, [open, initialPrompt, seedContext]);

  useEffect(() => {
    scrollerRef.current?.scrollTo({ top: 99999, behavior: "smooth" });
  }, [messages, loading]);

  const send = async (text?: string) => {
    const content = (text ?? input).trim();
    if (!content || loading) return;
    const next: Msg[] = [...messages, { role: "user", content }];
    setMessages(next);
    setInput("");
    setLoading(true);
    const signal = getSignal();
    try {
      // Inject the seed context as a hidden first user turn so the
      // assistant has framing without exposing the meta-prompt to the user.
      const payload: Msg[] = seedContext
        ? [{ role: "user", content: `Context for the conversation (not shown to user): ${seedContext}` }, ...next]
        : next;
      const { data, error } = await invokeAiCached<{ reply?: string; error?: string }>(
        "ai-assist",
        { messages: payload },
        // Conversational turns shouldn't be cached — but in-flight dedup
        // still protects against double-tap submits.
        { ttlMs: 0, timeoutMs: 45_000, signal },
      );
      if (signal.aborted) return;
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      const reply = String(data?.reply || "").trim();
      if (!reply) throw new Error("Empty reply");
      setMessages((m) => [...m, { role: "assistant", content: reply }]);
    } catch (e: any) {
      if (signal.aborted) return;
      toast.error(e?.message || "AI is unavailable");
    } finally {
      if (!signal.aborted) setLoading(false);
    }
  };

  // Contextual quick prompts. We pick a small set based on the seed context
  // so the suggestions feel relevant to whatever the user just tapped.
  const quickPrompts = useMemo<{ label: string; prompt: string; send?: boolean }[]>(() => {
    const ctx = (seedContext || "").toLowerCase();
    if (ctx.includes("empty day")) {
      return [
        { label: "Help me decide what to focus on today", prompt: "Ask me 2-3 quick questions to help me decide what to focus on today.", send: true },
        { label: "Suggest a balanced day structure", prompt: "Suggest a balanced shape for a productive day (deep work, breaks, admin) without scheduling anything for me.", send: true },
        { label: "How do I avoid overcommitting?", prompt: "How do I pick a realistic number of tasks for one day without overcommitting?", send: true },
      ];
    }
    if (ctx.includes("this task")) {
      return [
        { label: "Estimate realistic time", prompt: "Give a realistic time estimate for this task and explain the assumption in one line.", send: true },
        { label: "Break it into 3-5 steps", prompt: "Break this task into 3-5 concrete, ordered steps I can check off.", send: true },
        { label: "Best time of day for it", prompt: "When in the day is this task usually best to do, and why?", send: true },
      ];
    }
    // Default: looking at an existing plan
    return [
      { label: "Spot one weak spot in my day", prompt: "Look at my current day and point out one weak spot or risk — just advice, don't change anything.", send: true },
      { label: "Where should I add a break?", prompt: "Where in my current day would a short break help most, and why?", send: true },
      { label: "Estimate time for…", prompt: "Estimate time for: " },
      { label: "Break a task into steps…", prompt: "Break this task into steps: " },
    ];
  }, [seedContext]);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="bottom" className="rounded-t-[28px] border-border/45 bg-popover h-[85vh] flex flex-col p-0">
        <SheetHeader className="px-5 pt-5 pb-3 text-left shrink-0">
          <SheetTitle className="flex items-center gap-2 text-[16px]">
            <Sparkles className="h-4 w-4 text-primary" /> Ask AI
          </SheetTitle>
          <p className="text-[12px] text-secondary-fg/80">
            A helper, not a planner. Ideas only — you decide what goes on the day.
          </p>
        </SheetHeader>

        <div ref={scrollerRef} className="min-h-0 flex-1 overflow-y-auto px-5 pb-3 space-y-3">
          {messages.length === 0 && !loading && (
            <div className="space-y-2.5 pt-1">
              <p className="text-[11px] uppercase tracking-wider text-secondary-fg/70 font-medium px-1">
                Try one of these
              </p>
              {quickPrompts.map((p) => (
                <button
                  key={p.label}
                  type="button"
                  onClick={() => {
                    if (p.send) {
                      void send(p.prompt);
                    } else {
                      setInput(p.prompt);
                    }
                  }}
                  className="w-full text-left px-3.5 py-3 rounded-2xl border border-border/40 bg-white/[0.03] dark:bg-white/[0.04] text-[13px] text-foreground/95 hover:bg-white/[0.08] pressable transition-colors"
                >
                  {p.label}
                </button>
              ))}
            </div>
          )}
          {messages.map((m, i) => (
            <div
              key={i}
              // Slide-up + fade in per bubble so new replies land organically
              // instead of snapping into place. tailwind-animate utilities
              // already drive the keyframes; we just stage them per bubble.
              className={`bubble-in max-w-[88%] rounded-[20px] px-3.5 py-2.5 text-[13px] leading-relaxed whitespace-pre-wrap ${
                m.role === "user"
                  ? "ml-auto bg-gradient-primary text-primary-foreground shadow-[0_4px_12px_hsl(var(--primary)/0.25)] border border-primary/20"
                  : "bg-surface-card border border-border/30 text-foreground/95"
              }`}
            >
              {m.content}
            </div>
          ))}
          {loading && (
            <div className="flex items-center gap-2 text-[12px] text-secondary-fg/80">
              <Loader2 className="h-3.5 w-3.5 animate-spin text-primary" /> Thinking…
            </div>
          )}
        </div>

        <div className="shrink-0 px-4 pb-4 pt-2 border-t border-border/30 bg-background/60 backdrop-blur-md">
          <div className="flex items-end gap-2">
            <Textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  void send();
                }
              }}
              placeholder="Ask anything about your day…"
              rows={1}
              className="resize-none min-h-[40px] max-h-32 rounded-xl bg-card border-border/40 text-[13px] focus:ring-1 focus:ring-primary/25 placeholder:text-secondary-fg/50"
            />
            <Button
              onClick={() => void send()}
              disabled={loading || !input.trim()}
              className="h-10 w-10 p-0 rounded-xl bg-gradient-primary text-primary-foreground hover:opacity-95 shadow-[0_4px_12px_hsl(var(--primary)/0.25)] pressable shrink-0"
              aria-label="Send"
            >
              <Send className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

import {
  createContext,
  Suspense,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ComponentType,
} from "react";
import { useLocation } from "react-router-dom";
import { lazyWithReload } from "@/lib/lazyWithReload";

/**
 * Native-iOS-style tab persistence: every tab page mounts once on first visit
 * and stays mounted afterwards. Switching tabs only toggles which tree is
 * visible (`display: none` for inactive). This preserves scroll position,
 * expanded/collapsed UI state, and — most importantly — eliminates the
 * unmount/remount cycle that was causing the remaining flicker.
 *
 * Trade-off: a few extra trees stay in the DOM. This is the standard pattern
 * UITabBarController uses (each tab view stays alive across switches), and
 * the React Query cache means the data layer is also stable.
 */

type TabKey = "home" | "day" | "tracker" | "reports" | "settings";

type TabDef = {
  key: TabKey;
  matches: (pathname: string) => boolean;
  load: () => Promise<{ default: ComponentType<unknown> }>;
};

const TABS: TabDef[] = [
  {
    key: "home",
    matches: (p) => p === "/" || p === "/home" || p.startsWith("/home/"),
    load: () => import("@/pages/app/Home"),
  },
  {
    key: "day",
    matches: (p) => p === "/today" || p.startsWith("/today/"),
    load: () => import("@/pages/app/DayView"),
  },
  {
    key: "tracker",
    matches: (p) => p === "/tracker" || p.startsWith("/tracker/"),
    load: () => import("@/pages/app/Tracker"),
  },
  {
    key: "reports",
    matches: (p) => p === "/reports" || p.startsWith("/reports/"),
    load: () => import("@/pages/app/Reports"),
  },
  {
    key: "settings",
    matches: (p) => p === "/settings",
    load: () => import("@/pages/app/Settings"),
  },
];

const LazyComponents: Record<TabKey, ComponentType<unknown>> = {
  home: lazyWithReload(() => import("@/pages/app/Home")),
  day: lazyWithReload(() => import("@/pages/app/DayView")),
  tracker: lazyWithReload(() => import("@/pages/app/Tracker")),
  reports: lazyWithReload(() => import("@/pages/app/Reports")),
  settings: lazyWithReload(() => import("@/pages/app/Settings")),
};

export function matchedTabKey(pathname: string): TabKey | null {
  for (const tab of TABS) {
    if (tab.matches(pathname)) return tab.key;
  }
  return null;
}

/**
 * Lets a tab page know whether its tree is the active one. Pages can use this
 * to pause expensive intervals (poll loops, "now" tickers) while inactive —
 * the tree stays alive, but the work pauses.
 */
const TabVisibilityCtx = createContext<boolean>(true);
export function useTabVisible(): boolean {
  return useContext(TabVisibilityCtx);
}

export function PersistentTabs() {
  const { pathname } = useLocation();
  const activeKey = useMemo(() => matchedTabKey(pathname), [pathname]);

  // Lazy-mount: a tab only enters the DOM the first time it is visited.
  // After that, it stays mounted forever (within this Shell lifecycle).
  const [mounted, setMounted] = useState<Set<TabKey>>(() => {
    return new Set(activeKey ? [activeKey] : []);
  });

  useEffect(() => {
    if (!activeKey) return;
    setMounted((prev) => {
      if (prev.has(activeKey)) return prev;
      const next = new Set(prev);
      next.add(activeKey);
      return next;
    });
  }, [activeKey]);

  return (
    <>
      {TABS.map((tab) => {
        if (!mounted.has(tab.key)) return null;
        const Component = LazyComponents[tab.key];
        const isActive = activeKey === tab.key;
        return (
          <div
            key={tab.key}
            // `display:none` keeps the React tree + DOM nodes + scroll
            // position alive, but releases the inactive tab from paint and
            // layout. The active tab takes the full main column.
            className={`flex min-h-0 flex-1 flex-col ${isActive ? "" : "hidden"}`}
            aria-hidden={!isActive}
          >
            <TabVisibilityCtx.Provider value={isActive}>
              <Suspense fallback={null}>
                <Component />
              </Suspense>
            </TabVisibilityCtx.Provider>
          </div>
        );
      })}
    </>
  );
}

/**
 * Tells callers whether a path is one of the persistent tab routes — used by
 * route config to decide whether to drop through to ShellLayout (tab) or
 * render a standalone page (drill-in).
 */
export const PERSISTENT_TAB_PATHS = [
  "/home",
  "/today",
  "/today/plan",
  "/tracker",
  "/reports",
  "/settings",
] as const;

import type React from "react";
import { memo, useState } from "react";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Block, fmtTime, inferScheduleBlockType, isOpenUserTask, isUserTaskDone } from "@/lib/daydraft";
import { Check, Calendar, Layers, GripVertical, Sparkles, Play, Square } from "lucide-react";

const SortableBlockInner = ({
  block, editing, onTap, onTapTime, onToggleComplete, onStartTrack, onStopTrack, trackingActive, assignedCategory, tourSpotlight,
}: {
  block: Block & {
    ai_reasoning?: string | null;
    location?: string | null;
    location_lat?: number | null;
    location_lng?: number | null;
    is_calendar_event?: boolean;
    overlap_ok?: boolean | null;
    slot_end_time?: string | null;
    completed_at?: string | null;
    resolution?: string | null;
    resolved_at?: string | null;
  };
  editing: boolean;
  onTap?: (b: any) => void;
  onTapTime?: (b: any) => void;
  onToggleComplete?: (b: any) => void;
  onStartTrack?: (b: any) => void;
  onStopTrack?: (b: any) => void;
  /** True if the live timer is currently running on this block. */
  trackingActive?: boolean;
  /** Category the user has earmarked for this block (not yet ticking). */
  assignedCategory?: { id: string; name: string; color: string } | null;
  /** First visible row — tour hotspot only on one element. */
  tourSpotlight?: boolean;
}) => {
  const sortableDisabled =
    !!block.is_calendar_event || (block.kind === "task" && !isOpenUserTask(block));
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: block.id,
    disabled: sortableDisabled,
  });
  // Compose the dnd-kit transform with our own scale/lift while dragging.
  // The iOS-style cue: the card grows slightly, lifts on a real shadow,
  // and floats above its neighbours (z-index). Non-dragging rows keep
  // dnd-kit's own transition so they rearrange smoothly underneath.
  const baseTransform = CSS.Transform.toString(transform) || "";
  const style: React.CSSProperties = {
    transform: isDragging ? `${baseTransform} scale(1.025)` : baseTransform,
    transition: isDragging
      ? "transform 160ms cubic-bezier(0.34,1.56,0.64,1), box-shadow 200ms ease"
      : transition,
    boxShadow: isDragging
      ? "0 24px 56px -16px hsl(0 0% 0% / 0.55), 0 0 0 1px hsl(var(--primary) / 0.35)"
      : undefined,
    zIndex: isDragging ? 30 : undefined,
    opacity: isDragging ? 0.98 : 1,
    touchAction: sortableDisabled ? undefined : "manipulation",
  };
  const isCal = block.is_calendar_event;
  const rhythmType = inferScheduleBlockType(block);
  const stripeColor = isCal
    ? "hsl(var(--border))"
    : rhythmType === "personal"
      ? "hsl(270 78% 66%)"
      : rhythmType === "rest"
        ? "hsl(var(--muted-foreground) / 0.7)"
        : "hsl(var(--primary))";
  const dur = block.duration_min < 60
    ? `${block.duration_min}m`
    : `${Math.floor(block.duration_min/60)}h${block.duration_min%60 ? ` ${block.duration_min%60}m` : ""}`;
  const fmtMin = (mins: number) =>
    mins < 60 ? `${mins}m` : `${Math.floor(mins / 60)}h${mins % 60 ? ` ${mins % 60}m` : ""}`;
  const estimatedMin = block.estimated_minutes ?? block.duration_min;
  const actualMin = typeof block.actual_minutes === "number" ? block.actual_minutes : null;
  const actualDeltaRatio = actualMin != null && estimatedMin > 0 ? (actualMin - estimatedMin) / estimatedMin : 0;
  const actualToneClass =
    actualMin == null
      ? "text-secondary-fg"
      : actualDeltaRatio > 0.4
        ? "text-destructive"
        : actualDeltaRatio > 0.2
          ? "text-amber-400"
          : actualDeltaRatio < -0.2
            ? "text-emerald-400"
            : "text-secondary-fg";
  return (
    <div
      ref={setNodeRef}
      style={style}
      data-tour={tourSpotlight ? "dayview-block" : undefined}
      // dnd-kit attributes + listeners are spread on the whole card so a
      // long-press anywhere on the row lifts it (matching iOS "edit mode"
      // home-screen behavior). The activation delay (220ms) means quick
      // taps still pass through to onClick handlers below.
      {...(sortableDisabled ? {} : attributes)}
      {...(sortableDisabled ? {} : listeners)}
      className={`group cursor-pointer tappable app-card rounded-[20px] px-3.5 py-3.5 shadow-sm list-row-contain ${
        isDragging ? "is-dragging" : ""
      } ${
        trackingActive ? "ring-[1.5px] ring-primary/40 bg-primary/[0.04] shadow-[0_0_32px_hsl(var(--primary)/0.12)]" : ""
      } ${
        isUserTaskDone(block) && block.kind === "task" ? "opacity-80" : ""
      } ${
        !isCal && block.overlap_ok ? "border-l-[3px] border-l-primary/45" : ""
      } ${
        isCal
          ? "!border-border/35"
          : rhythmType === "rest"
            ? "bg-muted/25 !border-border/35 hover:border-border/50"
            : rhythmType === "personal"
              ? "bg-[linear-gradient(165deg,hsl(278_72%_62%/.08)_0%,hsl(var(--surface)/.72)_58%,hsl(var(--surface-elevated)/.65)_100%)] border-[hsl(270_70%_66%/.28)] hover:border-[hsl(270_72%_70%/.44)]"
              : "!border-border/40 hover:border-border/55 hover:!border-primary/30"
      }`}
    >
      <div className="flex items-center gap-2">
        {!sortableDisabled ? (
          // Decorative-only handle — the press target is the whole row.
          // The icon brightens during drag so the user gets visual
          // confirmation they're moving it.
          <div
            className={`shrink-0 flex h-9 w-8 items-center justify-center rounded-lg pointer-events-none transition-colors ${
              isDragging ? "text-primary" : "text-secondary-fg/55"
            }`}
            aria-hidden
          >
            <GripVertical className="h-4 w-4" />
          </div>
        ) : (
          <div className="w-8 shrink-0" aria-hidden />
        )}
        <div
          className="flex min-w-0 flex-1 cursor-pointer items-center gap-3"
          onClick={() => onTap?.(block)}
        >
        {/*
          Time column. Fixed-width + right-aligned so the blue stripe
          to its right stays vertically aligned across every row, no
          matter whether the slot is a round hour ("14") or a partial
          time ("14:30"). `w-[3.25rem]` fits the widest reasonable
          locale output (24h "23:45" or 12h "12:45pm") with breathing
          room either side.

          Hide the planned start time for tasks that have already
          resolved (done / missed / skipped). The status row under the
          title already carries the meaningful timestamp; we keep an
          invisible placeholder of the same width so the stripe stays
          aligned with the still-active rows above.
        */}
        {(() => {
          const isTerminal =
            block.kind === "task" && !isCal && (
              isUserTaskDone(block) ||
              block.resolution === "skipped" ||
              block.resolution === "missed"
            );
          if (isTerminal) {
            return <div className="shrink-0 h-6 w-[3.25rem]" aria-hidden />;
          }
          if (onTapTime && !block.is_calendar_event) {
            return (
              <button
                type="button"
                onPointerDown={(e) => e.stopPropagation()}
                onClick={(e) => { e.stopPropagation(); onTapTime?.(block); }}
                className="shrink-0 h-6 w-[3.25rem] pr-1.5 inline-flex items-center justify-end text-secondary-fg/85 text-[10.5px] font-mono-sf tabular-nums pressable hover:text-foreground transition-colors rounded-md"
                aria-label="Change start time"
                title="Change start time"
              >
                {fmtTime(block.start_time)}
              </button>
            );
          }
          return (
            <div className="shrink-0 h-6 w-[3.25rem] pr-1.5 inline-flex items-center justify-end text-secondary-fg/70 text-[10.5px] font-mono-sf tabular-nums">
              {fmtTime(block.start_time)}
            </div>
          );
        })()}
        <div className="w-[4px] h-8 rounded-full shrink-0" style={{ background: stripeColor }} />
        <div className="flex-1 min-w-0">
          <div className={`leading-tight flex items-center gap-1.5 min-w-0 ${rhythmType === "rest" ? "text-[12.5px]" : "text-[14px] font-medium"} ${isUserTaskDone(block) && block.kind === "task" ? "text-foreground/65" : "text-foreground"}`}>
          {isCal && <Calendar className="h-3 w-3 text-secondary-fg shrink-0" />}
          {!isCal && rhythmType === "rest" && <span className="shrink-0 text-[12px] leading-none" aria-hidden>☕</span>}
          <span className={`truncate ${isUserTaskDone(block) && block.kind === "task" ? "line-through" : ""}`}>{block.title}</span>
          {!isCal && Boolean(block.overlap_ok) && (
            <span className="shrink-0 text-secondary-fg" title="Runs alongside other work">
              <Layers className="h-3 w-3" aria-hidden />
            </span>
          )}
          {!isCal && block.ai_reasoning && (
            <span className="shrink-0 text-primary/70" title="Why this slot">
              <Sparkles className="h-3 w-3" aria-hidden />
            </span>
          )}
          </div>
          <div className={`${rhythmType === "rest" ? "text-[10px]" : "text-[10.5px]"} text-secondary-fg mt-1 tabular-nums`}>
            {block.kind === "task" && !isCal && block.resolution === "skipped" && block.resolved_at && (
              <span className="text-amber-700/90 dark:text-amber-400/85">
                Skipped ·{" "}
                {new Date(block.resolved_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }).replace(/\s/g, "")}
                <span className="text-faint mx-1">·</span>
              </span>
            )}
            {block.kind === "task" && !isCal && block.resolution === "missed" && block.resolved_at && (
              <span className="text-destructive/85">
                Missed ·{" "}
                {new Date(block.resolved_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }).replace(/\s/g, "")}
                <span className="text-faint mx-1">·</span>
              </span>
            )}
            {isUserTaskDone(block) && block.completed_at && (
              <span className="text-faint">
                Done {new Date(block.completed_at).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }).replace(/\s/g, "")}
                <span className="text-faint mx-1">·</span>
              </span>
            )}
            {isUserTaskDone(block) && actualMin != null ? (
              <>
                <span className="font-medium text-foreground">{fmtMin(actualMin)}</span>
                <span className="text-faint"> actual</span>
                {estimatedMin !== actualMin && (
                  <span className="text-faint"> · {fmtMin(estimatedMin)} est</span>
                )}
              </>
            ) : isUserTaskDone(block) ? (
              <span className="text-faint">{fmtMin(estimatedMin)} planned</span>
            ) : (
              <span className="text-faint">{dur}</span>
            )}
          </div>
          {isUserTaskDone(block) && actualMin != null && estimatedMin > 0 && actualMin >= 2 && (
            <div className={`mt-0.5 text-[10px] tabular-nums ${actualToneClass}`}>
              {actualDeltaRatio > 0.15
                ? `${Math.round(actualDeltaRatio * 100)}% longer than planned`
                : actualDeltaRatio < -0.15
                  ? `${Math.round(-actualDeltaRatio * 100)}% under plan`
                  : "On track vs plan"}
            </div>
          )}
          {trackingActive ? (
            <div className="mt-1 inline-flex items-center gap-1.5 rounded-full bg-success/15 text-success border border-success/25 px-2 py-0.5 text-[10.5px] font-medium leading-none">
              <span className="h-1.5 w-1.5 rounded-full bg-success animate-pulse" />
              Tracking now
            </div>
          ) : assignedCategory ? (
            <div className="mt-1 inline-flex items-center gap-1.5 rounded-full border border-border/45 bg-card/60 px-2 py-0.5 text-[10.5px] font-medium leading-none text-foreground/80">
