            <div className="app-card px-4 py-4 space-y-3">
              <div className="flex items-start justify-between gap-2">
                <button
                  type="button"
                  onClick={() => setMonthCursor((d) => {
                    const x = new Date(d);
                    x.setMonth(x.getMonth() - 1);
