                  <div className="flex items-center gap-1">
                    <span className="text-faint">0m</span>
                    {[0.2, 0.45, 0.7, 1].map((o, idx) => (
                      <span key={idx} className="h-3 w-3 rounded-sm border border-border/50" style={{ backgroundColor: `hsl(var(--primary) / ${o})` }} />
