    },
  ) => Promise<void>;
  addManualEntry: (categoryId: string, durationSec: number, opts?: { startedAt?: Date; note?: string }) => Promise<void>;
  deleteEntry: (id: string) => Promise<void>;
  todayTotalSec: number;
  weekTotalSec: number;
  refresh: () => Promise<void>;
};

const TimeTrackerCtx = createContext<Ctx | null>(null);
/** Minute-resolution heartbeat. Drives `fmtHM` totals that only change once a minute. */
const TimeTrackerElapsedMinCtx = createContext(0);

const PALETTE = ["#6366f1", "#ec4899", "#f59e0b", "#10b981", "#06b6d4", "#8b5cf6", "#ef4444"];

const remindedEntryIds = new Set<string>();
const REMIND_AFTER_HOURS = 2;

const CATEGORIES_ROOT = "time-categories" as const;
const categoriesQueryKey = (userId: string | undefined) =>
  [CATEGORIES_ROOT, userId ?? ""] as const;

const ACTIVE_ENTRY_ROOT = "time-tracker-active" as const;
const activeEntryQueryKey = (userId: string | undefined) =>
  [ACTIVE_ENTRY_ROOT, userId ?? ""] as const;

function fmtAge(ms: number): string {
  const m = Math.floor(ms / 60000);
  const h = Math.floor(m / 60);
  return h > 0 ? `${h}h ${m % 60}m` : `${m}m`;
}

function tryBrowserNotify(title: string, body: string) {
  try {
    if (typeof window === "undefined" || !("Notification" in window)) return;
    if (Notification.permission !== "granted") return;
    new Notification(title, { body, tag: "dd-tracker-running" });
  } catch {
    /* ignore */
  }
}

async function fetchCategories(userId: string): Promise<TimeCategory[]> {
  const { data, error } = await supabase
    .from("time_categories")
    .select("*")
    .eq("user_id", userId)
    .order("created_at");
  if (error) throw error;
  return dedupeCategoriesStable((data || []) as TimeCategory[]);
}

async function fetchActiveEntry(userId: string): Promise<TimeEntry | null> {
  const { data, error } = await supabase
    .from("time_entries")
    .select("*")
    .eq("user_id", userId)
    .is("ended_at", null)
    .order("started_at", { ascending: false })
    .limit(1);
  if (error) throw error;
  return ((data ?? [])[0] as TimeEntry) || null;
}

/**
 * Sum durations from a rolling list of entries, clipped to a given window.
 * Used to derive today/week totals from the shared 60-day cache without a
 * second SELECT.
 */
function sumEntryDurations(
  entries: RollingEntry[],
  windowStartMs: number,
  windowEndMs: number,
  now: number,
): number {
  let total = 0;
  for (const e of entries) {
    const s = new Date(e.started_at).getTime();
    const en = e.ended_at ? new Date(e.ended_at).getTime() : now;
    const a = Math.max(s, windowStartMs);
    const b = Math.min(en, windowEndMs);
    if (b > a) total += (b - a) / 1000;
  }
  return total;
}

export function TimeTrackerProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  // Minute-resolution heartbeat used to recompute today/week totals.
  // The per-second tick lives outside React (see emitElapsed above) so the
  // running timer never causes a re-render.
  const [elapsedMin, setElapsedMin] = useState(0);
  const workerRef = useRef<Worker | null>(null);
  const fallbackTickRef = useRef<number | null>(null);
  const alignmentRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const userId = user?.id;
  const enabled = !!userId;

  const categoriesQuery = useQuery({
    queryKey: categoriesQueryKey(userId),
    queryFn: () => fetchCategories(userId!),
    enabled,
    staleTime: 5 * 60_000,
    gcTime: 30 * 60_000,
    placeholderData: keepPreviousData,
  });

  const activeQuery = useQuery({
    queryKey: activeEntryQueryKey(userId),
    queryFn: () => fetchActiveEntry(userId!),
    enabled,
    staleTime: 60_000,
    gcTime: 30 * 60_000,
    placeholderData: keepPreviousData,
  });

  // Local-first hydration. On cold launch (or after the gc'd cache clears
  // overnight), prime the React Query cache from IndexedDB before the live
  // fetch lands so totals paint instantly. Runs once per user-id change.
  useEffect(() => {
    if (!userId) return;
    void hydrateRollingEntries(queryClient, userId);
  }, [userId, queryClient]);

  const entriesQuery = useQuery({
    queryKey: rollingEntriesQueryKey(userId),
    queryFn: () => fetchRollingEntries(userId!),
    enabled,
    staleTime: 60_000,
    gcTime: 30 * 60_000,
    placeholderData: keepPreviousData,
  });

  const categories = categoriesQuery.data ?? [];
  const active = activeQuery.data ?? null;
  const entries = entriesQuery.data ?? [];

  const loading =
    enabled &&
    (categoriesQuery.isLoading || activeQuery.isLoading || entriesQuery.isLoading);

  // Derive totals from the shared rolling entries. When a timer is running the
  // active entry already has a null ended_at, so sumEntryDurations counts the
  // live elapsed window automatically. `elapsedMin` is the minute-resolution
  // heartbeat that re-derives `now`; once-a-minute is the right cadence for
  // `fmtHM` totals (h+m only — sub-minute changes wouldn't be visible).
  const { todayTotalSec, weekTotalSec } = useMemo(() => {
    const now = Date.now();
    const startOfToday = new Date();
    startOfToday.setHours(0, 0, 0, 0);
    const startOfWeek = new Date();
    startOfWeek.setDate(startOfWeek.getDate() - 7);
    startOfWeek.setHours(0, 0, 0, 0);
    return {
      todayTotalSec: sumEntryDurations(entries, startOfToday.getTime(), now, now),
      weekTotalSec: sumEntryDurations(entries, startOfWeek.getTime(), now, now),
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entries, elapsedMin]);

  // Timer tick. Runs in a Web Worker so the cadence survives tab throttling /
  // background phone screen, and so it never schedules React work on the main
  // thread. The worker posts {elapsedSec} once a second; we forward to the
  // subscribers (LiveElapsed components write straight to the DOM) and only
  // touch React state on minute boundaries.
  useEffect(() => {
    // Stop any prior tick.
    const stopFallback = () => {
      if (fallbackTickRef.current != null) {
        clearInterval(fallbackTickRef.current);
        fallbackTickRef.current = null;
      }
      if (alignmentRef.current != null) {
        clearTimeout(alignmentRef.current);
        alignmentRef.current = null;
      }
    };
    const stopWorker = () => {
      if (workerRef.current) {
        try { workerRef.current.postMessage({ type: "stop" }); } catch { /* ignore */ }
      }
    };
    stopFallback();
    stopWorker();
    emitElapsed(0);
    setElapsedMin(0);
    if (!active) return;

    const started = new Date(active.started_at).getTime();
    let lastMin = -1;

    const handleTick = (sec: number) => {
      emitElapsed(sec);
      const min = Math.floor(sec / 60);
      if (min !== lastMin) {
        lastMin = min;
        setElapsedMin(min);
      }
    };

    // Try the worker first; fall back to a main-thread interval if the
    // environment can't spawn workers (older WebViews, some test runners).
    let usingWorker = false;
    try {
      if (typeof Worker !== "undefined") {
        const worker = new Worker(
          new URL("@/workers/timer.worker.ts", import.meta.url),
          { type: "module" },
        );
        worker.onmessage = (e: MessageEvent) => {
          const msg = e.data;
          if (!msg) return;
          if (msg.type === "tick") {
            handleTick(msg.elapsedSec as number);
          } else if (msg.type === "drift") {
            recordTimerDrift(msg.drift as number);
            // Resync from system clock on large drift.
            worker.postMessage({ type: "start", startedAtMs: started });
          }
        };
        worker.postMessage({ type: "start", startedAtMs: started });
        workerRef.current = worker;
        usingWorker = true;
      }
    } catch {
      usingWorker = false;
    }

    if (!usingWorker) {
      const update = () => {
        handleTick(Math.max(0, Math.floor((Date.now() - started) / 1000)));
      };
      update();
      const msToNextSec = 1000 - (Date.now() % 1000);
      alignmentRef.current = setTimeout(() => {
        update();
        fallbackTickRef.current = window.setInterval(update, 1000);
      }, msToNextSec);
    }

    // When the tab comes back to the foreground after a long sleep, the
    // worker will already be in sync (it's not throttled), but we ping it to
    // get an immediate update on the DOM so the digits don't lag a second.
    const onVisibility = () => {
      if (!document.hidden) {
        if (workerRef.current) {
          try { workerRef.current.postMessage({ type: "ping" }); } catch { /* ignore */ }
        } else {
          // Main-thread fallback: recompute now in case the interval was
          // throttled while hidden.
          handleTick(Math.max(0, Math.floor((Date.now() - started) / 1000)));
        }
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      stopFallback();
      if (workerRef.current) {
        try { workerRef.current.postMessage({ type: "stop" }); } catch { /* ignore */ }
        workerRef.current.terminate();
        workerRef.current = null;
      }
    };
  }, [active?.id, active?.started_at]);

  useEffect(() => {
    if (!active) return;
    const handler = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = "";
    };
    window.addEventListener("beforeunload", handler);
    return () => window.removeEventListener("beforeunload", handler);
  }, [active?.id]);

  const refresh = useCallback(async () => {
    if (!userId) return;
    await Promise.all([
      queryClient.invalidateQueries({ queryKey: categoriesQueryKey(userId) }),
      queryClient.invalidateQueries({ queryKey: activeEntryQueryKey(userId) }),
      invalidateRollingEntries(queryClient, userId),
    ]);
  }, [queryClient, userId]);

  const setCategoriesData = useCallback(
    (updater: (prev: TimeCategory[]) => TimeCategory[]) => {
      if (!userId) return;
      queryClient.setQueryData<TimeCategory[]>(categoriesQueryKey(userId), (prev) =>
        dedupeCategoriesStable(updater(prev ?? [])),
      );
    },
    [queryClient, userId],
  );

  const setActiveData = useCallback(
    (entry: TimeEntry | null) => {
      if (!userId) return;
      queryClient.setQueryData<TimeEntry | null>(activeEntryQueryKey(userId), entry);
    },
    [queryClient, userId],
  );

  // Long-running timer reminder.
  const stopRef = useRef<() => Promise<boolean>>(async () => false);
  useEffect(() => {
    if (!active) return;
    let cancelled = false;
    const fire = () => {
      if (cancelled || !active) return;
      const ageMs = Date.now() - new Date(active.started_at).getTime();
      if (ageMs < REMIND_AFTER_HOURS * 3_600_000) return;
      if (remindedEntryIds.has(active.id)) return;
      remindedEntryIds.add(active.id);
      const ageLabel = fmtAge(ageMs);
      tryBrowserNotify("Timer still running", `Your timer has been running for ${ageLabel}.`);
      toast(`Timer running for ${ageLabel} — still working?`, {
        duration: 12000,
        action: {
          label: "Stop",
          onClick: () => {
            void stopRef.current();
          },
        },
      });
    };
    const initial = window.setTimeout(fire, 1500);
    const interval = window.setInterval(fire, 10 * 60_000);
    return () => {
      cancelled = true;
      clearTimeout(initial);
      clearInterval(interval);
    };
  }, [active?.id, active?.started_at]);

  const startSession = async (
    categoryId?: string,
    opts?: { source?: string; note?: string; blockId?: string },
  ) => {
    if (!user) return;
    const cat =
      categoryId || categories.find((c) => c.is_default)?.id || categories[0]?.id;
    if (!cat) {
      toast.error("Add a category first");
      return;
    }
    const { data, error } = await supabase
      .from("time_entries")
      .insert({
        user_id: user.id,
        category_id: cat,
        source: opts?.source || "manual",
        note: opts?.note || null,
        block_id: opts?.blockId || null,
      })
      .select("*")
      .single();
    if (error) {
      toast.error(error.message);
      return;
    }
    const entry = data as TimeEntry;
    setActiveData(entry);
    // Optimistically prepend the live entry to the rolling cache so today/week
    // totals start counting immediately without a second round-trip.
    queryClient.setQueryData<RollingEntry[]>(
      rollingEntriesQueryKey(user.id),
      (prev) => {
        const next: RollingEntry = {
          id: entry.id,
          category_id: entry.category_id,
          started_at: entry.started_at,
          ended_at: entry.ended_at,
          note: entry.note,
          block_id: entry.block_id,
          source: entry.source,
        };
        return [next, ...(prev ?? [])];
      },
    );
    if (opts?.blockId) {
      try {
        const d = new Date();
        const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
        localStorage.setItem(`dd_last_plan_progress_${key}`, new Date().toISOString());
      } catch {
        /* ignore */
      }
    }
  };

  const start: Ctx["start"] = async (categoryId, opts) => {
    if (active) return;
    await startSession(categoryId, opts);
  };

  const stop: Ctx["stop"] = async () => {
    if (!active || !user) return false;
    const current = active;
    const endedAt = new Date().toISOString();
    const { error } = await supabase
      .from("time_entries")
      .update({ ended_at: endedAt })
      .eq("id", current.id);
    if (error) {
      toast.error(error.message);
      return false;
    }
    const dur = Math.floor((Date.now() - new Date(current.started_at).getTime()) / 1000);
    if (current.block_id) {
      try {
        const { data: rows } = await supabase
          .from("time_entries")
          .select("started_at,ended_at")
          .eq("user_id", user.id)
          .eq("block_id", current.block_id)
          .not("ended_at", "is", null);
        const actualMin = Math.max(
          0,
          Math.round(
            (rows || []).reduce((sum: number, e: any) => {
              const s = new Date(e.started_at).getTime();
              const en = e.ended_at ? new Date(e.ended_at).getTime() : s;
              return sum + Math.max(0, (en - s) / 60000);
            }, 0),
          ),
        );
        await supabase.from("blocks").update({ actual_minutes: actualMin }).eq("id", current.block_id);
        try {
          window.dispatchEvent(
            new CustomEvent("dd-block-timer-stopped", {
              detail: { blockId: current.block_id, actualMinutes: actualMin },
            }),
          );
        } catch {
          /* ignore */
        }
      } catch {
        /* non-fatal */
      }
    }
    setActiveData(null);
    queryClient.setQueryData<RollingEntry[]>(
      rollingEntriesQueryKey(user.id),
      (prev) =>
        (prev ?? []).map((e) =>
          e.id === current.id ? { ...e, ended_at: endedAt } : e,
        ),
    );
    const m = Math.floor(dur / 60);
    toast.success(`Tracked ${m < 60 ? `${m}m` : `${Math.floor(m / 60)}h ${m % 60}m`}`);
    return true;
  };
  stopRef.current = stop;

  useEffect(() => {
    try {
      if (sessionStorage.getItem("dd_track_titles_swept")) return;
      const keepCount = 30;
      const keys: string[] = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith("dd_track_titles_")) keys.push(k);
      }
      if (keys.length > keepCount) {
        keys
          .sort()
          .slice(0, keys.length - keepCount)
          .forEach((k) => localStorage.removeItem(k));
      }
      sessionStorage.setItem("dd_track_titles_swept", "1");
    } catch {
      /* ignore */
    }
  }, []);

  const switchCategory: Ctx["switchCategory"] = async (categoryId) => {
    if (!active) {
      await start(categoryId);
      return;
    }
    if (active.category_id === categoryId) return;
    const stopped = await stop();
    if (!stopped) return;
    await startSession(categoryId);
  };

  const addCategory: Ctx["addCategory"] = async (name, color) => {
    if (!user) return null;
    const trimmed = name.trim();
    if (!trimmed) return null;
    const existing = categories.find(
      (c) => c.name.trim().toLowerCase() === trimmed.toLowerCase(),
    );
    if (existing) return existing;
    const usedColors = new Set(categories.map((c) => c.color));
    const pick =
      color || PALETTE.find((c) => !usedColors.has(c)) || PALETTE[categories.length % PALETTE.length];
    const { data, error } = await supabase
      .from("time_categories")
      .insert({
        user_id: user.id,
        name: trimmed,
        color: pick,
        is_default: false,
      })
      .select("*")
      .single();
    if (error) {
      if ((error as { code?: string }).code === "23505") {
        const { data: again } = await supabase
          .from("time_categories")
          .select("*")
          .eq("user_id", user.id);
        const hit = (again || []).find(
          (c: TimeCategory) => c.name.trim().toLowerCase() === trimmed.toLowerCase(),
        );
        if (hit) {
          setCategoriesData(() => (again || []) as TimeCategory[]);
          return hit as TimeCategory;
        }
      }
      toast.error(error.message);
      return null;
    }
    setCategoriesData((prev) => [...prev, data as TimeCategory]);
    return data as TimeCategory;
  };

  const deleteCategory: Ctx["deleteCategory"] = async (id) => {
    const cat = categories.find((c) => c.id === id);
    if (cat?.is_default) {
      toast.error("Can't delete default category");
      return;
    }
    const { error } = await supabase.from("time_categories").delete().eq("id", id);
    if (error) {
      toast.error(error.message);
      return;
    }
    setCategoriesData((prev) => prev.filter((c) => c.id !== id));
  };

  const renameCategory: Ctx["renameCategory"] = async (id, name) => {
    const trimmed = name.trim();
    if (!trimmed) {
      toast.error("Name can't be empty");
      return;
    }
    const { error } = await supabase
      .from("time_categories")
      .update({ name: trimmed })
      .eq("id", id);
    if (error) {
      toast.error(error.message);
      return;
    }
    setCategoriesData((prev) => prev.map((c) => (c.id === id ? { ...c, name: trimmed } : c)));
  };

  const updateCategoryRate: Ctx["updateCategoryRate"] = async (id, hourlyRate) => {
    const normalized =
      hourlyRate === null ? null : Math.max(0, Math.round(hourlyRate * 100) / 100);
    const { error } = await supabase
      .from("time_categories")
      .update({ hourly_rate: normalized } as any)
      .eq("id", id);
    if (error) {
      toast.error(error.message);
      return;
    }
    setCategoriesData((prev) =>
      prev.map((c) => (c.id === id ? { ...c, hourly_rate: normalized } : c)),
    );
  };

  const updateCategoryBilling: Ctx["updateCategoryBilling"] = async (id, draft) => {
    const row = billingDraftToCategoryUpdate(draft);
    const { error } = await supabase
      .from("time_categories")
      .update(row as any)
      .eq("id", id);
    if (error) {
      toast.error(error.message);
      return;
    }
    setCategoriesData((prev) =>
      prev.map((c) => (c.id === id ? { ...c, ...row } : c)),
    );
  };

  const addManualEntry: Ctx["addManualEntry"] = async (categoryId, durationSec, opts) => {
    if (!user) return;
    const end = opts?.startedAt
      ? new Date(opts.startedAt.getTime() + durationSec * 1000)
      : new Date();
    const start = opts?.startedAt || new Date(Date.now() - durationSec * 1000);
    const { data, error } = await supabase
      .from("time_entries")
      .insert({
        user_id: user.id,
        category_id: categoryId,
        started_at: start.toISOString(),
        ended_at: end.toISOString(),
        source: "manual_add",
        note: opts?.note || null,
      })
      .select("*")
      .single();
    if (error) {
      toast.error(error.message);
      return;
    }
    const m = Math.round(durationSec / 60);
    toast.success(`Logged ${m < 60 ? `${m}m` : `${Math.floor(m / 60)}h ${m % 60}m`}`);
    const inserted = data as any;
    queryClient.setQueryData<RollingEntry[]>(
      rollingEntriesQueryKey(user.id),
      (prev) => {
        const row: RollingEntry = {
          id: inserted.id,
          category_id: inserted.category_id,
          started_at: inserted.started_at,
          ended_at: inserted.ended_at,
          note: inserted.note,
          block_id: inserted.block_id ?? null,
          source: inserted.source,
        };
        return [row, ...(prev ?? [])];
      },
    );
  };

  const deleteEntry: Ctx["deleteEntry"] = async (id) => {
    const { error } = await supabase.from("time_entries").delete().eq("id", id);
    if (error) {
      toast.error(error.message);
      return;
    }
    if (user?.id) {
      queryClient.setQueryData<RollingEntry[]>(
        rollingEntriesQueryKey(user.id),
        (prev) => (prev ?? []).filter((e) => e.id !== id),
      );
    }
  };

  const value: Ctx = useMemo(
    () => ({
      categories,
      active,
      loading,
      start,
      stop,
      switchCategory,
      addCategory,
      deleteCategory,
      renameCategory,
      updateCategoryRate,
      updateCategoryBilling,
      addManualEntry,
      deleteEntry,
      todayTotalSec,
      weekTotalSec,
      refresh,
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [categories, active, loading, todayTotalSec, weekTotalSec, refresh],
  );

  return (
    <TimeTrackerElapsedMinCtx.Provider value={elapsedMin}>
      <TimeTrackerCtx.Provider value={value}>{children}</TimeTrackerCtx.Provider>
    </TimeTrackerElapsedMinCtx.Provider>
  );
}

export function useTimeTracker() {
  const ctx = useContext(TimeTrackerCtx);
  if (!ctx) throw new Error("useTimeTracker must be used inside TimeTrackerProvider");
  return ctx;
}

/**
 * Back-compat hook. Used to re-render once a second; now re-renders once a
 * minute. Suitable for `fmtHM`-style derivations. Pages that need
 * second-level updates should use `<LiveElapsed format={...} />` or
 * subscribe via `subscribeElapsed` directly — those do NOT trigger React
 * renders.
 */
export function useTimeTrackerElapsed() {
  // Returns minute-aligned seconds so consumers that pass this into
  // fmtHM/fmtHMS-like formatters still see a number that grows over time.
  return useContext(TimeTrackerElapsedMinCtx) * 60;
}

export const fmtHMS = (s: number) => {
  const h = Math.floor(s / 3600),
    m = Math.floor((s % 3600) / 60),
    sec = Math.floor(s % 60);
  if (h > 0) return `${h}:${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
  return `${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
};

export const fmtHM = (s: number) => {
  const h = Math.floor(s / 3600),
    m = Math.floor((s % 3600) / 60);
  if (h === 0) return `${m}m`;
  if (m === 0) return `${h}h`;
  return `${h}h ${m}m`;
};

import { supabase } from "@/integrations/supabase/client";
import {
  recordAiCacheHit,
  recordAiCacheMiss,
  recordAiCall,
} from "./perfMonitor";

/**
 * Cached + deduplicated invocation wrapper for our Supabase Edge Functions.
 *
 *   const { data, error } = await invokeAiCached("generate-plan", payload, {
 *     ttlMs: 60_000,             // memoize identical requests for 60s
 *     persistMs: 7 * 86_400_000, // also persist to localStorage for 7 days
 *     cacheKey: ...,             // override the auto-derived key if needed
 *   });
 *
 * Three layers:
 *
 *   1. In-flight deduplication. If the same payload is in flight already,
 *      hand back the same Promise. Saves a roundtrip on double-tap and on
 *      transient duplicate calls from race conditions.
 *
 *   2. In-memory TTL cache. Identical requests within `ttlMs` return the
 *      cached response. Stays warm across tab switches but resets on
 *      reload.
 *
 *   3. Optional persistent layer (localStorage) with its own TTL. Use this
 *      for outputs that are stable across reloads — weekly digests,
 *      monthly reports, PDF narratives.
 *
 * All durations are tracked via perfMonitor so the debug panel can show
 * cache hit ratio + p95 call duration.
 */

type InvokeResult<T = unknown> = {
  data: T | null;
  error: { message: string; [k: string]: unknown } | null;
};

type CacheEntry<T = unknown> = {
  data: T;
  expiresAt: number;
};

type Options = {
  /** In-memory cache lifetime. 0 disables the memory layer. */
  ttlMs?: number;
  /** Persistent (localStorage) cache lifetime. 0 disables persistence. */
  persistMs?: number;
  /** Override the auto-derived cache key. */
  cacheKey?: string;
  /** Per-call timeout — aborts the request when exceeded. */
  timeoutMs?: number;
  /**
   * Caller-supplied AbortSignal. When it fires we *stop waiting* for the
   * result and return `{ data: null, error: { aborted: true } }`. The
   * underlying network request keeps running so other in-flight observers
   * (and the cache) still benefit — only this caller hands back early.
   * Pass a signal tied to your component's lifecycle to prevent
   * "set-state-after-unmount" warnings when the user navigates away
   * mid-call.
   */
  signal?: AbortSignal;
};

const ABORT_ERROR = { message: "aborted", aborted: true } as const;

/**
 * Resolve with whichever happens first: the underlying promise, or the
 * caller's signal firing. Used so an unmounted React component can stop
 * caring about an AI response without cancelling the shared request for
 * other consumers.
 */
function settleWithSignal<T>(p: Promise<InvokeResult<T>>, signal?: AbortSignal): Promise<InvokeResult<T>> {
  if (!signal) return p;
  if (signal.aborted) return Promise.resolve({ data: null, error: { ...ABORT_ERROR } });
  return new Promise<InvokeResult<T>>((resolve) => {
    let done = false;
    const finish = (val: InvokeResult<T>) => {
      if (done) return;
      done = true;
      signal.removeEventListener("abort", onAbort);
      resolve(val);
    };
    const onAbort = () => finish({ data: null, error: { ...ABORT_ERROR } });
    signal.addEventListener("abort", onAbort, { once: true });
    p.then(finish).catch((e: unknown) => {
      finish({ data: null, error: { message: e instanceof Error ? e.message : String(e) } });
    });
  });
}

const DEFAULT_TTL_MS = 30_000;
const memCache = new Map<string, CacheEntry>();
const inflight = new Map<string, Promise<InvokeResult<unknown>>>();

const PERSIST_PREFIX = "dd_ai_cache:";

function djb2(input: string): string {
  let h = 5381;
  for (let i = 0; i < input.length; i++) h = ((h << 5) + h + input.charCodeAt(i)) | 0;
  return Math.abs(h).toString(36);
}

function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  const keys = Object.keys(value as Record<string, unknown>).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify((value as any)[k])}`).join(",")}}`;
}

function deriveKey(name: string, body: unknown): string {
  return `${name}:${djb2(stableStringify(body))}`;
}

function readPersistent<T>(key: string): T | null {
  try {
    const raw = localStorage.getItem(PERSIST_PREFIX + key);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as CacheEntry<T>;
    if (!parsed || typeof parsed !== "object") return null;
    if (parsed.expiresAt < Date.now()) {
      localStorage.removeItem(PERSIST_PREFIX + key);
      return null;
    }
    return parsed.data;
  } catch {
    return null;
  }
}

function writePersistent<T>(key: string, data: T, ttlMs: number): void {
  try {
    const entry: CacheEntry<T> = { data, expiresAt: Date.now() + ttlMs };
    localStorage.setItem(PERSIST_PREFIX + key, JSON.stringify(entry));
  } catch {
    /* quota exceeded — best effort */
  }
}

export async function invokeAiCached<T = unknown>(
  name: string,
  body: unknown,
  options: Options = {},
): Promise<InvokeResult<T>> {
  const ttlMs = options.ttlMs ?? DEFAULT_TTL_MS;
  const persistMs = options.persistMs ?? 0;
  const key = options.cacheKey ?? deriveKey(name, body);

  // 1. memory layer
  if (ttlMs > 0) {
    const hit = memCache.get(key);
    if (hit && hit.expiresAt > Date.now()) {
      recordAiCacheHit(name);
      return { data: hit.data as T, error: null };
    }
  }

  // 2. persistent layer
  if (persistMs > 0) {
    const persisted = readPersistent<T>(key);
    if (persisted !== null) {
      recordAiCacheHit(name);
      // promote to memory cache so subsequent hits skip JSON.parse
      memCache.set(key, { data: persisted, expiresAt: Date.now() + Math.min(ttlMs || persistMs, persistMs) });
      return { data: persisted, error: null };
    }
  }

  // 3. dedup in-flight
  const existing = inflight.get(key);
  if (existing) {
    recordAiCacheHit(name);
    return settleWithSignal(existing as Promise<InvokeResult<T>>, options.signal);
  }

  recordAiCacheMiss(name);
  const started = typeof performance !== "undefined" ? performance.now() : Date.now();

  const runner = (async (): Promise<InvokeResult<T>> => {
    let controller: AbortController | null = null;
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    if (options.timeoutMs && options.timeoutMs > 0) {
      controller = new AbortController();
      timeoutId = setTimeout(() => controller?.abort(), options.timeoutMs);
    }
    try {
      const invokeOpts: Record<string, unknown> = { body };
      if (controller) invokeOpts.signal = controller.signal;
      // Forward the dev "Simulate Pro" flag so edge functions bypass
      // subscription checks in dev. No-op in prod (header is empty).
      try {
        const { devSimulateProHeaders } = await import("@/lib/devEntitlement");
        const extra = devSimulateProHeaders();
        if (Object.keys(extra).length > 0) invokeOpts.headers = extra;
      } catch { /* ignore */ }
      const { data, error } = await supabase.functions.invoke(name, invokeOpts as { body: unknown });
      if (error) return { data: null, error };
      if (data != null) {
        if (ttlMs > 0) memCache.set(key, { data, expiresAt: Date.now() + ttlMs });
        if (persistMs > 0) writePersistent(key, data, persistMs);
      }
      return { data: data as T, error: null };
    } catch (e) {
      return { data: null, error: { message: e instanceof Error ? e.message : String(e) } };
    } finally {
      if (timeoutId) clearTimeout(timeoutId);
      const ended = typeof performance !== "undefined" ? performance.now() : Date.now();
      recordAiCall(name, ended - started);
      inflight.delete(key);
    }
  })();

  inflight.set(key, runner as Promise<InvokeResult<unknown>>);
  return settleWithSignal(runner, options.signal);
}

/** Forget a specific cache entry (or all entries when `name` is omitted). */
export function invalidateAiCache(name?: string): void {
  if (!name) {
    memCache.clear();
    try {
      const keys: string[] = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith(PERSIST_PREFIX)) keys.push(k);
      }
      keys.forEach((k) => localStorage.removeItem(k));
    } catch { /* ignore */ }
    return;
  }
  for (const k of Array.from(memCache.keys())) {
    if (k.startsWith(name + ":")) memCache.delete(k);
  }
  try {
    const prefix = PERSIST_PREFIX + name + ":";
    const keys: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith(prefix)) keys.push(k);
    }
    keys.forEach((k) => localStorage.removeItem(k));
  } catch { /* ignore */ }
}

type AiFlagName = "aiRescueV2" | "aiFocusRuntime" | "aiWeeklyMemory";

const KEY = "dd_ai_flags";
const EVENTS_KEY = "dd_ai_events";

function hashString(input: string): number {
  let h = 0;
  for (let i = 0; i < input.length; i++) {
    h = (h << 5) - h + input.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h);
}

function rolloutPctFor(flag: AiFlagName): number {
  const envValue = import.meta.env[`VITE_AI_${flag.toUpperCase()}_ROLLOUT` as keyof ImportMetaEnv] as string | undefined;
  const parsed = Number(envValue);
  if (Number.isFinite(parsed)) return Math.max(0, Math.min(100, parsed));
  return 20;
}

export function isAiFlagEnabled(flag: AiFlagName, userId?: string | null): boolean {
  try {
    const saved = localStorage.getItem(KEY);
    if (saved) {
      const obj = JSON.parse(saved) as Partial<Record<AiFlagName, boolean>>;
      if (typeof obj[flag] === "boolean") return !!obj[flag];
    }
  } catch {
    // ignore storage
  }
  if (!userId) return false;
  const bucket = hashString(`${userId}:${flag}`) % 100;
  return bucket < rolloutPctFor(flag);
}

export function setAiFlagOverride(flag: AiFlagName, enabled: boolean): void {
  try {
    const raw = localStorage.getItem(KEY);
    const obj = raw ? (JSON.parse(raw) as Partial<Record<AiFlagName, boolean>>) : {};
    obj[flag] = enabled;
    localStorage.setItem(KEY, JSON.stringify(obj));
  } catch {
    // ignore
  }
}

export function trackAiEvent(name: string, payload?: Record<string, unknown>): void {
  try {
    const raw = localStorage.getItem(EVENTS_KEY);
    const events = raw ? (JSON.parse(raw) as any[]) : [];
    events.push({ name, payload: payload || {}, ts: new Date().toISOString() });
    if (events.length > 200) events.splice(0, events.length - 200);
    localStorage.setItem(EVENTS_KEY, JSON.stringify(events));
  } catch {
    // ignore
  }
  console.info("[ai-event]", name, payload || {});
}

export type AiWeeklyMemory = {
  generated_at: string;
  best_focus_hours: string;
  realistic_block_min: number;
  common_slip: string;
  recommendation: string;
};

const MEMORY_KEY = "dd_ai_weekly_memory";

export function readAiWeeklyMemory(): AiWeeklyMemory | null {
  try {
    const raw = localStorage.getItem(MEMORY_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as AiWeeklyMemory;
    if (!parsed || typeof parsed !== "object") return null;
    return parsed;
  } catch {
    return null;
  }
}

export function writeAiWeeklyMemory(memory: AiWeeklyMemory): void {
  try {
    localStorage.setItem(MEMORY_KEY, JSON.stringify(memory));
  } catch {
    // ignore
  }
}

import { supabase } from "@/integrations/supabase/client";
import { recordAiCall } from "@/lib/perfMonitor";
import { devSimulateProHeaders } from "@/lib/devEntitlement";

/**
 * Streaming wrapper for Supabase Edge Functions.
 *
 * Designed so the edge function can opt in to streaming (NDJSON: one
 * newline-delimited JSON object per chunk) without breaking existing
 * non-streaming callers.
 *
 * Usage on the client:
 *
 *   await streamAi("generate-plan", payload, {
 *     onBlock: (b) => appendOptimisticBlock(b),
 *     onDone:  (final) => persistPlan(final),
 *   });
 *
 * Server-side (edge function) opts in by returning
 * `Content-Type: application/x-ndjson` and writing `JSON.stringify(obj) + "\n"`
 * for each block; the final summary object goes last with `{ done: true, ... }`.
 *
 * If the response isn't NDJSON (older edge function version, or any
 * non-streaming function), we fall back to parsing the whole body as JSON
 * and surfacing `{ blocks: [...] }` chunks via `onBlock`, then `onDone` with
 * the full payload. So callers can adopt this helper without depending on
 * server-side changes landing first.
 */
export type StreamOptions<TBlock = unknown, TFinal = unknown> = {
  onBlock?: (block: TBlock, index: number) => void;
  onDone?: (final: TFinal) => void;
  onError?: (error: Error) => void;
  signal?: AbortSignal;
};

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL as string | undefined;
const ANON_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string | undefined;

async function authHeader(): Promise<string | null> {
  try {
    const { data } = await supabase.auth.getSession();
    const token = data.session?.access_token;
    return token ? `Bearer ${token}` : ANON_KEY ? `Bearer ${ANON_KEY}` : null;
  } catch {
    return ANON_KEY ? `Bearer ${ANON_KEY}` : null;
  }
}

export async function streamAi<TBlock = any, TFinal = any>(
  functionName: string,
  body: unknown,
  options: StreamOptions<TBlock, TFinal> = {},
): Promise<TFinal | null> {
  if (!SUPABASE_URL || !ANON_KEY) {
    options.onError?.(new Error("Supabase env missing"));
    return null;
  }
  const url = `${SUPABASE_URL}/functions/v1/${functionName}`;
  const auth = await authHeader();
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    apikey: ANON_KEY,
    accept: "application/x-ndjson, application/json",
  };
  if (auth) headers.Authorization = auth;
  // Dev-only: forward Simulate Pro flag so the edge function bypasses
  // subscription checks. Empty in production.
  Object.assign(headers, devSimulateProHeaders());

  const started = typeof performance !== "undefined" ? performance.now() : Date.now();
  let response: Response;
  try {
    response = await fetch(url, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
      signal: options.signal,
    });
  } catch (e) {
    const err = e instanceof Error ? e : new Error(String(e));
    options.onError?.(err);
    return null;
  }

  if (!response.ok) {
    const err = new Error(`${functionName} failed: ${response.status}`);
    options.onError?.(err);
    return null;
  }

  const contentType = response.headers.get("content-type") || "";
  const isStream =
    contentType.includes("application/x-ndjson") || contentType.includes("text/event-stream");

  try {
    if (isStream && response.body) {
      const final = await consumeNdjson<TBlock, TFinal>(response.body, options);
      return final;
    }
    // Fallback: non-streaming response. Replay it as a single-chunk stream
    // so callers see the same callback shape.
    const json = (await response.json()) as { blocks?: TBlock[] } & TFinal;
    if (Array.isArray(json?.blocks)) {
      json.blocks.forEach((b: TBlock, i: number) => options.onBlock?.(b, i));
    }
    options.onDone?.(json as TFinal);
    return json as TFinal;
  } catch (e) {
    options.onError?.(e instanceof Error ? e : new Error(String(e)));
    return null;
  } finally {
    const ended = typeof performance !== "undefined" ? performance.now() : Date.now();
    recordAiCall(`${functionName}:stream`, ended - started);
  }
}

async function consumeNdjson<TBlock, TFinal>(
  body: ReadableStream<Uint8Array>,
  options: StreamOptions<TBlock, TFinal>,
): Promise<TFinal | null> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let blockIndex = 0;
  let final: TFinal | null = null;
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let nl = buffer.indexOf("\n");
      while (nl !== -1) {
        const line = buffer.slice(0, nl).trim();
        buffer = buffer.slice(nl + 1);
        if (line) {
          try {
            const obj = JSON.parse(line);
            if (obj && obj.done) {
              final = obj as TFinal;
            } else {
              options.onBlock?.(obj as TBlock, blockIndex++);
            }
          } catch {
            /* skip malformed line — server should be well-behaved */
          }
        }
        nl = buffer.indexOf("\n");
      }
    }
    // Tail flush.
    const tail = buffer.trim();
    if (tail) {
      try {
        const obj = JSON.parse(tail);
        if (obj?.done) final = obj as TFinal;
        else options.onBlock?.(obj as TBlock, blockIndex++);
      } catch {
        /* ignore */
      }
    }
  } finally {
    try { reader.releaseLock(); } catch { /* ignore */ }
  }
  if (final) options.onDone?.(final);
  return final;
}

import { type Block, blockSlotEndHHMM, isOpenUserTask } from "@/lib/daydraft";

/**
 * Local block-start reminders.
 *
 * Schedules in-tab Notifications a few minutes before each upcoming block
 * starts. This is intentionally lightweight: it lives only while the tab is
 * open and silently no-ops if permission isn't granted. For "real" pushes
 * even when the app is closed we'd need the existing push_subscriptions /
 * service-worker pipeline (already wired but VAPID-pending).
 *
 * Per-block configuration:
 *   Users can configure reminders Google-Calendar-style — pick lead times
 *   (e.g. 10 min and 2 min before) and a repeat count (re-fire every N min
 *   after the start until acknowledged or count exhausted). Stored in
 *   localStorage keyed by block id, so it survives reloads but stays
 *   on-device (no extra DB column needed).
 */

const TIMEOUT_HANDLES: number[] = [];
const DEFAULT_LEADS_MIN = [2]; // default: a single nudge 2 min before
const DEFAULT_REPEATS = 0;
const REPEAT_INTERVAL_MIN = 5;

export type ReminderConfig = {
  enabled: boolean;
  leadsMin: number[]; // e.g. [10, 2]
  repeats: number; // re-fire N times after start (every 5 min)
  /** Minutes before block end ("window closing"). Empty = off. Legacy; see endAlertLeadMin. */
  endLeadsMin: number[];
  /** Primary alert this many minutes before the task window ends. */
  endAlertLeadMin: number;
  /** After the primary end alert, fire up to this many extra pings every minute while still before end. */
  endAlertRepeat: number;
};

const KEY = (blockId: string) => `dd_reminders_${blockId}`;

const defaultEndAlert = (): Pick<ReminderConfig, "endLeadsMin" | "endAlertLeadMin" | "endAlertRepeat"> => ({
  endLeadsMin: [2],
  endAlertLeadMin: 5,
  endAlertRepeat: 0,
});

export const getReminderConfig = (blockId: string): ReminderConfig => {
  if (typeof window === "undefined")
    return { enabled: true, leadsMin: DEFAULT_LEADS_MIN, repeats: DEFAULT_REPEATS, ...defaultEndAlert() };
  try {
    const raw = localStorage.getItem(KEY(blockId));
    if (!raw)
      return { enabled: true, leadsMin: DEFAULT_LEADS_MIN, repeats: DEFAULT_REPEATS, ...defaultEndAlert() };
    const parsed = JSON.parse(raw);
    const endLeadsMin = Array.isArray(parsed.endLeadsMin) ? parsed.endLeadsMin : [2];
    const endAlertLeadMin =
      typeof parsed.endAlertLeadMin === "number" && parsed.endAlertLeadMin >= 0
        ? parsed.endAlertLeadMin
        : Math.max(1, ...(endLeadsMin as number[]));
    const endAlertRepeat =
      typeof parsed.endAlertRepeat === "number" && parsed.endAlertRepeat >= 0 ? parsed.endAlertRepeat : 0;
    return {
      enabled: parsed.enabled !== false,
      leadsMin: Array.isArray(parsed.leadsMin) && parsed.leadsMin.length ? parsed.leadsMin : DEFAULT_LEADS_MIN,
      repeats: typeof parsed.repeats === "number" ? parsed.repeats : DEFAULT_REPEATS,
      endLeadsMin,
      endAlertLeadMin,
      endAlertRepeat,
    };
  } catch {
    return { enabled: true, leadsMin: DEFAULT_LEADS_MIN, repeats: DEFAULT_REPEATS, ...defaultEndAlert() };
  }
};

export const setReminderConfig = (blockId: string, cfg: ReminderConfig) => {
  if (typeof window === "undefined") return;
  try { localStorage.setItem(KEY(blockId), JSON.stringify(cfg)); } catch {/* ignore */}
};

export const clearScheduledReminders = () => {
  while (TIMEOUT_HANDLES.length) {
    const h = TIMEOUT_HANDLES.pop();
    if (h != null) clearTimeout(h);
  }
};

export const ensureNotificationPermission = async (): Promise<boolean> => {
  if (typeof window === "undefined" || !("Notification" in window)) return false;
  if (Notification.permission === "granted") return true;
  if (Notification.permission === "denied") return false;
  try {
    const res = await Notification.requestPermission();
    return res === "granted";
  } catch {
    return false;
  }
};

const fire = (title: string, body: string) => {
  if (typeof window === "undefined" || !("Notification" in window)) return;
  if (Notification.permission !== "granted") return;
  try {
    new Notification(title, {
      body,
      icon: "/placeholder.svg",
      tag: `block-${title}`,
      // `renotify` is not in the standard TS lib type, but supported by most
      // browsers — cast to any so re-firing reminders surface a fresh ping.
      ...({ renotify: true } as any),
    });
  } catch { /* some browsers throw inside iframes */ }
};

/**
 * Schedules reminders for blocks that start later today. Pass `{ planDate }`
 * with the block's date string (yyyy-mm-dd); we only schedule if it's today,
 * because setTimeout can't span hours of background tab time reliably.
 */
export const scheduleBlockReminders = (
  blocks: Block[],
  opts: { planDate: string },
) => {
  clearScheduledReminders();
  const today = new Date();
  const ymd = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
  if (opts.planDate !== ymd) return;
  if (typeof window === "undefined" || !("Notification" in window)) return;
  if (Notification.permission !== "granted") return;

  const now = Date.now();
  blocks.forEach((b: any) => {
    if (b.completed) return;
    if (b.kind === "task" && !b.is_calendar_event && !isOpenUserTask(b)) return;
    if (b.kind !== "task" && b.kind !== "lunch" && b.kind !== "break") {
      // also skip calendar events — the user's calendar handles those.
      if (!b.is_calendar_event) return;
    }
    const cfg = getReminderConfig(b.id);
    if (!cfg.enabled) return;
    const [h, m] = (b.start_time || "00:00").split(":").map(Number);
    if (Number.isNaN(h) || Number.isNaN(m)) return;
    const startMs = new Date(today.getFullYear(), today.getMonth(), today.getDate(), h, m, 0).getTime();

    const schedule = (fireAt: number, label: string) => {
      const delay = fireAt - now;
      if (delay <= 0) return;
      if (delay > 6 * 60 * 60_000) return; // setTimeout drift beyond 6h
      const handle = window.setTimeout(() => {
        fire(`Up next: ${b.title}`, label);
      }, delay);
      TIMEOUT_HANDLES.push(handle);
    };

    cfg.leadsMin.forEach((lead) => {
      schedule(startMs - lead * 60_000, `In ${lead} min · ${b.start_time} · ${b.duration_min} min`);
    });
    const [eh, emin] = blockSlotEndHHMM(b as Block).split(":").map(Number);
    const endMs = new Date(today.getFullYear(), today.getMonth(), today.getDate(), eh || 0, emin || 0, 0).getTime();
    const leadMin = typeof cfg.endAlertLeadMin === "number" ? cfg.endAlertLeadMin : 5;
    const endRepeat = typeof cfg.endAlertRepeat === "number" ? cfg.endAlertRepeat : 0;
    const primaryEndPing = endMs - leadMin * 60_000;
    if (leadMin === 0) {
      schedule(endMs, `Window ends · ${b.title} · ${fmtEndClock(endMs)}`);
    } else {
      schedule(primaryEndPing, `Window ends in ${leadMin} min · ${b.title} · ${fmtEndClock(endMs)}`);
      for (let i = 1; i <= endRepeat; i++) {
        const t = primaryEndPing + i * 60_000;
        if (t >= endMs) break;
        schedule(t, `Reminder · ${b.title} · ends ${fmtEndClock(endMs)}`);
      }
    }
    for (let i = 1; i <= cfg.repeats; i++) {
      schedule(startMs + i * REPEAT_INTERVAL_MIN * 60_000, `Reminder · started at ${b.start_time}`);
    }
  });
};

function fmtEndClock(endMs: number) {
  try {
    const d = new Date(endMs);
    return d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }).replace(/\s/g, "").toLowerCase();
  } catch {
    return "";
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import type { Block } from "@/lib/daydraft";
import { blockSlotEndHHMM, isOpenUserTask, todayDateStr, wallMsOnPlanDay } from "@/lib/daydraft";

/**
 * User tasks whose planned window has ended but are still "open" → mark missed (idempotent).
 * Returns true if any row was updated.
 */
export async function applyAutoMissedBlocks(
  supabase: SupabaseClient,
  planDateYmd: string,
  blocks: Block[],
): Promise<boolean> {
  // Policy: only write missed for the *current* day. Past plans are shown read-only in UI
  // to avoid retroactively mutating history when a user revisits an old date.
  if (planDateYmd !== todayDateStr()) return false;

  const now = Date.now();
  // Grace: only auto-mark missed when the block existed before its slot end.
  // Without this, creating a plan retroactively (e.g. typing tasks at 21:00
  // with default 09:00 starts) instantly marks every block "missed".
  const GRACE_MS = 60_000;
  const ids = blocks
    .filter((b) => {
      if (!isOpenUserTask(b)) return false;
      const endMs = wallMsOnPlanDay(planDateYmd, blockSlotEndHHMM(b));
      if (endMs >= now) return false;
      const createdAtRaw = (b as any).created_at as string | undefined;
      const createdMs = createdAtRaw ? Date.parse(createdAtRaw) : NaN;
      // If we don't know when it was created, be conservative — don't mark missed.
      if (!Number.isFinite(createdMs)) return false;
      // Skip blocks whose entire window was already in the past at creation time.
      return createdMs + GRACE_MS < endMs;
    })
    .map((b) => b.id);
  if (!ids.length) return false;
  const iso = new Date().toISOString();
  const { error } = await supabase
    .from("blocks")
    .update({ resolution: "missed", resolved_at: iso, completed: false })
    .in("id", ids);
  if (error) {
    console.error(error);
    return false;
  }
  return true;
}

/**
 * Haptic feedback wrapper.
 *
 * Priority order:
 *   1. Native iOS / Android via `@capacitor/haptics` when running inside
 *      Capacitor and the plugin is installed (best feel — real Taptic
 *      Engine vibrations).
 *   2. `navigator.vibrate` on Android Chrome / supported browsers.
 *   3. No-op everywhere else (iOS Safari ignores `navigator.vibrate`
 *      silently; doing nothing is the right behaviour there).
 *
 * The Capacitor call is wrapped in a dynamic import that fails closed,
 * so this file builds and runs whether or not `@capacitor/haptics` is
 * in `package.json` yet. Install the plugin (`npm i @capacitor/haptics`
 * + `npx cap sync ios`) to light up real iOS haptics — no code changes
 * needed in callers.
 */

type Impact = "light" | "medium" | "heavy";
type Notify = "success" | "warning" | "error";

// Cached plugin module reference. `undefined` = not yet probed, `null` =
// probed and unavailable, otherwise the live module.
let capPluginCache: { impact: (o: { style: string }) => unknown; notification: (o: { type: string }) => unknown; selection: () => unknown } | null | undefined;

const isNative = (): boolean => {
  try {
    // Avoid a hard import; Capacitor core is always present in this app.
    const w = window as unknown as { Capacitor?: { isNativePlatform?: () => boolean } };
    return !!w.Capacitor?.isNativePlatform?.();
  } catch { return false; }
};

const getCapPlugin = async () => {
  if (capPluginCache !== undefined) return capPluginCache;
  if (!isNative()) { capPluginCache = null; return null; }
  try {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore — optional dependency; resolves only when installed.
    const mod = await import("@capacitor/haptics");
    capPluginCache = (mod?.Haptics as any) || null;
  } catch {
    capPluginCache = null;
  }
  return capPluginCache;
};

const vibrate = (pattern: number | number[]) => {
  try { navigator.vibrate?.(pattern); } catch { /* ignore */ }
};

const fireCapImpact = async (style: Impact) => {
  const p = await getCapPlugin();
  if (!p) return false;
  try {
    const map = { light: "LIGHT", medium: "MEDIUM", heavy: "HEAVY" } as const;
    await p.impact({ style: map[style] });
    return true;
  } catch { return false; }
};

const fireCapNotify = async (type: Notify) => {
  const p = await getCapPlugin();
  if (!p) return false;
  try {
    const map = { success: "SUCCESS", warning: "WARNING", error: "ERROR" } as const;
    await p.notification({ type: map[type] });
    return true;
  } catch { return false; }
};

const fireCapSelection = async () => {
  const p = await getCapPlugin();
  if (!p) return false;
  try { await p.selection(); return true; } catch { return false; }
};

export const haptics = {
  /** Light tap — buttons, toggles, navigation. */
  tap: () => {
    void fireCapImpact("light").then((ok) => { if (!ok) vibrate(8); });
  },
  impact: (style: Impact = "medium") => {
    void fireCapImpact(style).then((ok) => {
      if (ok) return;
      const ms = style === "light" ? 8 : style === "heavy" ? 25 : 14;
      vibrate(ms);
    });
  },
  /** Success / warning / error pattern — completion, errors. */
  notify: (type: Notify = "success") => {
    void fireCapNotify(type).then((ok) => {
      if (ok) return;
      const patterns: Record<Notify, number[]> = {
        success: [10, 40, 18],
        warning: [12, 60, 12],
        error: [20, 50, 20, 50, 20],
      };
      vibrate(patterns[type]);
    });
  },
  /** Selection change — picker, segment switch. */
  selection: () => {
    void fireCapSelection().then((ok) => { if (!ok) vibrate(5); });
  },
};

import { lazy, type ComponentType } from "react";

/**
 * Wraps `React.lazy()` so a stale browser tab that references a chunk hash
 * which no longer exists on the CDN (after a deploy) recovers by reloading
 * once, instead of leaving the user on the "Importing a module script failed"
 * error boundary screen.
 *
 * IMPORTANT: gate the reload by a timestamp, not by a flag-cleared-on-load.
 * Clearing on `window.load` causes an infinite reload loop whenever the chunk
 * failure is persistent (e.g. preview env, offline, blocked CDN).
 */
const RELOAD_KEY = "dd_chunk_reload_at";
const RELOAD_COOLDOWN_MS = 60_000;

export function lazyWithReload<T extends { default: ComponentType<any> }>(
  factory: () => Promise<T>,
) {
  return lazy(() =>
    factory().catch((err) => {
      const msg = String(err?.message || err || "");
      const isChunkErr =
        /Importing a module script failed|Failed to fetch dynamically imported module|ChunkLoadError|Loading chunk/i.test(
          msg,
        );
      if (isChunkErr && typeof window !== "undefined") {
        try {
          const last = Number(sessionStorage.getItem(RELOAD_KEY) || 0);
          const now = Date.now();
          if (!last || now - last > RELOAD_COOLDOWN_MS) {
            sessionStorage.setItem(RELOAD_KEY, String(now));
            window.location.reload();
            return new Promise(() => {}) as Promise<T>;
          }
        } catch {
          // ignore storage errors and fall through to re-throw
        }
      }
      throw err;
    }),
  );
}

export const isIOS = () => {
  if (typeof navigator === "undefined") return false;
  return /iPhone|iPad|iPod/.test(navigator.userAgent) ||
    (navigator.platform === "MacIntel" && (navigator as any).maxTouchPoints > 1);
};

export const mapsUrl = (location: string, lat?: number | null, lng?: number | null) => {
  const dest = lat != null && lng != null ? `${lat},${lng}` : location;
  const enc = encodeURIComponent(dest);
  if (isIOS()) return `https://maps.apple.com/?daddr=${enc}&dirflg=d`;
  return `https://www.google.com/maps/dir/?api=1&destination=${enc}`;
};

import { Capacitor } from "@capacitor/core";
import { SocialLogin } from "@capgo/capacitor-social-login";
import { supabase } from "@/integrations/supabase/client";

/**
 * Native iOS/Android sign-in for Google and Apple.
 *
 * Browser-broker OAuth (the existing `@lovable.dev/cloud-auth-js` path)
 * doesn't work inside a Capacitor WebView because the broker can't
 * redirect back to `capacitor://localhost`. Instead we let the native
 * platform present its own sign-in sheet (Apple's system dialog / Google's
 * native flow), receive an *identity token* + nonce, and hand it to
 * Supabase via `signInWithIdToken`. Supabase verifies the token against
 * the provider and creates the session — no broker round-trip needed.
 *
 * The web build keeps using the Lovable broker (better UX in browsers,
 * already works). Only native iOS/Android calls into this module.
 *
 * Required configuration the user must do once, outside the code:
 *   1. Apple Developer:
 *      - Enable "Sign In with Apple" on the App ID (`dev.daydraft.app`).
 *      - Create a Services ID + key for Supabase's Apple provider.
 *      - Xcode: add the "Sign in with Apple" capability (Targets → App →
 *        Signing & Capabilities → "+ Capability").
 *   2. Google Cloud Console:
 *      - Create an OAuth 2.0 client of type "iOS" with bundle ID
 *        `dev.daydraft.app`. Note the Client ID and the reversed URL
 *        scheme.
 *      - Add the reversed scheme to `ios/App/App/Info.plist`
 *        (placeholder block already added).
 *      - Set `VITE_GOOGLE_IOS_CLIENT_ID` in the env so the plugin can
 *        request the right token audience.
 *   3. Supabase Auth dashboard:
 *      - Enable Apple provider (paste Service ID + private key).
 *      - Enable Google provider (paste Web client ID). In the "Authorized
 *        client IDs" field add the iOS client ID too, so tokens minted by
 *        the iOS app are accepted.
 */

let initialized = false;

const GOOGLE_IOS_CLIENT_ID = import.meta.env.VITE_GOOGLE_IOS_CLIENT_ID as string | undefined;

/** Idempotent — safe to call from many entry points. Runs once per app session. */
async function ensureInitialized(): Promise<void> {
  if (initialized) return;
  if (!Capacitor.isNativePlatform()) {
    initialized = true;
    return;
  }
  console.info("[nativeAuth] initializing SocialLogin plugin", {
    googleConfigured: !!GOOGLE_IOS_CLIENT_ID,
  });
  try {
    await SocialLogin.initialize({
      google: GOOGLE_IOS_CLIENT_ID
        ? {
            // Used to request an ID token whose audience matches the iOS
            // client. Supabase's Google provider must list this client ID
            // in its "Authorized client IDs" field.
            iOSClientId: GOOGLE_IOS_CLIENT_ID,
            // The mode determines what we receive. "online" returns an
            // accessToken + idToken — Supabase needs the idToken.
            mode: "online",
          }
        : undefined,
      // Apple needs no init config on iOS — the system handles it.
      apple: {},
    });
    initialized = true;
    console.info("[nativeAuth] SocialLogin plugin initialized");
  } catch (e) {
    // Initialization failures are rare but possible on the simulator
    // without proper bundle configuration. Surface as a normal error to
    // the caller so the UI can fall back gracefully.
    initialized = false;
    console.error("[nativeAuth] SocialLogin.initialize failed", e);
    throw e instanceof Error ? e : new Error(String(e));
  }
}

export function isNativeAuthAvailable(): boolean {
  return Capacitor.isNativePlatform();
}

export function isNativeGoogleConfigured(): boolean {
  return Capacitor.isNativePlatform() && !!GOOGLE_IOS_CLIENT_ID;
}

/**
 * Native Google sign-in. Returns the Supabase session result (same shape
 * as `supabase.auth.signInWithIdToken`).
 *
 * Nonce protocol — same as Apple (see `signInWithAppleNative` for the
 * detailed explanation). Modern `GoogleSignIn` iOS SDK ALSO includes a
 * `nonce` claim in the id_token even when one isn't requested explicitly
 * — and Supabase, when it sees a nonce in the id_token, *requires* a
 * matching `nonce` param on the request. Otherwise:
 *   "passed nonce and nonce in id_token should either both exist or not"
 *
 * The fix: hand the plugin a SHA-256 hash of our raw nonce; the plugin
 * forwards it to Google, Google embeds it verbatim in the id_token's
 * nonce claim. Then we pass the raw nonce to Supabase, Supabase hashes
 * it server-side and the two hashes match.
 */
export async function signInWithGoogleNative(): Promise<{ error?: Error | null }> {
  if (!Capacitor.isNativePlatform()) {
    return { error: new Error("Native Google sign-in is only available on iOS / Android") };
  }
  if (!GOOGLE_IOS_CLIENT_ID) {
    return { error: new Error("Google sign-in isn't configured for this build (missing VITE_GOOGLE_IOS_CLIENT_ID)") };
  }
  try {
    await ensureInitialized();
    /**
     * No nonce in this flow — intentional.
     *
     * GoogleSignIn-iOS 9.x uses OAuth code flow internally
     * (`OIDResponseTypeCode` in GIDSignIn.m). Google's token endpoint
     * does NOT echo the authorization-request nonce back into the
     * resulting id_token under code flow — so whatever we send via the
     * SDK's `nonce:` parameter is silently dropped. Empirically
     * confirmed: even with a SHA-256/base64url hashed nonce, the
     * returned id_token has no `nonce` claim (see debug log below).
     *
     * supabase-js's client-side check is
     * `Boolean(nonceParam) === Boolean(idToken.nonce)` — so the safe
     * configuration is "neither side has a nonce". We give up nonce-
     * based replay protection for this provider; the rest of OIDC
     * code-flow security (PKCE, audience verification, signature
     * verification of the id_token via Google's JWKS) is unaffected.
     *
     * If Google fixes nonce round-tripping in a future OIDC flow, the
     * branch below re-adds nonce when the returned token actually
     * contains one.
     */
    console.info("[nativeAuth] Google: calling SocialLogin.login");
    const res = await SocialLogin.login({
      provider: "google",
      options: {
        // Request the standard set so Supabase can build a profile.
        scopes: ["email", "profile"],
      },
    });
    const idToken = (res as any)?.result?.idToken as string | undefined;
    const claims = idToken ? decodeJwtPayload(idToken) : null;
    const tokenNonce = typeof claims?.nonce === "string" ? (claims.nonce as string) : undefined;
    console.info("[nativeAuth] Google: plugin returned", {
      hasIdToken: !!idToken,
      tokenAud: claims?.aud,
      tokenNoncePresent: !!tokenNonce,
    });
    if (!idToken) {
      return { error: new Error("Google sign-in didn't return an ID token") };
    }
    const { error } = await supabase.auth.signInWithIdToken({
      provider: "google",
      token: idToken,
      // Only forward a nonce if the token actually has one. The current
      // GoogleSignIn 9.x code flow does NOT include one, so this branch
      // is dormant — kept defensively in case the SDK starts populating
      // it after a future Google change.
      ...(tokenNonce ? { nonce: tokenNonce } : {}),
    });
    if (error) console.error("[nativeAuth] Google: signInWithIdToken error", error);
    else console.info("[nativeAuth] Google: signInWithIdToken ok");
    return { error: error ?? null };
  } catch (e) {
    console.error("[nativeAuth] Google: caught error", e);
    return { error: e instanceof Error ? e : new Error(String(e)) };
  }
}

/**
 * Native Apple sign-in. Apple's system sheet handles the entire flow.
 * Identity token comes back signed by Apple; Supabase verifies it.
 *
 * Nonce protocol — the part you'll get wrong twice if you don't read this:
 *   1. We generate a raw random nonce.
 *   2. We SHA-256 it ourselves to a hex string ("hashedNonce") and pass
 *      THAT to the plugin. The plugin sets `request.nonce = hashedNonce`.
 *      Apple's iOS SDK embeds whatever we hand it *verbatim* in the
 *      `nonce` claim of the id_token.
 *   3. We pass the RAW (un-hashed) nonce to Supabase. Supabase hashes our
 *      raw nonce server-side and compares against the id_token's nonce
 *      claim (which is the hash). Match → session.
 *
 * Why both halves: if we'd passed the raw value to both, Apple would put
 * the raw value in the id_token and Supabase would produce a hash from
 * its own nonce param — mismatch → "passed nonce and nonce in id_token
 * should either both exist or not". This is the exact bug we're fixing.
 */
export async function signInWithAppleNative(): Promise<{ error?: Error | null }> {
  if (!Capacitor.isNativePlatform()) {
    return { error: new Error("Native Apple sign-in is only available on iOS") };
  }
  try {
    await ensureInitialized();
    const rawNonce = generateNonce();
    const hashedNonce = await sha256Base64Url(rawNonce);
    console.info("[nativeAuth] Apple: calling SocialLogin.login", {
      rawNonceLen: rawNonce.length,
      hashedNoncePreview: hashedNonce.slice(0, 12) + "…",
    });
    const res = await SocialLogin.login({
      provider: "apple",
      options: {
        scopes: ["email", "name"],
        nonce: hashedNonce,
      },
    });
    const idToken = (res as any)?.result?.idToken as string | undefined;
    const claims = idToken ? decodeJwtPayload(idToken) : null;
    console.info("[nativeAuth] Apple: plugin returned", {
      hasIdToken: !!idToken,
      tokenAud: claims?.aud,
      tokenNoncePresent: !!claims?.nonce,
      tokenNoncePreview: typeof claims?.nonce === "string" ? (claims.nonce as string).slice(0, 12) + "…" : null,
    });
    if (!idToken) {
      return { error: new Error("Apple sign-in didn't return an ID token") };
    }
    const { error } = await supabase.auth.signInWithIdToken({
      provider: "apple",
      token: idToken,
      nonce: rawNonce,
    });
    if (error) console.error("[nativeAuth] Apple: signInWithIdToken error", error);
    else console.info("[nativeAuth] Apple: signInWithIdToken ok");
    return { error: error ?? null };
  } catch (e) {
    console.error("[nativeAuth] Apple: caught error", e);
    return { error: e instanceof Error ? e : new Error(String(e)) };
  }
}

/** Random URL-safe nonce — input to SHA-256, kept raw to hand to Supabase. */
function generateNonce(length = 32): string {
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  const charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~";
  let out = "";
  for (const b of bytes) out += charset[b % charset.length];
  return out;
}

/**
 * SHA-256 → URL-safe base64 (no padding).
 *
 * Google's OAuth endpoint docs require the nonce to be a "URL-safe base64-
 * encoded SHA-256 hash of a random string" — if you send a different format
 * (e.g. lowercase hex) Google's server silently rejects it, returning an
 * id_token with NO nonce claim. supabase-js then throws "passed nonce and
 * nonce in id_token should either both exist or not" because we sent a
 * nonce but the id_token has none.
 *
 * Apple's auth server also accepts (and round-trips) this format, so using
 * it for both providers keeps the protocol uniform.
 */
async function sha256Base64Url(input: string): Promise<string> {
  const buf = new TextEncoder().encode(input);
  const hashBuf = await crypto.subtle.digest("SHA-256", buf);
  // bytes → base64 → URL-safe → strip "=" padding
  let bin = "";
  const bytes = new Uint8Array(hashBuf);
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/**
 * Best-effort decode of a JWT's payload claims. Returns `null` on any parse
 * failure — used purely for debug logging to confirm what's in the
 * provider-issued token before handing it to Supabase.
 */
function decodeJwtPayload(token: string): Record<string, unknown> | null {
  try {
    const parts = token.split(".");
    if (parts.length !== 3) return null;
    // base64url → base64
    let payload = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    while (payload.length % 4) payload += "=";
    return JSON.parse(atob(payload));
  } catch {
    return null;
  }
}

import { supabase } from "@/integrations/supabase/client";
import { listQueuedWrites, removeQueuedWrite, type QueuedWrite } from "@/lib/idbCache";

/**
 * Drains the offline write queue against Supabase.
 *
 * Anything in the IndexedDB queue is replayed in order. Each successful
 * replay removes the queue entry; failures stay in the queue for the next
 * online event so a flaky network doesn't lose work.
 *
 * Pair with `enqueueWrite` (in idbCache) at the call sites that mutate
 * Supabase. The typical pattern:
 *
 *   try { await supabase.from("...").insert(payload); }
 *   catch { await enqueueWrite({ table: "...", op: "insert", payload }); }
 */
let draining = false;

async function replay(item: QueuedWrite): Promise<boolean> {
  const table = supabase.from(item.table as never) as any;
  try {
    if (item.op === "insert") {
      const { error } = await table.insert(item.payload as never);
      return !error;
    }
    if (item.op === "upsert") {
      const { error } = await table.upsert(item.payload as never);
      return !error;
    }
    if (item.op === "update") {
      let q = table.update(item.payload as never);
      for (const [k, v] of Object.entries(item.filter || {})) q = q.eq(k, v);
      const { error } = await q;
      return !error;
    }
    if (item.op === "delete") {
      let q = table.delete();
      for (const [k, v] of Object.entries(item.filter || {})) q = q.eq(k, v);
      const { error } = await q;
      return !error;
    }
  } catch {
    return false;
  }
  return false;
}

export async function drainOfflineQueue(): Promise<{ replayed: number; remaining: number }> {
  if (draining) return { replayed: 0, remaining: 0 };
  draining = true;
  let replayed = 0;
  try {
    const queue = await listQueuedWrites();
    for (const item of queue) {
      if (!item.id) continue;
      const ok = await replay(item);
      if (ok) {
        await removeQueuedWrite(item.id);
        replayed += 1;
      }
    }
    const remaining = (await listQueuedWrites()).length;
    return { replayed, remaining };
  } finally {
    draining = false;
  }
}

let listening = false;
export function startOfflineQueueDrainer(): () => void {
  if (typeof window === "undefined" || listening) return () => {};
  listening = true;
  const onOnline = () => { void drainOfflineQueue(); };
  window.addEventListener("online", onOnline);
  // Best-effort drain on boot in case we missed an `online` event between
  // sessions.
  if (navigator.onLine) void drainOfflineQueue();
  return () => {
    window.removeEventListener("online", onOnline);
    listening = false;
  };
}

import { supabase } from "@/integrations/supabase/client";
import type { Block } from "@/lib/daydraft";

export {
  PLAN_DASHBOARD_ROOT,
  PLAN_DAY_ROOT,
  planDashboardQueryKey,
  planDayQueryKey,
} from "@/lib/planQueryKeys";

export type PlanDashboardData = {
  hasPlanForDate: boolean;
  planId: string | null;
  planBlocks: Block[];
  planSummary: string | null;
};

export type DayPlanData = {
  plan: { id: string; ai_summary: string | null; ai_subtext: string | null } | null;
  blocks: Block[];
};

/**
 * Single round-trip for Today glance: plan row + ordered blocks.
 *
 * Uses a PostgREST nested select so the blocks ride back on the plan row,
 * collapsing the previous two sequential queries into one. The previous
 * code fetched the plan, then on success fetched its blocks — two RTTs
 * even though the second one only needed the first one's id.
 */
export async function fetchPlanDashboard(userId: string, date: string): Promise<PlanDashboardData> {
  const { data: p, error: planError } = await supabase
    .from("plans")
    .select("id, ai_summary, blocks(*)")
    .eq("user_id", userId)
    .eq("date", date)
    .order("position", { foreignTable: "blocks" })
    .maybeSingle();
  if (planError) throw planError;
  if (!p) {
    return { hasPlanForDate: false, planId: null, planBlocks: [], planSummary: null };
  }
  const list = (((p as any).blocks ?? []) as Block[]);
  return {
    hasPlanForDate: list.length > 0,
    planId: p.id,
    planBlocks: list,
    planSummary: list.length > 0 ? ((p as any).ai_summary || null) : null,
  };
}

export async function fetchDayPlan(userId: string, date: string): Promise<DayPlanData> {
  const { data: p, error: planError } = await supabase
    .from("plans")
    .select("id, ai_summary, ai_subtext, blocks(*)")
    .eq("user_id", userId)
    .eq("date", date)
    .order("position", { foreignTable: "blocks" })
    .maybeSingle();
  if (planError) throw planError;
  if (!p) return { plan: null, blocks: [] };
  const { blocks: blockList, ...planRow } = p as { blocks: Block[] | null } & {
    id: string;
    ai_summary: string | null;
    ai_subtext: string | null;
  };
  return {
    plan: { id: planRow.id, ai_summary: planRow.ai_summary, ai_subtext: planRow.ai_subtext },
    blocks: (blockList ?? []) as Block[],
  };
}

import { supabase } from "@/integrations/supabase/client";
import { Capacitor } from "@capacitor/core";

export const PUBLIC_VAPID_KEY = import.meta.env.VITE_VAPID_PUBLIC_KEY as string | undefined;

export const pushSupported = () =>
  typeof window !== "undefined" && "serviceWorker" in navigator && "PushManager" in window;

/**
 * Diagnose why notifications aren't available so we can give the user a useful
 * next step instead of a dead-end "not supported" message.
 *
 * Returns:
 *   - "ok"               — web push is wired up and ready to enable
 *   - "needs-install"    — iOS Safari, needs to install as PWA before web push works
 *   - "in-app-browser"   — inside an embedded WebView (lovable.dev preview, social apps)
 *   - "browser-no-support" — browser genuinely doesn't expose PushManager / SW
 *   - "not-configured"   — PushManager is there but the VAPID key isn't wired
 *   - "native-not-wired" — running inside the Capacitor native iOS / Android app,
 *                          but we haven't installed @capacitor/push-notifications yet.
 *                          The native channel uses APNs / FCM, not Web Push.
 */
export type PushAvailability =
  | "ok"
  | "needs-install"
  | "in-app-browser"
  | "browser-no-support"
  | "not-configured"
  | "native-not-wired";

export const pushAvailability = (): PushAvailability => {
  if (typeof window === "undefined") return "browser-no-support";
  // Capacitor native runs inside a WKWebView that does NOT expose `PushManager`
  // — that's the web-only API. Native push needs `@capacitor/push-notifications`
  // talking to APNs (iOS) / FCM (Android), which isn't installed yet. Showing
  // the "Add to Home Screen" copy here would be nonsense (the user already
  // installed the native app).
  if (Capacitor.isNativePlatform()) return "native-not-wired";
  const ua = navigator.userAgent || "";
  const isIos = /iPad|iPhone|iPod/.test(ua);
  // iOS Safari requires the app to be installed to the home screen (standalone)
  // before it exposes a working PushManager. Lovable / in-app browsers never
  // expose it at all.
  const standalone =
    (typeof window.matchMedia === "function" && window.matchMedia("(display-mode: standalone)").matches) ||
    (navigator as unknown as { standalone?: boolean }).standalone === true;
  const inAppBrowserHints = /(Instagram|FBAN|FBAV|Line\/|MicroMessenger|Twitter|TikTok|Lovable)/i.test(ua);
  if (!("serviceWorker" in navigator) || !("PushManager" in window)) {
    if (isIos && !standalone) return "needs-install";
    if (inAppBrowserHints) return "in-app-browser";
    return "browser-no-support";
  }
  if (!PUBLIC_VAPID_KEY) return "not-configured";
  return "ok";
};

export const pushAvailabilityCopy: Record<PushAvailability, { title: string; body: string }> = {
  ok: { title: "Notifications ready", body: "Turn on to get gentle nudges as your day unfolds." },
  "needs-install": {
    title: "Install DayDraft first",
    body: "iOS only sends notifications from installed apps. Tap Share → Add to Home Screen, then open DayDraft from your home screen to enable.",
  },
  "in-app-browser": {
    title: "Open in your browser",
    body: "Notifications don't work inside in-app browsers. Tap the menu and choose \"Open in Safari / Chrome\" to enable.",
  },
  "browser-no-support": {
    title: "Notifications not supported",
    body: "This browser doesn't expose web push. Try the latest Safari, Chrome, or Edge.",
  },
  "not-configured": {
    title: "Coming soon",
    body: "Push isn't wired up in this preview yet. Your reminders still fire while the app is open.",
  },
  "native-not-wired": {
    title: "Coming to the iOS app soon",
    body: "Daily nudges run over APNs on the native app — we haven't wired that channel yet. Open the web app at daydraft.app to enable nudges in the meantime.",
  },
};

const urlBase64ToUint8 = (b64: string) => {
  const padding = "=".repeat((4 - (b64.length % 4)) % 4);
  const base64 = (b64 + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(base64);
  return new Uint8Array([...raw].map(c => c.charCodeAt(0)));
};

export const enablePush = async (userId: string) => {
  if (!pushSupported()) throw new Error("Push not supported on this browser");
  if (!PUBLIC_VAPID_KEY) throw new Error("Push isn't configured yet — VAPID key missing");
  const reg = await navigator.serviceWorker.register("/sw.js");
  const perm = await Notification.requestPermission();
  if (perm !== "granted") throw new Error("Notifications permission denied");
  const existing = await reg.pushManager.getSubscription();
  const sub = existing || await reg.pushManager.subscribe({
    userVisibleOnly: true,
    applicationServerKey: urlBase64ToUint8(PUBLIC_VAPID_KEY),
  });
  const json: any = sub.toJSON();
  const { error } = await supabase
    .from("push_subscriptions")
    .upsert(
      {
        user_id: userId,
        endpoint: json.endpoint,
        p256dh: json.keys.p256dh,
        auth: json.keys.auth,
      } as any,
      { onConflict: "user_id,endpoint", ignoreDuplicates: false }
    );
  if (error) throw error;
};

export const disablePush = async (userId: string) => {
  if (!pushSupported()) return;
  const reg = await navigator.serviceWorker.getRegistration();
  const sub = await reg?.pushManager.getSubscription();
  if (sub) {
    await supabase.from("push_subscriptions").delete().eq("user_id", userId).eq("endpoint", sub.endpoint);
    await sub.unsubscribe();
  }
};

const cleanupTitle = (value: string) =>
  value
    .replace(/^[,.;:!?\-–—•*\d.)\s]+/, "")
    .replace(/[,.;:!?\-–—\s]+$/, "")
    .replace(/\s+/g, " ")
    .trim();

const taskStarterFragments = [
  "сд[еэ]л[а-яё]*", "здел[а-яё]*", "добав[а-яё]*", "убер[а-яё]*", "убрат[а-яё]*", "удал[а-яё]*",
  "исправ[а-яё]*", "поправ[а-яё]*", "почин[а-яё]*", "провер[а-яё]*", "обнов[а-яё]*", "передел[а-яё]*", "настро[а-яё]*",
  "напис[а-яё]*", "ответ(?:ить|ь|им|ите|ил|ила|или|ят)", "отправ[а-яё]*", "позвон[а-яё]*", "созвон[а-яё]*", "встрет[а-яё]*",
  "куп[а-яё]*", "закаж[а-яё]*", "заказ(?:ать|ал|ала|али|ывай[а-яё]*)", "оплат(?:ить|и|им|ите|ил|ила|или|ят)", "выстав[а-яё]*", "забр[а-яё]*", "отнес[а-яё]*",
  "подготов[а-яё]*", "законч[а-яё]*", "разобр[а-яё]*", "собра[а-яё]*", "прочит[а-яё]*", "посмотр[а-яё]*",
  "выда[а-яё]*", "покаж[а-яё]*", "сформир[а-яё]*", "раздел[а-яё]*", "сплит[а-яё]*", "отполир[а-яё]*",
  "заполн[а-яё]*", "загруз[а-яё]*", "скача[а-яё]*", "протест[а-яё]*", "депло[а-яё]*", "заплан[а-яё]*",
  "clean", "fix", "add", "remove", "delete", "write", "reply", "email", "call", "send", "create", "update", "finish",
  "prepare", "review", "check", "test", "deploy", "publish", "pay", "book", "buy", "pick", "research", "design", "record", "edit",
];

const starterSource = taskStarterFragments.join("|");
const starterRe = new RegExp(`(^|\\s)((?:${starterSource})(?=$|[\\s,.;:!?]))`, "giu");
const connectorBeforeStarterRe = new RegExp(
  `\\s+(?:и|and|&|плюс|потом|затем|также|ещ[её]|then|also|plus)\\s+(?=(?:${starterSource})(?=$|[\\s,.;:!?]))`,
  "giu",
);

function splitByRepeatedStarters(part: string): string[] {
  const starts: number[] = [];
  starterRe.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = starterRe.exec(part))) {
    const index = match.index + (match[1]?.length || 0);
    if (index > 0) starts.push(index);
  }
  starterRe.lastIndex = 0;
  if (!starts.length) return [part];
  const cutPoints = [0, ...starts, part.length];
  return cutPoints
    .slice(0, -1)
    .map((start, i) => cleanupTitle(part.slice(start, cutPoints[i + 1])))
    .filter(Boolean);
}

/**
 * Pull a duration ("5 hours", "30 min", "1h 15m", "пол часа") out of a task
 * title and return the cleaned title + minutes. Returns duration=null when
 * the title doesn't carry a duration so the caller can fall back to a
 * default. Conservative — only matches obvious patterns so we don't strip
 * real content like "30 min walk".
 */
export function extractDurationFromTitle(rawTitle: string): { title: string; duration: number | null } {
  const original = rawTitle;
  let minutes = 0;
  let matched = false;

  // Pattern: <num> h/hr/hrs/hour/hours/ч/час/часа/часов (+ optional decimals)
  const hourRe = /(\d+(?:[.,]\d+)?)\s*(?:hours?|hrs?|h|часов|часа|час|ч)\b/gi;
  // Pattern: <num> m/min/mins/minute/minutes/мин/минут
  const minuteRe = /(\d+)\s*(?:minutes?|mins?|minute|m|минут[ауы]?|мин)\b/gi;

  let m: RegExpExecArray | null;
  while ((m = hourRe.exec(original)) !== null) {
    const val = parseFloat(m[1].replace(",", "."));
    if (Number.isFinite(val) && val > 0 && val <= 24) {
      minutes += Math.round(val * 60);
      matched = true;
    }
  }
  while ((m = minuteRe.exec(original)) !== null) {
    const val = parseInt(m[1], 10);
    if (Number.isFinite(val) && val > 0 && val <= 600) {
      minutes += val;
      matched = true;
    }
  }

  // Common natural-language fragments
  const lower = original.toLowerCase();
  if (!matched) {
    if (/\bhalf an hour\b|\bhalf hour\b|пол\s*часа/.test(lower)) { minutes += 30; matched = true; }
    else if (/quarter (?:of an )?hour|четверть\s*часа/.test(lower)) { minutes += 15; matched = true; }
  }

  if (!matched || minutes <= 0) {
    return { title: cleanupTitle(original), duration: null };
  }

  // Strip the matched duration fragments from the title so the row reads cleanly.
  const cleanedTitle = cleanupTitle(
    original
      .replace(hourRe, " ")
      .replace(minuteRe, " ")
      .replace(/\bhalf an hour\b|\bhalf hour\b|пол\s*часа/gi, " ")
      .replace(/quarter (?:of an )?hour|четверть\s*часа/gi, " ")
      // Trailing connectors left behind ("for", "за", "на").
      .replace(/\s+(?:for|за|на)\s*$/i, " ")
      .replace(/\s+/g, " ")
      .trim()
  );

  // Sanity cap (24h) — protect downstream packers from absurd values.
  const capped = Math.min(minutes, 24 * 60);
  return { title: cleanedTitle || cleanupTitle(original), duration: capped };
}

export function parseBulkTasks(input: string): string[] {
  const normalized = input
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(connectorBeforeStarterRe, "\n")
    .replace(/\s+(?:[+\/|]|->|=>)\s+/g, "\n")
    .replace(/\s+[—–]\s+/g, "\n")
    .replace(/\.\s+(?=[A-ZА-ЯЁ])/g, "\n");

  const primary = normalized
    .split(/\r?\n+|[,;•]+|(?:^|\s)[-*]\s+|(?:^|\s)\d+[.)]\s+/g)
    .map(cleanupTitle)
    .filter(Boolean);

  const expanded = primary.flatMap(splitByRepeatedStarters);
  const seen = new Set<string>();
  return expanded
    .filter((title) => {
      const key = title.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 40);
}

import { createContext, useContext, useEffect, useState, ReactNode } from "react";
import { supabase } from "@/integrations/supabase/client";

export type Theme = "system" | "light" | "dark";

interface Ctx {
  theme: Theme;
  resolved: "light" | "dark";
  setTheme: (t: Theme) => void;
}

const ThemeCtx = createContext<Ctx>({ theme: "system", resolved: "light", setTheme: () => {} });

const STORAGE_KEY = "daydraft.theme";

const applyTheme = (theme: Theme): "light" | "dark" => {
  // Dark-first product. "system" still respects OS, but dark is the default
  // when user has expressed no preference yet.
  const sys = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "dark";
  const resolved = theme === "system" ? sys : theme;
  const root = document.documentElement;
  root.classList.remove("light", "dark");
  root.classList.add(resolved);
  return resolved;
};

export const ThemeProvider = ({ children }: { children: ReactNode }) => {
  const [theme, setThemeState] = useState<Theme>(() => {
    if (typeof window === "undefined") return "system";
    // Safari private browsing throws on every localStorage read; fall back
    // to "system" so the app still mounts.
    try {
      return (localStorage.getItem(STORAGE_KEY) as Theme) || "system";
    } catch {
      return "system";
    }
  });
  const [resolved, setResolved] = useState<"light" | "dark">("dark");

  useEffect(() => {
    setResolved(applyTheme(theme));
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onChange = () => { if (theme === "system") setResolved(applyTheme("system")); };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, [theme]);

  // Hydrate from profile once user is loaded
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.user || cancelled) return;
      const { data } = await supabase.from("profiles").select("theme").eq("id", session.user.id).maybeSingle();
      const t = (data as any)?.theme as Theme | undefined;
      if (t && t !== theme) setThemeState(t);
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const setTheme = (t: Theme) => {
    setThemeState(t);
    try { localStorage.setItem(STORAGE_KEY, t); } catch { /* private mode / quota */ }
    supabase.auth.getSession().then(({ data }) => {
      if (data.session?.user) {
        supabase.from("profiles").update({ theme: t } as any).eq("id", data.session.user.id).then(() => {});
      }
    });
  };

  return <ThemeCtx.Provider value={{ theme, resolved, setTheme }}>{children}</ThemeCtx.Provider>;
};

export const useTheme = () => useContext(ThemeCtx);

import { forwardRef, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { lovable } from "@/integrations/lovable";
import {
  isNativeAuthAvailable,
  isNativeGoogleConfigured,
  signInWithAppleNative,
  signInWithGoogleNative,
} from "@/lib/nativeAuth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { PageFallback } from "@/components/app/PageFallback";
import { toast } from "sonner";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "@/hooks/useAuth";
import { useProfile } from "@/hooks/useProfile";
import { Fingerprint } from "lucide-react";
import { getStoredPasskey, passkeySupported, verifyPasskey } from "@/lib/passkeys";

export default function Auth() {
  const { user, loading } = useAuth();
  const { profile, loading: profileLoading } = useProfile();
  const [mode, setMode] = useState<"signin" | "signup">("signup");
  const [email, setEmail] = useState("");
  const [pw, setPw] = useState("");
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [awaitingConfirmation, setAwaitingConfirmation] = useState(false);
  const [confirmedFor, setConfirmedFor] = useState<string>("");
  const [resending, setResending] = useState(false);
  const nav = useNavigate();
  const stored = typeof window !== "undefined" ? getStoredPasskey() : null;
  const canUsePasskey = passkeySupported() && !!stored;

  useEffect(() => {
    if (loading || (user && profileLoading)) return;
    if (!user) return;
    // Only send the user straight to /today when we're confident they're
    // already onboarded. For fresh sign-ups the profile row might not have
    // propagated yet (trigger race or Lovable preview slowness) — onboarding
    // upserts on commit, so routing there first is the safe default. The
    // sticky localStorage flag also counts as onboarded so a flaky profile
    // fetch can't re-route a returning user through onboarding.
    let stickyOnboarded = false;
    try {
      stickyOnboarded = localStorage.getItem(`dd_onboarded_uid_${user.id}`) === "1";
    } catch { /* ignore */ }
    const onboarded = profile?.onboarded === true || stickyOnboarded;
    nav(onboarded ? "/today" : "/onboarding", { replace: true });
  }, [loading, nav, profile?.onboarded, profileLoading, user]);

  const getErrorMessage = (message: string) => {
    if (/(leaked|breach|pwned|compromised)/i.test(message)) {
      return "This password has appeared in known data breaches. Please choose a stronger one.";
    }
    return message;
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    try {
      if (mode === "signup") {
        const { data, error } = await supabase.auth.signUp({
          email, password: pw,
          options: { emailRedirectTo: window.location.origin, data: { display_name: name || email.split("@")[0] } },
        });
        if (error) throw error;
        if (data.session) {
          toast.success("Welcome to DayDraft");
          nav("/onboarding");
        } else {
          setAwaitingConfirmation(true);
          setConfirmedFor(email);
          toast.success("Check your email to confirm your account");
        }
      } else {
        const { error } = await supabase.auth.signInWithPassword({ email, password: pw });
        if (error) throw error;
        nav("/today");
      }
    } catch (err: any) {
      toast.error(getErrorMessage(err.message || "Something went wrong"));
    } finally { setBusy(false); }
  };

  const resendConfirmation = async () => {
    if (!email) return;
    setResending(true);
    try {
      const { error } = await supabase.auth.resend({
        type: "signup",
        email,
        options: { emailRedirectTo: window.location.origin },
      });
      if (error) throw error;
      toast.success("Confirmation email sent again");
    } catch (err: any) {
      toast.error(getErrorMessage(err.message || "Something went wrong"));
    } finally {
      setResending(false);
    }
  };

  // OAuth has two distinct paths now, picked at click time:
  //
  //   • Web (browser): goes through the Lovable OAuth broker
  //     (oauth.lovable.app), which redirects back to `window.location.origin`.
  //     This is what's wired today and works for any real https origin.
  //   • Native (Capacitor iOS/Android): uses the native sign-in sheet via
  //     `@capgo/capacitor-social-login`, gets an identity token, and exchanges
  //     it for a Supabase session via `signInWithIdToken`. No broker, no
  //     redirect — fixes the "404 inside the WebView" dead-end the broker hit
  //     when trying to round-trip to `capacitor://localhost`.
  //
  // The Lovable preview (`lovable.dev`) is still blocked because the broker
  // refuses to round-trip to that host either; users there can use email +
  // password or open the deployed app.
  const oauthBlockedReason = (() => {
    if (typeof window === "undefined") return null;
    // Native path is fine — don't block.
    if (isNativeAuthAvailable()) return null;
    try {
      const host = window.location.hostname;
      if (host.includes("lovable") || host.includes("localhost")) {
        return "Google / Apple sign-in only works on the published app URL — not inside the Lovable preview or localhost. Use email & password here, or open the live app to use OAuth.";
      }
    } catch { /* ignore */ }
    return null;
  })();

  const oauth = async (provider: "google" | "apple") => {
    console.info(`[auth] oauth tap`, { provider, native: isNativeAuthAvailable(), blocked: oauthBlockedReason });
    if (oauthBlockedReason) {
      toast(oauthBlockedReason, { duration: 6000 });
      return;
    }
    setBusy(true);
    try {
      if (isNativeAuthAvailable()) {
        // Native flow: Apple is always available on iOS; Google needs the
        // iOS client ID env to be set. Fall through to a friendly error if
        // not configured.
        if (provider === "apple") {
          console.info("[auth] starting native Apple sign-in");
          const { error } = await signInWithAppleNative();
          if (error) throw error;
          console.info("[auth] native Apple sign-in returned cleanly");
          // signInWithIdToken populates the session — useEffect navigates.
          return;
        }
        if (provider === "google") {
          if (!isNativeGoogleConfigured()) {
            toast.error("Google sign-in isn't fully configured for this build yet — try Apple, or email & password.");
            return;
          }
          console.info("[auth] starting native Google sign-in");
          const { error } = await signInWithGoogleNative();
          if (error) throw error;
          console.info("[auth] native Google sign-in returned cleanly");
          return;
        }
      }
      // Web fallback — Lovable OAuth broker round-trip.
      const result = await lovable.auth.signInWithOAuth(provider, { redirect_uri: window.location.origin });
      if (result.error) throw result.error;
      // result.redirected handled by browser; otherwise tokens set, useEffect navigates
    } catch (err: any) {
      console.error(`[auth] ${provider} sign-in failed`, err);
      // Detect real user-cancellation only — narrow patterns so we don't
      // swallow legit errors like "URL canceled by system" or
      // "user not signed in iCloud". Apple's `ASAuthorizationError.canceled`
      // surfaces as code 1001; the @capgo plugin maps it to the strings
      // matched below. Anything else gets surfaced to the user.
      const msg = String(err?.message || "");
      const code = String(err?.code || (err as any)?.errorMessage || "");
      const userCancelled =
        /user.*cancell?ed|sign.?in.*cancell?ed|the operation was cancelled by the user|ASAuthorizationError.*canceled|com\.apple\.AuthenticationServices.*1001/i
          .test(`${msg} ${code}`);
      if (!userCancelled) {
        toast.error(msg || `Couldn't sign in with ${provider}`);
      }
    } finally {
      setBusy(false);
    }
  };

  const passkeyLogin = async () => {
    setBusy(true);
    try {
      const { ok, userEmail } = await verifyPasskey();
      if (!ok || !userEmail) throw new Error("Couldn't verify");
      // Passkey verifies device identity; for now, prefill email and ask for password.
      // (Full passwordless requires server-side challenge — out of scope here.)
      setEmail(userEmail);
      setMode("signin");
      toast.success("Identity verified — enter your password to continue");
    } catch (e: any) {
      toast.error("Face ID / fingerprint failed");
    } finally { setBusy(false); }
  };

  if (loading || (user && profileLoading)) {
    return <PageFallback />;
  }

  return (
    <div className="min-h-screen w-full bg-background flex justify-center">
      <div className="relative w-full max-w-[400px] min-h-screen flex flex-col">
        <div className="pointer-events-none absolute inset-x-0 top-0 h-[200px]" style={{ background: "var(--gradient-glow)" }} />
        <div className="relative z-10 flex-1 flex flex-col px-6 pt-16 pb-10">
          <p className="eyebrow">DayDraft</p>
          <h1 className="font-display text-[28px] font-semibold mt-3 leading-[1.1] tracking-tight text-balance">
            {awaitingConfirmation ? "Check your email." : mode === "signup" ? "Design your days." : "Welcome back."}
          </h1>
          <p className="text-secondary-fg mt-2.5 text-[13px] leading-[1.55]">
            {awaitingConfirmation
              ? `We sent a confirmation link to ${confirmedFor || email}. Open it to finish creating your account.`
              : mode === "signup"
                ? "Turn raw lists into focused, intelligent schedules."
                : "Pick up where you left off."}
          </p>

          {!awaitingConfirmation ? (
            <>
              <div className="mt-8 space-y-2">
                <button onClick={() => oauth("google")} disabled={busy}
                  className={`w-full h-12 rounded-[14px] app-card py-0 text-foreground hover:border-primary/20 pressable text-sm font-medium inline-flex items-center justify-center gap-2 ${oauthBlockedReason ? "opacity-55" : ""}`}
                  title={oauthBlockedReason || undefined}>
                  <GoogleIcon /> Continue with Google
                </button>
                <button onClick={() => oauth("apple")} disabled={busy}
                  className={`w-full h-12 rounded-[14px] bg-foreground text-background hover:opacity-90 pressable text-sm font-medium inline-flex items-center justify-center gap-2 shadow-card ${oauthBlockedReason ? "opacity-55" : ""}`}
                  title={oauthBlockedReason || undefined}>
                  <AppleIcon /> Continue with Apple
                </button>
                {canUsePasskey && (
                  <button onClick={passkeyLogin} disabled={busy}
                    className="w-full h-12 rounded-[14px] border border-accent surface-accent backdrop-blur-sm text-primary hover:bg-primary/[0.07] pressable text-sm font-medium inline-flex items-center justify-center gap-2">
                    <Fingerprint className="h-4 w-4" /> Use Face ID / fingerprint
                  </button>
                )}
                {oauthBlockedReason && (
                  <p className="text-[11px] leading-snug text-secondary-fg/85 px-1 pt-1">
                    {oauthBlockedReason}
                  </p>
                )}
              </div>
              <div className="my-6 flex items-center gap-3 text-[10px] font-semibold uppercase tracking-[0.12em] text-secondary-fg">
                <div className="flex-1 h-px bg-border/50" />
                <span className="shrink-0">or email</span>
                <div className="flex-1 h-px bg-border/50" />
              </div>

              <form onSubmit={submit} className="space-y-3">
                {mode === "signup" && (
                  <Input value={name} onChange={e => setName(e.target.value)} placeholder="Your name" className="h-12 surface-card border-soft rounded-[14px]" />
                )}
                <Input
                  type="email"
                  required
                  value={email}
                  onChange={e => {
                    setEmail(e.target.value);
                    // If the user changes the email after a pending confirmation,
                    // hide the stale "Check your email at <old>" panel.
                    if (awaitingConfirmation && e.target.value !== confirmedFor) {
                      setAwaitingConfirmation(false);
                    }
                  }}
                  placeholder="Email"
                  className="h-12 surface-card border-soft rounded-[14px]"
                />
                <Input type="password" required minLength={6} value={pw} onChange={e => setPw(e.target.value)} placeholder="Password" className="h-12 surface-card border-soft rounded-[14px]" />
                <Button type="submit" disabled={busy} className="w-full h-12 rounded-[14px] bg-primary text-primary-foreground hover:bg-primary/90 pressable text-base font-medium shadow-card">
                  {busy ? "..." : mode === "signup" ? "Create account" : "Sign in"}
                </Button>
              </form>

              <div className="mt-6 flex items-center justify-between">
                <button
                  onClick={() => {
                    setAwaitingConfirmation(false);
                    setMode(mode === "signup" ? "signin" : "signup");
                  }}
                  className="text-secondary-fg text-sm hover:text-foreground transition-colors"
                >
                  {mode === "signup" ? "I already have an account" : "Create a new account"}
                </button>
                {mode === "signin" && (
                  <Link to="/forgot-password" className="text-secondary-fg text-sm hover:text-foreground transition-colors">
                    Forgot password?
                  </Link>
                )}
              </div>
            </>
          ) : (
            <div className="mt-10 space-y-3">
              <Button
                type="button"
                onClick={resendConfirmation}
                disabled={resending}
                className="w-full h-12 rounded-[14px] app-card py-0 text-foreground hover:border-primary/15 pressable text-base font-medium"
              >
                {resending ? "Sending..." : "Resend confirmation email"}
              </Button>
              <button
                type="button"
                onClick={() => {
                  setAwaitingConfirmation(false);
                  setMode("signin");
                }}
                className="w-full text-center text-secondary-fg text-sm hover:text-foreground transition-colors"
              >
                Already confirmed? Sign in
              </button>
              <button
                type="button"
                onClick={() => setAwaitingConfirmation(false)}
                className="w-full text-center text-secondary-fg text-sm hover:text-foreground transition-colors"
              >
                Use a different email
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

