} from "@/components/ui/alert-dialog";

type AIHelp = {
  substeps: string[];
  links: { label: string; url: string }[];
  tip: string;
  draft?: { subject?: string; body: string };
  recovery_actions?: { id: "compress_rest_day" | "defer_low_priority" | "split_current_block"; label: string; why: string }[];
};

export default function Focus() {
  const { blockId } = useParams();
  const nav = useNavigate();
  const { user } = useAuth();
  const { profile } = useProfile();
  const tone = getTone(profile as any);
  const { active: tracking, start: startTracking, stop: stopTracking, categories, addCategory, refresh: refreshTracker } = useTimeTracker();
  // Read elapsed seconds synchronously each render. `sessionTick` (below)
  // drives the once-per-second re-render that keeps this value fresh.
  const elapsedSec = getElapsedSec();
  const [block, setBlock] = useState<any | null>(null);
  const [next, setNext] = useState<Block | null>(null);
  const windowWallRef = useRef({ startMs: 0, endMs: 0 });
  /** Ticks once per second while armed so session elapsed re-renders without countdown pressure. */
  const [sessionTick, setSessionTick] = useState(0);
  const [showCheck, setShowCheck] = useState(false);
  const [help, setHelp] = useState<AIHelp | null>(null);
  const [helpLoading, setHelpLoading] = useState(false);
  const [helpError, setHelpError] = useState<string | null>(null);
  const [helpOpen, setHelpOpen] = useState(false);
  const [preflightOpen, setPreflightOpen] = useState(false);
  const [armed, setArmed] = useState(false);
  // Cancels in-flight task-assistant calls if the user leaves the Focus
  // screen mid-request — prevents setState-after-unmount.
  const getAbortSignal = useAbortOnUnmount();
  const startedHereRef = useRef(false);
  const autoStartedRef = useRef(false);
  const [confirmSkipOpen, setConfirmSkipOpen] = useState(false);
  const [confirmCancelOpen, setConfirmCancelOpen] = useState(false);
  const [runtimeReason, setRuntimeReason] = useState<"stuck" | "skip" | "overtime" | null>(null);
  // Wall-clock when the timer actually started ticking (after preflight).
  // Used to attribute REAL elapsed time to time_entries on complete().
  const actualStartMsRef = useRef<number | null>(null);
  const [catPickerOpen, setCatPickerOpen] = useState(false);
  const [newFocusCatName, setNewFocusCatName] = useState("");
  // Set when the user explicitly chooses "focus without tracking" for this
  // block. Suppresses the tracker prompt for the rest of the session, so the
  // big ring keeps counting plain elapsed without nagging.
  const [trackerSkipped, setTrackerSkipped] = useState(false);
  /** Plan calendar day (YYYY-MM-DD) — for recap / back navigation off the default "today". */
  const [planDate, setPlanDate] = useState<string | null>(null);
  const [searchParams] = useSearchParams();
  // "One thing mode" was removed from the product. Keep the variable so
  // existing branches stay dead without a large refactor.
  void searchParams;
  const oneThingMode = false;
  const [oneThingDoneFlash, setOneThingDoneFlash] = useState(false);
  const calmAutoEnabledRef = useRef(false);
  const guardrailToastShownRef = useRef(false);
  const trackingRef = useRef(tracking);
  const aiFocusRuntimeEnabled = isAiFlagEnabled("aiFocusRuntime", user?.id);
  const { isPro } = useEntitlement();

  useEffect(() => {
    const wasCalm = getCalmMode();
    if (!wasCalm) {
      calmAutoEnabledRef.current = true;
      setCalmMode(true);
    }
    return () => {
      if (calmAutoEnabledRef.current) {
        setCalmMode(false);
      }
    };
  }, []);

  useEffect(() => {
    if (!blockId || !user) return;
    // Reset all per-block state so navigating between blocks via /focus/:id
    // doesn't leave the previous block's UI (e.g. green checkmark) on screen.
    setBlock(null);
    setNext(null);
    windowWallRef.current = { startMs: 0, endMs: 0 };
    setShowCheck(false);
    setArmed(false);
    setTrackerSkipped(false);
    autoStartedRef.current = false;
    setHelp(null);
    setHelpOpen(false);
    setHelpError(null);
    setHelpLoading(false);
    startedHereRef.current = false;
    actualStartMsRef.current = null;
    guardrailToastShownRef.current = false;
    setPlanDate(null);
    (async () => {
      const { data } = await supabase.from("blocks").select("*").eq("id", blockId).maybeSingle();
      if (!data) {
        toast("This block is no longer available");
        nav("/today/plan");
        return;
      }
      const { data: planRow } = await supabase.from("plans").select("date").eq("id", data.plan_id).maybeSingle();
      setPlanDate((planRow as { date?: string } | null)?.date ?? todayDateStr());
      setBlock(data as Block);
      const pd =
        ((planRow as { date?: string } | null)?.date ?? todayDateStr());
      const startMs = wallMsOnPlanDay(pd, data.start_time);
      const endMs = wallMsOnPlanDay(pd, blockSlotEndHHMM(data as Block));
      windowWallRef.current = { startMs, endMs };
      const { data: rest } = await supabase
        .from("blocks")
        .select("*")
        .eq("plan_id", data.plan_id)
        .eq("kind", "task")
        .eq("is_calendar_event", false)
        .gt("position", data.position)
        .order("position")
        .limit(24);
      const nextOpen = (rest || []).find((row) => isOpenUserTask(row as Block));
      setNext((nextOpen as Block) || null);
      // Show preflight on first visit per session — unless the user opted out.
      // Skip on intra-session block transitions to avoid nagging.
      const optedOut = (() => { try { return localStorage.getItem("dd_preflight_disabled") === "1"; } catch { return false; } })();
      if (!optedOut && !sessionStorage.getItem("dd_preflight_seen") && !sessionStorage.getItem("dd_focus_active")) {
        setPreflightOpen(true);
      } else {
        setArmed(true);
      }
      sessionStorage.setItem("dd_focus_active", "1");
    })();
  }, [blockId, user?.id]);

  const dismissPreflight = () => {
    sessionStorage.setItem("dd_preflight_seen", "1");
    setPreflightOpen(false);
    setArmed(true);
  };

  // Mark the wall-clock start the first time the timer is armed for this block.
  useEffect(() => {
    if (armed && !actualStartMsRef.current) {
      actualStartMsRef.current = Date.now();
    }
  }, [armed]);

  // Auto-start the tracker the moment the focus session arms IF the user
  // already earmarked a category for this block on the Plan screen. If
  // they didn't, we leave tracking off and a prompt below offers a choice
  // ("pick category" / "focus without tracking").
  useEffect(() => {
    if (!armed || !block || autoStartedRef.current) return;
    if (tracking) return; // a timer is already running — don't double-start
    const assignedId = getAssignedCategoryId(block.id);
    if (!assignedId) return;
    const cat = categories.find((c) => c.id === assignedId);
    if (!cat) return;
    autoStartedRef.current = true;
    startedHereRef.current = true;
    void startTracking(cat.id, { source: "focus", blockId: block.id, note: block.title });
  }, [armed, block?.id, categories, tracking, startTracking]);

  useEffect(() => {
    if (!armed || !block) return;
    // Per-second re-render to drive the big ring countdown — pause it
    // when the tab is hidden so we don't burn renders the user can't
    // see. visibilitychange re-syncs when they come back.
    let id: number | null = null;
    const start = () => {
      if (id !== null) return;
      id = window.setInterval(() => setSessionTick((n) => n + 1), 1000);
    };
    const stop = () => {
      if (id !== null) { clearInterval(id); id = null; }
    };
    const onVisibility = () => {
      if (document.hidden) stop();
      else { setSessionTick((n) => n + 1); start(); }
    };
    if (!document.hidden) start();
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      stop();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [armed, block?.id]);

  useEffect(() => {
    trackingRef.current = tracking;
  }, [tracking]);

  useEffect(() => {
    return () => {
      // Stop tracking on unmount (leaving Focus entirely)
      if (startedHereRef.current && trackingRef.current) stopTracking();
      sessionStorage.removeItem("dd_focus_active");
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const trackingCat = categories.find(c => c.id === tracking?.category_id);

  const loadHelp = async (reason?: "stuck" | "skip" | "overtime") => {
    if (!block || helpLoading) return;
    setHelpOpen(true);
    if (help) return;
    if (reason) setRuntimeReason(reason);
    setHelpLoading(true);
    setHelpError(null);
    trackAiEvent("ai_focus_help_used", { reason: reason || "manual", block_type: block.type });
    const signal = getAbortSignal();
    try {
      // task-assistant on the same block + reason is cacheable for the whole
      // session — the inputs don't change while the user is in Focus.
      const { data, error } = await invokeAiCached<AIHelp>(
        "task-assistant",
        {
          title: block.title,
          type: block.type,
          location: block.location,
          duration_min: block.duration_min,
          ai_tone: (profile as any)?.ai_tone || "professional",
          ai_tone_custom: (profile as any)?.ai_tone_custom || null,
          ai_planning_rules: (profile as any)?.ai_planning_rules || "",
          runtime_reason: reason || null,
        },
        { ttlMs: 30 * 60_000, timeoutMs: 45_000, signal },
      );
      if (signal.aborted) return;
      if (error) throw error;
      setHelp(data as AIHelp);
    } catch (e: any) {
      if (signal.aborted) return;
      console.error(e);
      setHelpError(e?.message || "Unable to load AI assistant");
    } finally {
      if (!signal.aborted) setHelpLoading(false);
    }
  };

  const complete = async () => {
    if (!block || !user) return;
    haptics.notify("success");
    setShowCheck(true);
    // Wall-clock from when the Focus session timer armed → now (in-app countdown).
    const actualSec = actualStartMsRef.current
      ? Math.max(0, Math.round((Date.now() - actualStartMsRef.current) / 1000))
      : 0;
    const completedAtMs = Date.now();
    const completedIso = new Date(completedAtMs).toISOString();
    // Stop linked tracker first so `actual_minutes` can be derived from time_entries.
    const hadTrackerForBlock = !!(startedHereRef.current && tracking);
    let trackerStopOk = true;
    if (hadTrackerForBlock) {
      try {
        trackerStopOk = (await stopTracking()) !== false;
      } catch {
        trackerStopOk = false;
      }
      startedHereRef.current = false;
    }
    const patch: Record<string, unknown> = {
      completed: true,
      completed_at: completedIso,
      resolution: "done",
      resolved_at: completedIso,
    };
    if (!hadTrackerForBlock) {
      const fromArm = minutesFromFocusArmSeconds(actualSec);
      if (fromArm != null) patch.actual_minutes = fromArm;
      else {
        try {
          patch.actual_minutes = await resolveActualMinutesOnComplete(
            supabase,
            user.id,
            block.id,
            planDate || todayDateStr(),
            block.start_time,
            completedAtMs,
          );
        } catch {
          patch.actual_minutes = null;
        }
      }
    } else {
      try {
        const { data: row } = await supabase.from("blocks").select("actual_minutes").eq("id", block.id).maybeSingle();
        const am = (row as { actual_minutes?: number | null } | null)?.actual_minutes;
        if (!trackerStopOk || typeof am !== "number" || am < 1) {
          const fromArm = minutesFromFocusArmSeconds(actualSec);
          patch.actual_minutes =
            fromArm ??
            (await resolveActualMinutesOnComplete(
              supabase,
              user.id,
              block.id,
              planDate || todayDateStr(),
              block.start_time,
              completedAtMs,
            ).catch(() => null));
        }
      } catch {
        const fromArm = minutesFromFocusArmSeconds(actualSec);
        patch.actual_minutes = fromArm ?? null;
      }
    }
    const { error } = await supabase.from("blocks").update(patch as never).eq("id", block.id);
    if (error) {
      setShowCheck(false);
      toast.error("Unable to save. Please try again.");
      return;
    }
    try { localStorage.setItem(`dd_last_plan_progress_${planDate || todayDateStr()}`, new Date().toISOString()); } catch {/* ignore */}
    const recap = `/recap?date=${planDate || todayDateStr()}`;
    if (oneThingMode) {
      setOneThingDoneFlash(true);
      setTimeout(() => {
        if (next) nav(`/focus/${next.id}?mode=one`);
        else nav(recap);
      }, 3000);
      return;
    }
    setTimeout(() => {
      if (next) nav(`/focus/${next.id}`);
      else nav(recap);
    }, 600);
  };

  const skip = async () => {
    if (!block) return;
    haptics.impact("light");
    if (startedHereRef.current && tracking) {
      const entryId = tracking.id;
      try {
        await supabase.from("time_entries").delete().eq("id", entryId);
        await refreshTracker();
      } catch {/* ignore */}
      startedHereRef.current = false;
    }
    const resolvedIso = new Date().toISOString();
    try {
      await supabase
        .from("blocks")
        .update({ resolution: "skipped", resolved_at: resolvedIso, completed: false })
        .eq("id", block.id);
    } catch {
      toast.error("Could not save skip");
      return;
    }
    const backPlan =
      planDate && planDate !== todayDateStr() ? `/today/plan?date=${planDate}` : "/today/plan";
    if (next) nav(`/focus/${next.id}`); else nav(backPlan);
  };

  // Cancel = leave focus mode without changing anything (no completion, no
  // tracker write). Mirrors browser-back but with a confirmation if a session
  // is active so the user doesn't accidentally lose tracked time.
  const cancel = async () => {
    if (startedHereRef.current && tracking) {
      const entryId = tracking.id;
      try {
        await supabase.from("time_entries").delete().eq("id", entryId);
        await refreshTracker();
      } catch {/* ignore */}
      startedHereRef.current = false;
    }
    const backPlan =
      planDate && planDate !== todayDateStr() ? `/today/plan?date=${planDate}` : "/today/plan";
    nav(backPlan);
  };

  const lateDeepWork = !!block && block.type === "deep_work" && new Date().getHours() >= 18;
  const longSession = !!block && block.duration_min >= 90;

  useEffect(() => {
    if (!armed || guardrailToastShownRef.current) return;
    if (!block) return;
    if (lateDeepWork) {
      guardrailToastShownRef.current = true;
      toast("Guardrail: keep this block focused, then switch to lighter work.");
      return;
    }
    if (longSession) {
      guardrailToastShownRef.current = true;
      toast("Guardrail: take a short break after this focus block.");
    }
  }, [armed, lateDeepWork, longSession]);

  if (!block) return <div className="min-h-screen bg-background" />;
  if (oneThingMode && !isPro) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center px-6">
        <div className="text-center">
          <div className="text-[18px] font-display text-foreground">One thing mode is Pro</div>
          <button onClick={() => nav(`/focus/${block.id}`)} className="mt-3 text-primary text-sm hover:underline">Continue in regular focus</button>
        </div>
      </div>
    );
  }

  void sessionTick;
  const focusElapsedSec = actualStartMsRef.current
    ? Math.max(0, Math.floor((Date.now() - actualStartMsRef.current) / 1000))
    : 0;
  const oneThingElapsedSec = focusElapsedSec;
  const trackingThisBlock = !!(tracking && block && tracking.block_id === block.id);
  // The big ring should reflect the *tracker* when it's actually attributing
  // time to a category. With no tracker running, it falls back to a plain
  // wall-clock since-arm count (which doesn't persist to time_entries).
  const ringElapsedSec = trackingThisBlock ? elapsedSec : focusElapsedSec;
  const assignedCatIdForBlock = block ? getAssignedCategoryId(block.id) : null;
  const fmtDur = (m: number) =>
    m < 60 ? `${m}m` : `${Math.floor(m / 60)}h${m % 60 ? ` ${m % 60}m` : ""}`;

  const RING_R = 100;
  const RING_CIRC = 2 * Math.PI * RING_R;
  const plannedSec = block.duration_min * 60;
  const progressRatio = plannedSec > 0 ? Math.min(1, ringElapsedSec / plannedSec) : 0;
  const isOverTime = ringElapsedSec > 0 && ringElapsedSec > plannedSec;

  if (oneThingMode) {
    return (
      <div className="min-h-screen w-full bg-black flex justify-center relative overflow-hidden">
        <div className="absolute inset-0 bg-black/95" />
        <button
          onClick={() => cancel()}
          className="absolute top-5 right-5 z-20 text-[12px] text-slate-300 border border-slate-700 rounded-full px-3 py-1.5 pressable hover:text-white"
        >
          × Exit focus
        </button>
        <div className="relative z-10 w-full max-w-[430px] min-h-screen flex flex-col items-center justify-center px-8">
          <div className="text-[10px] uppercase tracking-[0.16em] text-slate-400">One thing mode</div>
          <h1 className="mt-3 text-center font-display text-[34px] leading-[1.08] text-white text-balance">{block.title}</h1>
          <div className="mt-8 text-[44px] font-mono-sf tabular-nums text-cyan-200 leading-none">
            {fmtHMS(oneThingElapsedSec)}
          </div>
          <div className="text-[11px] uppercase tracking-[0.14em] text-slate-500 mt-3">
            Session time · planned window to {fmtTime(blockSlotEndHHMM(block))}
          </div>
          <button
            onClick={complete}
            className="mt-10 h-14 px-10 rounded-2xl bg-cyan-400 text-slate-950 font-semibold text-[17px] pressable shadow-[0_10px_40px_-12px_rgba(34,211,238,0.7)]"
          >
            Done
          </button>
        </div>
        {oneThingDoneFlash && (
          <div className="fixed inset-0 z-30 flex items-center justify-center bg-emerald-500/92 animate-in fade-in duration-300">
            <div className="text-center text-emerald-950">
              <Check className="h-20 w-20 mx-auto" strokeWidth={3.2} />
              <div className="mt-3 text-[20px] font-display font-semibold">Great work</div>
            </div>
          </div>
        )}
      </div>
    );
  }

  const applyRecoveryAction = async (actionId: "compress_rest_day" | "defer_low_priority" | "split_current_block") => {
    if (!block || !user) return;
    trackAiEvent("ai_replan_applied", { action_id: actionId, block_id: block.id });
    if (actionId === "split_current_block") {
      toast.success("Use the suggested steps below as your micro-plan.");
      return;
    }
    const { data: restRows } = await supabase
      .from("blocks")
      .select("title,duration_min,type,kind,completed,position,resolution")
      .eq("plan_id", block.plan_id)
      .gt("position", block.position)
      .eq("completed", false)
      .is("resolution", null)
      .order("position", { ascending: true });
    const rest = (restRows || []).filter((r: any) => r.kind === "task");
    if (!rest.length) {
      toast("No remaining tasks to re-plan.");
      return;
    }
    const shaped = rest
      .filter((r: any) => actionId !== "defer_low_priority" || r.type !== "routine")
      .map((r: any) => {
        const min = Number(r.duration_min) || 30;
        const nextMin = actionId === "compress_rest_day" ? Math.max(20, Math.round(min * 0.8)) : min;
        return `${r.title} (${nextMin}m)`;
      });
    if (!shaped.length) {
      toast("Everything left is low-priority. Finish this block first.");
      return;
    }
    sessionStorage.setItem("dd_planning_input", shaped.join("\n"));
    if (planDate) sessionStorage.setItem("dd_planning_plan_date", planDate);
    nav(planDate && planDate !== todayDateStr() ? `/today?date=${planDate}&composer=1` : "/today?composer=1");
  };

  // Smart contextual quick actions derived from the title/type
  const title = (block.title || "").toLowerCase();
  const isCall = /\b(call|phone|ring|dial)\b/.test(title);
  const isMeeting = block.type === "communication" && /\b(meeting|sync|standup|1:1|catchup|catch-up|call with|meet with)\b/.test(title);
  const isEmail = /\b(email|reply|respond|inbox)\b/.test(title);

  const calendarUrl = (() => {
    const t = encodeURIComponent(block.title || "Block");
    return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${t}`;
  })();
  const mailtoUrl = `mailto:?subject=${encodeURIComponent(block.title || "")}`;
  const telUrl = `tel:`;

  const copyDraft = async () => {
    if (!help?.draft) return;
    const txt = help.draft.subject
      ? `Subject: ${help.draft.subject}\n\n${help.draft.body}`
      : help.draft.body;
    try {
      await navigator.clipboard.writeText(txt);
      toast.success("Draft copied");
    } catch {
      toast.error("Unable to copy draft");
    }
  };

  return (
    <div className="min-h-screen w-full bg-background flex justify-center relative">
      <div className="pointer-events-none absolute inset-x-0 top-0 h-[160px]" style={{ background: "var(--gradient-glow)" }} />
      <motion.div
        initial={{ opacity: 0, scale: 0.96, y: 16 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        transition={{ type: "spring", bounce: 0.2, duration: 0.7 }}
        className="relative w-full max-w-[400px] min-h-screen flex flex-col items-center px-6 pt-14 pb-10"
      >
        {/* Cancel — top-left, returns to plan without altering anything */}
        <button
          onClick={() => (startedHereRef.current && tracking) ? setConfirmCancelOpen(true) : cancel()}
          className="absolute top-4 left-4 h-11 w-11 rounded-full border border-soft bg-background/70 backdrop-blur-md flex items-center justify-center text-secondary-fg hover:text-foreground pressable shadow-card"
          aria-label="Cancel focus session"
        >
          <X className="h-4 w-4" />
        </button>
        <div className="px-3 py-1 rounded-full surface-accent border border-accent text-[10px] tracking-[0.14em] text-primary font-semibold uppercase">Focus</div>
        {/* Tracking pill removed — the main timer + the inline "Stop tracking"
            button below already convey state. Two timers on one screen was
            redundant and confusing. */}

        <h1 className="mt-8 font-display text-[26px] font-semibold text-center leading-[1.15] max-w-[310px] line-clamp-3 text-balance tracking-[-0.02em]">{block.title}</h1>
        {(lateDeepWork || longSession) && (
          <div className="mt-3 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-soft surface-soft text-[11px] text-secondary-fg">
            <ShieldAlert className="h-3.5 w-3.5 text-primary" />
            {lateDeepWork ? "Late-day guardrail: one priority, then wind down." : "Guardrail: take a short reset right after this block."}
          </div>
        )}

        {/* Circular ring timer */}
        <div className="relative mt-10 flex flex-col items-center">
          <div className="relative h-[240px] w-[240px]">
            {showCheck ? (
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="h-28 w-28 rounded-full bg-success flex items-center justify-center check-pop shadow-[0_12px_40px_-10px_hsl(var(--success)/0.55)]">
                  <Check className="h-14 w-14 text-success-foreground" strokeWidth={2.75} />
                </div>
              </div>
            ) : (
              <>
                {/* Ambient glow behind ring */}
                <div
                  className="absolute inset-0 rounded-full pointer-events-none"
                  style={{
                    background: isOverTime
                      ? "radial-gradient(circle, hsl(var(--destructive)/0.08) 0%, transparent 65%)"
                      : "radial-gradient(circle, hsl(var(--primary)/0.08) 0%, transparent 65%)",
                  }}
                />
                <svg className="absolute inset-0 w-full h-full -rotate-90" viewBox="0 0 240 240">
                  {/* Track */}
                  <circle cx="120" cy="120" r={RING_R} fill="none" stroke="hsl(var(--border)/0.2)" strokeWidth="9" />
                  {/* Progress fill */}
                  <circle
                    cx="120" cy="120" r={RING_R}
                    fill="none"
                    stroke={isOverTime ? "hsl(var(--destructive))" : "hsl(var(--primary))"}
                    strokeWidth="9"
                    strokeLinecap="round"
                    strokeDasharray={`${RING_CIRC} ${RING_CIRC}`}
                    strokeDashoffset={RING_CIRC * (1 - progressRatio)}
                    className={isOverTime ? "focus-timer-overtime" : "focus-timer-ring-active"}
                    style={{ transition: "stroke-dashoffset 0.9s cubic-bezier(0.4,0,0.2,1), stroke 0.4s ease" }}
                  />
                </svg>
                {/* Center content — shows tracker time when a category is
                    attributing the session; otherwise a plain since-arm
                    elapsed (no time_entry is created). */}
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                  <div className="text-[10px] font-semibold uppercase tracking-[0.16em] text-secondary-fg/55 inline-flex items-center gap-1">
                    {trackingThisBlock && trackingCat ? (
                      <>
                        <span className="h-1.5 w-1.5 rounded-full animate-pulse" style={{ background: trackingCat.color }} aria-hidden />
                        {trackingCat.name}
                      </>
                    ) : isOverTime ? (
                      "overtime"
                    ) : (
                      "elapsed"
                    )}
                  </div>
                  <div className={`text-[46px] font-mono-sf font-semibold tabular-nums leading-none mt-1.5 ${isOverTime ? "text-destructive" : "text-foreground"}`}>
                    {fmtHMS(ringElapsedSec)}
                  </div>
                  <div className="text-[12px] text-secondary-fg/60 mt-2">
                    of {fmtDur(block.duration_min)}
                  </div>
                </div>
              </>
            )}
          </div>
          {/* Stop-tracking control (only when a tracker is actually running on
              this block — the ring already shows the category + elapsed, so
              we just need a discreet stop affordance). */}
          {armed && trackingThisBlock && trackingCat && (
            <button
              type="button"
              onClick={() => { stopTracking(); startedHereRef.current = false; }}
              className="mt-5 flex items-center gap-1 mx-auto rounded-full border border-soft bg-background/70 px-3 py-1.5 text-[11px] font-medium text-secondary-fg pressable hover:text-foreground"
            >
              <Square className="h-3 w-3" /> Stop tracking
            </button>
          )}
        </div>

        <div className="mt-8 w-full max-w-[320px] space-y-2.5">
          <button
            type="button"
            onClick={() => void complete()}
            className="w-full flex h-14 items-center justify-center gap-2 rounded-2xl bg-primary text-[16px] font-semibold text-primary-foreground pressable shadow-[0_8px_28px_-8px_hsl(var(--primary)/0.6)]"
          >
            <Check className="h-5 w-5 shrink-0" strokeWidth={2.75} />
            Done
          </button>
          <button
            type="button"
            onClick={() => setConfirmSkipOpen(true)}
            className="w-full flex h-11 items-center justify-center rounded-xl border border-border/45 bg-card/80 text-[13px] font-medium text-secondary-fg pressable hover:text-foreground transition-colors"
          >
            Skip
          </button>
        </div>
        {/* Decision prompt when this block has no tracker category yet and
            the user hasn't opted out for this session. Two clear paths so
            the user is never silently un-tracked. */}
        {!trackingThisBlock && armed && !assignedCatIdForBlock && !trackerSkipped && (
          <div className="mt-5 w-full max-w-[320px] rounded-[18px] border border-border/45 bg-card/70 backdrop-blur-sm px-4 py-3.5 space-y-2.5">
            <div className="flex items-start gap-2.5">
              <Timer className="h-4 w-4 text-primary mt-0.5 shrink-0" />
              <div className="text-[12.5px] leading-snug text-foreground/90">
                Track this block's time? Pick a category to log it, or focus without saving.
              </div>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <Popover open={catPickerOpen} onOpenChange={(o) => { setCatPickerOpen(o); if (!o) setNewFocusCatName(""); }}>
                <PopoverTrigger asChild>
                  <button className="h-10 rounded-[12px] bg-primary/12 border border-primary/35 text-primary text-[12.5px] font-semibold pressable hover:bg-primary/18 transition-colors">
                    Pick category
                  </button>
                </PopoverTrigger>
                <PopoverContent className="w-[min(20rem,calc(100vw-2rem))] p-3" align="center">
                  <div className="text-[10px] uppercase tracking-wider text-secondary-fg px-1 pb-2">Pick a category</div>
                  <div className="max-h-48 space-y-0.5 overflow-y-auto pr-0.5">
                    {categories.map((c) => (
                      <button
                        key={c.id}
                        type="button"
                        onClick={() => {
                          startedHereRef.current = true;
                          void startTracking(c.id, { source: "focus", blockId: block.id, note: block.title });
                          setCatPickerOpen(false);
                        }}
                        className="flex w-full items-center gap-2 rounded-lg px-2 py-2 text-left text-sm text-foreground pressable hover:bg-muted"
                      >
                        <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: c.color }} />
                        <span className="flex-1 truncate">{c.name}</span>
                      </button>
                    ))}
                    {categories.length === 0 && (
                      <p className="px-1 py-2 text-[12px] leading-snug text-secondary-fg">No categories yet. Create one below.</p>
                    )}
                  </div>
                  <form
                    className="mt-3 flex flex-col gap-2 border-t border-border/40 pt-3"
                    onSubmit={async (e) => {
                      e.preventDefault();
                      const name = newFocusCatName.trim();
                      if (!name) return;
                      const c = await addCategory(name);
                      if (!c) return;
                      startedHereRef.current = true;
                      await startTracking(c.id, { source: "focus", blockId: block.id, note: block.title });
                      setNewFocusCatName("");
                      setCatPickerOpen(false);
                    }}
                  >
                    <Input
                      value={newFocusCatName}
                      onChange={(e) => setNewFocusCatName(e.target.value)}
                      placeholder="New category name"
                      className="h-10 text-[13px]"
                    />
                    <button
                      type="submit"
                      disabled={!newFocusCatName.trim()}
                      className="h-10 w-full rounded-xl bg-primary text-[13px] font-semibold text-primary-foreground pressable disabled:opacity-45"
                    >
                      Add and start
                    </button>
                  </form>
                </PopoverContent>
              </Popover>
              <button
                type="button"
                onClick={() => { setTrackerSkipped(true); haptics.selection(); }}
                className="h-10 rounded-[12px] border border-border/45 bg-background/60 text-secondary-fg text-[12.5px] font-medium pressable hover:text-foreground transition-colors"
              >
                Focus without tracking
              </button>
            </div>
          </div>
        )}

        {/* Quiet "add tracker" button after the user opted to skip — non-blocking,
            in case they change their mind mid-session. */}
        {!trackingThisBlock && armed && !assignedCatIdForBlock && trackerSkipped && (
          <Popover open={catPickerOpen} onOpenChange={(o) => { setCatPickerOpen(o); if (!o) setNewFocusCatName(""); }}>
            <PopoverTrigger asChild>
              <button className="mt-5 inline-flex items-center gap-1.5 px-4 py-2 rounded-full border border-border/45 bg-card/60 text-[12px] font-medium text-secondary-fg hover:text-foreground hover:border-border/65 pressable transition-colors">
                <Timer className="h-3.5 w-3.5" /> Start tracking
              </button>
            </PopoverTrigger>
            <PopoverContent className="w-[min(20rem,calc(100vw-2rem))] p-3" align="center">
              <div className="text-[10px] uppercase tracking-wider text-secondary-fg px-1 pb-2">Pick a category</div>
              <div className="max-h-48 space-y-0.5 overflow-y-auto pr-0.5">
                {categories.map((c) => (
                  <button
                    key={c.id}
                    type="button"
                    onClick={() => {
                      startedHereRef.current = true;
                      void startTracking(c.id, { source: "focus", blockId: block.id, note: block.title });
                      setCatPickerOpen(false);
                    }}
                    className="flex w-full items-center gap-2 rounded-lg px-2 py-2 text-left text-sm text-foreground pressable hover:bg-muted"
                  >
                    <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: c.color }} />
                    <span className="flex-1 truncate">{c.name}</span>
                  </button>
                ))}
                {categories.length === 0 && (
                  <p className="px-1 py-2 text-[12px] leading-snug text-secondary-fg">Create a category below, then time links to this task.</p>
                )}
              </div>
              <form
                className="mt-3 flex flex-col gap-2 border-t border-border/40 pt-3"
                onSubmit={async (e) => {
                  e.preventDefault();
                  const name = newFocusCatName.trim();
                  if (!name) return;
                  const c = await addCategory(name);
                  if (!c) return;
                  startedHereRef.current = true;
                  await startTracking(c.id, { source: "focus", blockId: block.id, note: block.title });
                  setNewFocusCatName("");
                  setCatPickerOpen(false);
                }}
              >
                <Input
                  value={newFocusCatName}
                  onChange={(e) => setNewFocusCatName(e.target.value)}
                  placeholder="New category name"
                  className="h-10 text-[13px]"
                />
                <button
                  type="submit"
                  disabled={!newFocusCatName.trim()}
                  className="h-10 w-full rounded-xl bg-primary text-[13px] font-semibold text-primary-foreground pressable disabled:opacity-45"
                >
                  Add category and start
                </button>
              </form>
            </PopoverContent>
          </Popover>
        )}
        <div className="mt-auto pt-8 text-center px-2">
          <p className="text-[13px] text-secondary-fg/80 leading-relaxed">
            {next ? (
              <>Next up: <span className="text-foreground font-medium">{next.title}</span></>
            ) : block.kind === "task" ? (
              "Last block — finish strong."
            ) : block.kind === "lunch" ? (
              "Enjoy your lunch."
            ) : (
              "Take a real break."
            )}
          </p>
        </div>

        {/* AI Assistant panel */}
        <div className="w-full mt-5">
          {!helpOpen ? (
            <button
              onClick={() => loadHelp()}
              className="w-full h-11 rounded-2xl app-card py-0 text-[13px] font-medium pressable inline-flex items-center justify-center gap-2 text-foreground border-primary/20 hover:border-primary/40 transition-colors"
            >
              <Sparkles className="h-4 w-4 text-primary" />
              {toneCopy(tone, "ai_help_cta")}
            </button>
          ) : (
            <div className="app-card panel-luxe px-3.5 py-5 space-y-3 text-left">
              <div className="flex items-center gap-2 eyebrow text-primary">
                <Sparkles className="h-3.5 w-3.5" /> {toneCopy(tone, "ai_assistant_title")}
              </div>
              {block.location && (
                <a
                  href={mapsUrl(block.location, block.location_lat, block.location_lng)}
                  target="_blank"
                  rel="noreferrer"
                  className="flex items-center gap-2 text-sm text-foreground bg-background/80 rounded-[12px] px-3 py-2 border border-soft pressable"
                >
                  <MapPin className="h-4 w-4 text-primary shrink-0" />
                  <span className="truncate flex-1">{block.location}</span>
                  <ExternalLink className="h-3.5 w-3.5 text-secondary-fg" />
                </a>
              )}
              {/* Contextual quick actions */}
              {(isCall || isMeeting || isEmail) && (
                <div className="flex gap-1.5 flex-wrap">
                  {isCall && (
                    <a href={telUrl} className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-background border border-soft text-xs font-medium text-foreground pressable">
                      <Phone className="h-3.5 w-3.5 text-primary" /> Call
                    </a>
                  )}
                  {isMeeting && (
                    <a href={calendarUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-background border border-soft text-xs font-medium text-foreground pressable">
                      <CalendarPlus className="h-3.5 w-3.5 text-primary" /> Add to calendar
                    </a>
                  )}
                  {isEmail && (
                    <a href={mailtoUrl} className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-background border border-soft text-xs font-medium text-foreground pressable">
                      <Mail className="h-3.5 w-3.5 text-primary" /> New email
                    </a>
                  )}
                </div>
              )}
              {helpLoading && (
                <div className="flex items-center gap-2 text-sm text-secondary-fg py-3 justify-center">
                  <Loader2 className="h-4 w-4 animate-spin" /> Thinking…
                </div>
              )}
              {helpError && (
                <div className="text-sm text-destructive">{helpError}</div>
              )}
              {help && (
                <>
                  {aiFocusRuntimeEnabled && help.recovery_actions && help.recovery_actions.length > 0 && (
                    <div className="space-y-1.5">
                      <div className="text-[11px] uppercase tracking-wider text-secondary-fg">AI quick recovery</div>
                      {help.recovery_actions.map((a, idx) => (
                        <button
                          key={`${a.id}-${idx}`}
                          type="button"
                          onClick={() => void applyRecoveryAction(a.id)}
                          className="w-full text-left rounded-lg border border-soft bg-background/70 px-3 py-2 pressable"
                        >
                          <div className="text-[12px] font-medium text-foreground">{a.label}</div>
                          <div className="text-[11px] text-secondary-fg mt-0.5">{a.why}</div>
                        </button>
                      ))}
                    </div>
                  )}
                  {help.draft && (
                    <div className="rounded-[14px] border border-accent surface-accent overflow-hidden">
                      <div className="flex items-center justify-between px-3 py-2 border-b border-accent">
                        <div className="flex items-center gap-1.5 eyebrow text-primary">
                          <Mail className="h-3 w-3" /> Draft
                        </div>
                        <button onClick={copyDraft} className="inline-flex items-center gap-1 text-[11px] font-medium text-primary pressable">
                          <Copy className="h-3 w-3" /> Copy
                        </button>
                      </div>
                      <div className="px-3 py-2.5 text-sm space-y-1">
                        {help.draft.subject && (
                          <div className="text-foreground"><span className="text-secondary-fg text-xs">Subject: </span>{help.draft.subject}</div>
                        )}
                        <pre className="whitespace-pre-wrap font-sans text-foreground text-[13px] leading-relaxed">{help.draft.body}</pre>
                      </div>
                    </div>
                  )}
                  {help.substeps?.length > 0 && (
                    <div>
                      <div className="text-[11px] uppercase tracking-wider text-secondary-fg mb-1.5">Steps</div>
                      <ol className="space-y-1.5">
                        {help.substeps.map((s, i) => (
                          <li key={i} className="flex items-start gap-2 text-sm">
                            <span className="h-5 w-5 rounded-full bg-primary/10 text-primary text-[11px] font-semibold flex items-center justify-center shrink-0 mt-0.5">{i + 1}</span>
                            <span className="text-foreground">{s}</span>
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                  {help.links?.length > 0 && (
                    <div>
                      <div className="text-[11px] uppercase tracking-wider text-secondary-fg mb-1.5">Useful links</div>
                      <div className="space-y-1">
                        {help.links.map((l, i) => (
                          <a
                            key={i}
                            href={l.url}
                            target="_blank"
                            rel="noreferrer"
                            className="flex items-center gap-2 text-sm text-primary hover:underline"
                          >
                            <ExternalLink className="h-3.5 w-3.5 shrink-0" />
                            <span className="truncate">{l.label}</span>
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                  {help.tip && (
                    <div className="flex items-start gap-2 surface-accent border border-accent rounded-[12px] px-3 py-2 text-sm text-foreground">
                      <Lightbulb className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                      <span>{help.tip}</span>
                    </div>
                  )}
                </>
              )}
            </div>
          )}
        </div>
      </motion.div>
      <PreflightSheet
        open={preflightOpen}
        onOpenChange={(v) => { if (!v) dismissPreflight(); }}
        onStart={dismissPreflight}
        taskTitle={block?.title}
        taskType={block?.type}
      />
      <AlertDialog open={confirmSkipOpen} onOpenChange={setConfirmSkipOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Skip this block?</AlertDialogTitle>
            <AlertDialogDescription>
              &quot;{block?.title}&quot; will be marked skipped (cleared from your plate). Any tracker time started here is dropped.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            {aiFocusRuntimeEnabled && (
              <button
                type="button"
                onClick={() => {
                  setConfirmSkipOpen(false);
                  void loadHelp("skip");
                }}
                className="h-10 rounded-md border border-soft px-3 text-sm text-secondary-fg hover:text-foreground pressable"
              >
                {toneCopy(tone, "ai_skip_alt_cta")}
              </button>
            )}
            <AlertDialogAction onClick={() => { setConfirmSkipOpen(false); skip(); }}>Skip</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      <AlertDialog open={confirmCancelOpen} onOpenChange={setConfirmCancelOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Leave focus?</AlertDialogTitle>
            <AlertDialogDescription>
              You're tracking time. Leaving will discard this session — the block stays as it was.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Stay</AlertDialogCancel>
            <AlertDialogAction onClick={() => { setConfirmCancelOpen(false); cancel(); }}>Leave</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { ArrowLeft } from "lucide-react";

export default function ForgotPassword() {
  const [email, setEmail] = useState("");
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);
  const nav = useNavigate();

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${window.location.origin}/reset-password`,
      });
      if (error) throw error;
      setSent(true);
      toast.success("Check your email for a reset link");
    } catch (err: any) {
      toast.error(err.message || "Something went wrong");
    } finally { setBusy(false); }
  };

  return (
    <div className="min-h-screen w-full bg-background flex justify-center">
      <div className="relative w-full max-w-[400px] min-h-screen flex flex-col">
        <div className="pointer-events-none absolute inset-x-0 top-0 h-[200px]" style={{ background: "var(--gradient-glow)" }} />
        <div className="relative z-10 flex-1 flex flex-col px-6 pt-16 pb-10">
          <button onClick={() => nav("/auth")} className="inline-flex items-center gap-1 text-[13px] text-secondary-fg hover:text-foreground pressable">
            <ArrowLeft className="h-4 w-4" /> Back
          </button>
          <h1 className="font-display text-[26px] font-semibold mt-6 leading-tight text-balance">Reset password</h1>
          <p className="text-secondary-fg mt-2.5 text-[13px] leading-[1.55]">
            {sent ? `Reset link sent to ${email}. Open it on this device.` : "We'll email you a link to set a new password."}
          </p>

          {!sent && (
            <form onSubmit={submit} className="mt-9 space-y-3">
              <Input type="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="Email"
                className="h-12 surface-card border-soft rounded-[14px]" />
              <Button type="submit" disabled={busy} className="w-full h-12 rounded-[14px] bg-primary text-primary-foreground hover:bg-primary/90 pressable text-base font-medium shadow-card">
                {busy ? "..." : "Send reset link"}
              </Button>
            </form>
          )}

          {sent && (
            <Button onClick={() => nav("/auth")} variant="outline" className="mt-8 h-12 rounded-[14px] border-soft">
              Back to sign in
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo } from "react";
import { keepPreviousData, useQuery, useQueryClient } from "@tanstack/react-query";
import { useLocation, useNavigate, useSearchParams } from "react-router-dom";
import { HomeTrackerHero } from "@/components/app/HomeTrackerHero";
import { PullToRefresh } from "@/components/app/PullToRefresh";
import { YesterdayDebriefCard } from "@/components/app/YesterdayDebriefCard";
import { useAuth } from "@/hooks/useAuth";
import { useProfile } from "@/hooks/useProfile";
import { useTour, TOUR_TODAY } from "@/components/app/Tour";
import { todayDateStr, isUserTask, isOpenUserTask, isUserTaskDone, type Block } from "@/lib/daydraft";
import { fetchPlanDashboard, planDashboardQueryKey } from "@/lib/planQueries";
import { supabase } from "@/integrations/supabase/client";
import { applyAutoMissedBlocks } from "@/lib/blockResolution";
import { greetingFor, getTone } from "@/lib/tone";
import { fmtHM, useTimeTracker, useTimeTrackerElapsed } from "@/hooks/useTimeTracker";
import {
  fetchRollingEntries,
  filterEntriesByRange,
  rollingEntriesQueryKey,
} from "@/lib/timeEntriesQuery";
import { useTabVisible } from "@/components/app/PersistentTabs";
import { motion } from "framer-motion";

/** Tracker is the hero. */
export default function Home() {
  const { user } = useAuth();
  const { profile } = useProfile();
  const tone = getTone(profile as any);
  const tour = useTour();
  const nav = useNavigate();
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const queryClient = useQueryClient();
  const viewDate = todayDateStr();
  const { categories } = useTimeTracker();

  useEffect(() => {
    if (location.hash === "#tracker" || searchParams.get("tracker") === "1") {
      nav("/tracker", { replace: true });
    }
  }, [location.hash, searchParams, nav]);

  useEffect(() => {
    if (!profile?.onboarded) return;
    if (profile.tour_seen && (profile.tour_seen as Record<string, unknown>).today) return;
    const t = setTimeout(() => tour.start(TOUR_TODAY), 800);
    return () => clearTimeout(t);
  }, [profile?.onboarded, profile?.tour_seen, tour]);

  const { data: planData } = useQuery({
    queryKey: planDashboardQueryKey(user?.id ?? "", viewDate),
    queryFn: () => fetchPlanDashboard(user!.id, viewDate),
    enabled: !!user?.id,
    staleTime: 30_000,
    placeholderData: keepPreviousData,
  });
  const blocks = planData?.planBlocks ?? [];

  // Pause the missed-block poll while this tab isn't on screen. Background
  // tabs in a native app don't keep hitting the network — this matches that
  // behavior so we don't pay a Supabase round-trip every 60s while the user
  // is on Reports / Settings / Tracker.
  const tabVisible = useTabVisible();
  useEffect(() => {
    if (!user?.id || !tabVisible) return;
    let alive = true;
    const run = async () => {
      const d = await fetchPlanDashboard(user.id, viewDate);
      if (!d.planBlocks.length || !alive) return;
      const changed = await applyAutoMissedBlocks(supabase, viewDate, d.planBlocks as Block[]);
      if (alive && changed) void queryClient.invalidateQueries({ queryKey: planDashboardQueryKey(user.id, viewDate) });
    };
    void run();
    const id = setInterval(run, 60_000);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, [user?.id, viewDate, queryClient, tabVisible]);

  const onRefresh = async () => {
    if (!user?.id) return;
    await queryClient.invalidateQueries({ queryKey: planDashboardQueryKey(user.id, viewDate) });
    await queryClient.invalidateQueries({ queryKey: ["plan-dates-markers", user!.id] });
  };

  const greeting = greetingFor(tone, profile?.display_name);
  const firstName = profile?.display_name?.split(" ")[0];

  // Today's category breakdown reads from the shared rolling-entries cache —
  // no Home-only fetch. Reports, Tracker, and useTimeTracker all draw from the
  // same query, so the data is already warm by the time Home mounts.
  const { data: rollingEntries } = useQuery({
    queryKey: rollingEntriesQueryKey(user?.id),
    queryFn: () => fetchRollingEntries(user!.id),
    enabled: !!user?.id,
    staleTime: 60_000,
    gcTime: 30 * 60_000,
    placeholderData: keepPreviousData,
  });
  // Subscribe to elapsed ticks so live timer contribution to today's totals
  // re-renders each second.
  useTimeTrackerElapsed();

  const userTasks = useMemo(() => blocks.filter(isUserTask), [blocks]);
  const doneTasks = useMemo(() => userTasks.filter((b) => isUserTaskDone(b)).length, [userTasks]);
  const nextTask = useMemo(() => blocks.find((b) => isUserTask(b) && isOpenUserTask(b)), [blocks]);

  const breakdown = useMemo(() => {
    if (!rollingEntries?.length) return [];
    const dayStart = new Date(); dayStart.setHours(0,0,0,0);
    const dayEnd = new Date(dayStart.getTime() + 86_400_000);
    const ds = dayStart.getTime();
    const de = dayEnd.getTime();
    const todays = filterEntriesByRange(rollingEntries, { from: dayStart, to: dayEnd });
    const now = Date.now();
    const map = new Map<string, number>();
    let total = 0;
    for (const e of todays) {
      const s = Math.max(new Date(e.started_at).getTime(), ds);
      const en = Math.min(e.ended_at ? new Date(e.ended_at).getTime() : now, de);
      const sec = Math.max(0, (en - s) / 1000);
      if (sec <= 0 || !e.category_id) continue;
      total += sec;
      map.set(e.category_id, (map.get(e.category_id) || 0) + sec);
    }
    const catMap = new Map(categories.map((c) => [c.id, c]));
    return Array.from(map.entries())
      .map(([id, sec]) => ({ cat: catMap.get(id), sec, pct: total > 0 ? sec / total : 0 }))
      .filter((r) => r.cat)
      .sort((a, b) => b.sec - a.sec)
      .slice(0, 5);
  }, [rollingEntries, categories]);

  return (
    <PullToRefresh onRefresh={onRefresh}>
        <div className="flex min-h-0 flex-1 flex-col px-5 pt-7 pb-6">
          {/* Greeting */}
          <header className="mb-5 shrink-0">
            <p className="text-[10px] font-semibold tracking-[0.18em] uppercase text-secondary-fg/50 mb-1">
              {new Date().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" })}
            </p>
            <h1 className="font-display text-[28px] font-semibold tracking-[-0.025em] leading-[1.1] text-foreground overflow-hidden text-ellipsis whitespace-nowrap">
              {greeting}
            </h1>
          </header>

          {/* THE HERO — tracker */}
          <motion.div layout transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}>
            <HomeTrackerHero onOpenDetails={() => nav("/reports")} />
          </motion.div>

          {/* Morning look-back. Silently hides when there's no plan from
              yesterday, when the edge function isn't deployed, or when the
              user dismissed it for the day. */}
          <motion.div layout transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}>
            <YesterdayDebriefCard timezone={profile?.timezone} />
          </motion.div>

          {/* Today's plan progress */}
          {userTasks.length > 0 && (
            <motion.div
              layout
              transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
              className="mt-4 app-card px-4 py-4 cursor-pointer tappable"
              onClick={() => nav("/today")}
              role="button"
              tabIndex={0}
              onKeyDown={(e) => e.key === "Enter" && nav("/today")}
              aria-label="Open today's plan"
            >
              <div className="flex items-center justify-between mb-3">
                <span className="eyebrow">Today's plan</span>
                <div className="flex items-center gap-2">
                  {doneTasks > 0 && doneTasks < userTasks.length && (
                    <span className="text-[12px] font-semibold text-primary tabular-nums">
                      {Math.round((doneTasks / userTasks.length) * 100)}%
                    </span>
                  )}
                  <span className="text-[12px] tabular-nums text-secondary-fg/70">
                    {doneTasks}/{userTasks.length}
                  </span>
                </div>
              </div>
              <div className="h-1.5 rounded-full bg-muted/55 overflow-hidden">
                <div
                  className="h-full rounded-full bg-primary/90 transition-[width] duration-700 ease-out"
                  style={{ width: `${(doneTasks / userTasks.length) * 100}%` }}
                />
              </div>
              {nextTask && doneTasks < userTasks.length && (
                <div className="mt-3 flex items-center gap-2">
                  <span className="text-[10px] font-semibold uppercase tracking-[0.12em] text-secondary-fg/55 shrink-0">Next</span>
                  <span className="text-[13px] font-medium text-foreground/90 truncate">{nextTask.title}</span>
                </div>
              )}
              {doneTasks === userTasks.length && (
                <div className="mt-2 text-[13px] font-semibold text-success">All done ✓</div>
              )}
            </motion.div>
          )}

          {/* Today categories breakdown — minimal, only if data */}
          {breakdown.length > 0 && (
            <motion.div layout transition={{ type: "spring", bounce: 0.2, duration: 0.6 }} className="mt-4 app-card px-4 py-3.5">
              <div className="flex items-center justify-between mb-3">
                <span className="eyebrow">Time tracked today</span>
                <span className="text-[11px] tabular-nums text-secondary-fg/55 font-medium">
                  {fmtHM(breakdown.reduce((s, r) => s + r.sec, 0))} total
                </span>
              </div>
              <ul className="space-y-2.5">
                {breakdown.map((row) => (
                  <li key={row.cat!.id} className="flex items-center gap-3">
                    <span className="h-2 w-2 rounded-full shrink-0" style={{ background: row.cat!.color }} />
                    <span className="text-[13px] font-medium text-foreground/85 truncate flex-1">{row.cat!.name}</span>
                    <div className="flex-1 max-w-[72px] h-[3px] rounded-full bg-foreground/[0.07] overflow-hidden">
                      <div className="h-full rounded-full" style={{ width: `${Math.max(8, row.pct * 100)}%`, background: row.cat!.color }} />
                    </div>
                    <span className="text-[12px] tabular-nums text-secondary-fg/80 font-medium w-[3.4rem] text-right">{fmtHM(row.sec)}</span>
                  </li>
                ))}
              </ul>
            </motion.div>
          )}
        </div>
    </PullToRefresh>
  );
}

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { useProfile } from "@/hooks/useProfile";
import { ArrowRight, Check, Sparkles } from "lucide-react";
import { enablePush, pushSupported } from "@/lib/push";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { TONE_OPTIONS, type Tone } from "@/lib/tone";

const PROGRESS_KEY = "dd_onboarding_progress_v3";
const TONE_KEYS = TONE_OPTIONS.map((o) => o.key);

export default function Onboarding() {
  const initial = (() => {
    try {
      const raw = sessionStorage.getItem(PROGRESS_KEY);
      if (!raw) return { step: 0, tone: "professional" as Tone, aiAbout: "" };
      const p = JSON.parse(raw);
      const step = [0, 1, 2].includes(p.step) ? p.step : 0;
      const tone = TONE_KEYS.includes(p.tone) ? (p.tone as Tone) : ("professional" as Tone);
      const aiAbout = typeof p.aiAbout === "string" ? p.aiAbout : "";
      return { step, tone, aiAbout };
    } catch {
      return { step: 0, tone: "professional" as Tone, aiAbout: "" };
    }
  })();

  const [step, setStep] = useState<number>(initial.step);
  const [tone, setTone] = useState<Tone>(initial.tone);
  const [aiAbout, setAiAbout] = useState(initial.aiAbout);
  const [finishing, setFinishing] = useState(false);
  const { profile, update, refresh } = useProfile();
  const nav = useNavigate();

  useEffect(() => {
    try {
      sessionStorage.setItem(PROGRESS_KEY, JSON.stringify({ step, tone, aiAbout }));
    } catch { /* ignore */ }
  }, [step, tone, aiAbout]);

  const finish = async (notif: boolean) => {
    if (finishing) return;
    setFinishing(true);
    let enabled = false;
    try {
      if (notif && pushSupported()) {
        try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) { await enablePush(session.user.id); enabled = true; }
        } catch (e: any) {
          if (e?.message && !/VAPID|configured/i.test(e.message)) toast(e.message);
        }
      }
      const tz = (() => { try { return Intl.DateTimeFormat().resolvedOptions().timeZone; } catch { return "UTC"; } })();
      try { localStorage.setItem("dd_ai_tone", tone); } catch { /* ignore */ }
      const payload = {
        ai_tone: tone as any,
        ai_context_custom: aiAbout.trim() || null,
        notifications_enabled: enabled,
        onboarded: true,
        timezone: tz,
      };
      if (profile) {
        await update(payload as any);
      } else {
        // No profile row yet (auth trigger missed). Upsert so the user never
        // gets stuck looping back to /onboarding for accounts where the auth
        // trigger didn't fire (e.g. historical sign-ups before the trigger
        // existed, or OAuth flows where the trigger raced with the session).
        const { data: { session } } = await supabase.auth.getSession();
        const uid = session?.user?.id;
        if (uid) {
          const { error } = await supabase
            .from("profiles")
            .upsert({ id: uid, ...payload } as never, { onConflict: "id" });
          if (error) throw error;
          await refresh();
        }
      }
      try { sessionStorage.removeItem(PROGRESS_KEY); } catch { /* ignore */ }
      nav("/home");
    } catch (e: any) {
      toast.error(e?.message || "Could not finish onboarding. Please try again.");
    } finally {
      setFinishing(false);
    }
  };

  return (
    <div className="min-h-screen w-full bg-background flex justify-center">
      <div className="relative w-full max-w-[440px] min-h-screen flex flex-col">
        <div className="pointer-events-none absolute inset-x-0 top-0 h-[240px]" style={{ background: "var(--gradient-glow)" }} />
        <div className="relative z-10 flex-1 flex flex-col px-6 pt-14 pb-10 page-enter" key={step}>
          <div className="flex gap-1.5 mb-8">
            {[0, 1, 2].map((i) => (
              <div key={i} className={`h-[3px] flex-1 rounded-full transition-colors ${i <= step ? "bg-primary" : "bg-border/70"}`} />
            ))}
          </div>

          {step === 0 && (
            <div className="flex-1 flex flex-col">
              <div className="flex-1 flex flex-col justify-center">
                <p className="eyebrow">DayDraft</p>
                <h1 className="font-display text-[38px] font-semibold leading-[1.05] tracking-tight mt-3 text-balance">
                  Your day, distilled.
                </h1>
                <p className="text-secondary-fg mt-5 text-[15px] leading-[1.55] max-w-sm">
                  Track time, plan tasks your way, ask AI only when you want a nudge.
                </p>
                <div className="mt-6 app-card px-4 py-5 space-y-2 fade-in">
                  <div className="text-[11px] uppercase tracking-wider text-secondary-fg inline-flex items-center gap-1.5">
                    <Sparkles className="h-3.5 w-3.5 text-primary" /> Quiet by default
                  </div>
                  <div className="text-[13px] text-subtle">No auto-planning. No noise. You're in control.</div>
                </div>
              </div>
              <Button disabled={finishing} onClick={() => setStep(1)} className="w-full h-[52px] rounded-[16px] bg-primary text-primary-foreground hover:bg-primary/92 pressable text-[15px] font-medium shadow-card">
                Continue <ArrowRight className="h-4 w-4" />
              </Button>
            </div>
          )}

          {step === 1 && (
            <div className="flex-1 flex flex-col">
              <h1 className="font-display text-[26px] font-semibold leading-tight mt-2 tracking-tight text-balance">
                Pick the AI voice
              </h1>
              <p className="text-secondary-fg mt-2 text-[13px] leading-[1.55]">
                Used only when you ask for help.
              </p>
              <div className="space-y-2 mt-5 flex-1 overflow-y-auto">
                {TONE_OPTIONS.map((e) => {
                  const active = tone === e.key;
                  return (
                    <button
                      key={e.key}
                      onClick={() => setTone(e.key)}
                      className={`w-full flex items-center gap-3 p-3.5 rounded-[16px] border pressable transition-all backdrop-blur-sm ${active ? "border-accent surface-accent" : "border-soft surface-card hover:border-strong"}`}
                    >
                      <span className="text-lg">{e.emoji}</span>
                      <div className="flex-1 text-left">
                        <div className="font-medium text-[14px]">{e.title}</div>
                        <div className="text-[11.5px] text-secondary-fg leading-snug mt-0.5">{e.sub}</div>
                      </div>
                      <span className={`h-[18px] w-[18px] rounded-full border flex items-center justify-center transition-all shrink-0 ${active ? "border-primary bg-primary" : "border-soft"}`}>
                        {active && <Check className="h-3 w-3 text-primary-foreground" strokeWidth={3} />}
                      </span>
                    </button>
                  );
                })}
              </div>
              <Button disabled={finishing} onClick={() => setStep(2)} className="w-full h-[52px] rounded-[16px] bg-primary text-primary-foreground hover:bg-primary/92 pressable text-[15px] font-medium mt-5 shadow-card">
                Continue
              </Button>
            </div>
          )}

          {step === 2 && (
            <div className="flex-1 flex flex-col min-h-0">
              <h1 className="font-display text-[26px] font-semibold leading-tight mt-2 tracking-tight text-balance">
                A line about you (optional)
              </h1>
              <p className="text-secondary-fg mt-2 text-[13px] leading-[1.55]">
                Helps AI answers land right. Skip if you'd rather not.
              </p>
              <div className="mt-5 flex-1 min-h-0">
                <Textarea
                  value={aiAbout}
                  onChange={(e) => setAiAbout(e.target.value)}
                  placeholder="e.g. I'm a parent of a 4yo, work remote, prefer deep work after lunch."
                  maxLength={500}
                  className="min-h-[120px] surface-card border-soft rounded-xl text-[13px] resize-none"
                />
                <p className="mt-1 text-[10px] text-secondary-fg">{aiAbout.length}/500</p>
              </div>
              <Button disabled={finishing} onClick={() => finish(true)} className="w-full h-[52px] rounded-[16px] bg-primary text-primary-foreground hover:bg-primary/92 pressable text-[15px] font-medium mt-5 shadow-card shrink-0">
                Enable nudges & finish
              </Button>
              <button disabled={finishing} onClick={() => finish(false)} className="mt-3 text-secondary-fg text-[13px] hover:text-foreground transition-colors mx-auto disabled:opacity-60 disabled:pointer-events-none">
                Finish without nudges
              </button>
            </div>
          )}

          {step > 0 && (
            <button
              type="button"
              disabled={finishing}
              onClick={() => setStep((s) => Math.max(0, s - 1))}
              className="mt-4 text-[12px] text-secondary-fg hover:text-foreground mx-auto disabled:opacity-50 disabled:pointer-events-none"
            >
              Back
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

import { lazy, Suspense, useMemo, useState } from "react";
import { keepPreviousData, useQuery } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { BarChart3, ChevronDown, Download, FileText } from "lucide-react";
import { motion } from "framer-motion";

// Recharts is its own ~100kB chunk. Lazy-load it so the Reports first paint
// shows headline numbers + the per-day list while the chart streams in.
const ReportsTrendChart = lazy(() => import("@/components/app/ReportsTrendChart"));
import {
  downloadReportCsv,
  downloadReportPdf,
  type ReportPaymentDetails,
  type ReportPayload,
  type ReportPaymentSection,
} from "@/lib/reportExport";
import {
  mergeCategoryPayment,
  paymentDetailsHasContent,
  type CategoryBillingRow,
} from "@/lib/categoryBilling";
import { toast } from "sonner";
import { useEntitlement } from "@/hooks/useEntitlement";
import { UpgradeSheet } from "@/components/app/UpgradeSheet";
import { TickingNumber } from "@/components/app/TickingNumber";
import { useTimeTracker, useTimeTrackerElapsed } from "@/hooks/useTimeTracker";
import {
  filterEntriesByRange,
  rollingEntriesQueryKey,
  fetchRollingEntries,
  type RollingEntry,
} from "@/lib/timeEntriesQuery";

type Period = "day" | "week" | "month";

function periodRange(period: Period): { from: Date; to: Date; label: string; periodLabel: string } {
  const now = new Date();
  const to = new Date(now);
  to.setHours(23, 59, 59, 999);
  const from = new Date(now);
  if (period === "day") {
    from.setHours(0, 0, 0, 0);
  } else if (period === "week") {
    const dow = (from.getDay() + 6) % 7; // Mon = 0
    from.setDate(from.getDate() - dow);
    from.setHours(0, 0, 0, 0);
  } else {
    from.setDate(1);
    from.setHours(0, 0, 0, 0);
  }
  const fmt = (d: Date) => d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
  const label = period === "day" ? fmt(from) : `${fmt(from)} – ${fmt(to)}`;
  const periodLabel = period === "day" ? "Day" : period === "week" ? "Week" : "Month";
  return { from, to, label, periodLabel };
}

const fmtHM = (sec: number) => {
  const m = Math.round(sec / 60);
  const h = Math.floor(m / 60);
  const mm = m % 60;
  if (!h) return `${mm}m`;
  return mm ? `${h}h ${mm}m` : `${h}h`;
};

function paymentFingerprint(d: ReportPaymentDetails): string {
  return [
    d.currency ?? "",
    d.paymentMethod ?? "",
    d.displayName ?? "",
    d.bankName ?? "",
    d.iban ?? "",
    d.cryptoNetwork ?? "",
    d.cryptoWallet ?? "",
    d.paymentLink ?? "",
    d.notes ?? "",
  ].join("");
}

const fmtMoney = (amount: number, currency = "USD") => {
  const code = String(currency || "USD").trim().toUpperCase();
  try {
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency: code,
      maximumFractionDigits: Math.abs(amount) >= 100 ? 0 : 2,
    }).format(amount);
  } catch {
    return `${Math.abs(amount) >= 100 ? amount.toFixed(0) : amount.toFixed(2)} ${code}`;
  }
};

type CategoryGroup = {
  id: string;
  name: string;
  color: string;
  currency: string;
  hourlyRate: number | null;
  sec: number;
  earnings: number;
  pct: number;
  entries: RollingEntry[];
};

export default function Reports() {
  const { user } = useAuth();
  const { isPro } = useEntitlement();
  // Categories already live in the TimeTrackerProvider — reading them from the
  // shared context avoids a Reports-only fetch on every tab switch.
  const { categories } = useTimeTracker();
  // Subscribing to elapsedSec keeps live totals (running timer in the active
  // category) ticking inside Reports without a per-tab Supabase query.
  useTimeTrackerElapsed();
  const [period, setPeriod] = useState<Period>("week");
  const [expandedCategoryIds, setExpandedCategoryIds] = useState<Set<string>>(() => new Set());
  const [upgradeOpen, setUpgradeOpen] = useState(false);
  const range = useMemo(() => periodRange(period), [period]);

  const { data: rollingEntries = [] } = useQuery({
    queryKey: rollingEntriesQueryKey(user?.id),
    queryFn: () => fetchRollingEntries(user!.id),
    enabled: !!user?.id,
    staleTime: 60_000,
    gcTime: 30 * 60_000,
    placeholderData: keepPreviousData,
  });

  const { data: paymentDetails = null } = useQuery({
    queryKey: ["billing-payment-details", user?.id],
    enabled: !!user?.id && isPro,
    staleTime: 5 * 60_000,
    gcTime: 30 * 60_000,
    placeholderData: keepPreviousData,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("billing_payment_details")
        .select("display_name,bank_name,iban,crypto_network,crypto_wallet,payment_link,notes")
        .eq("user_id", user!.id)
        .maybeSingle();
      if (error) return null;
      if (!data) return null;
      return {
        displayName: data.display_name,
        bankName: data.bank_name,
        iban: data.iban,
        cryptoNetwork: data.crypto_network,
        cryptoWallet: data.crypto_wallet,
        paymentLink: data.payment_link,
        notes: data.notes,
      } satisfies ReportPaymentDetails;
    },
  });

  const catMap = useMemo(
    () => new Map(categories.map((c) => [c.id, c])),
    [categories],
  );

  const periodEntries = useMemo(
    () => filterEntriesByRange(rollingEntries, range),
    [rollingEntries, range],
  );

  // Single pass through entries — previously this file built two near-identical
  // aggregations (`byCategory` and `categoryGroups`) which doubled the work on
  // every period change. One walk computes totals, per-category sums, per-day
  // sums, and per-category entry lists at once.
  const { totalSec, totalEarnings, categoryGroups, perDay } = useMemo(() => {
    const now = Date.now();
    let total = 0;
    let earnedTotal = 0;
    const groups = new Map<string, CategoryGroup>();
    const dMap = new Map<string, number>();
    for (const e of periodEntries) {
      const s = new Date(e.started_at).getTime();
      const en = e.ended_at ? new Date(e.ended_at).getTime() : now;
      const sec = Math.max(0, (en - s) / 1000);
      if (sec <= 0) continue;
      total += sec;
      const id = e.category_id || "uncategorized";
      const cat = (e.category_id ? catMap.get(e.category_id) : undefined) as
        | (typeof categories)[number]
        | undefined;
      const rate = cat?.hourly_rate ?? null;
      const earned = ((rate || 0) * sec) / 3600;
      earnedTotal += earned;
      let group = groups.get(id);
      if (!group) {
        group = {
          id,
          name: cat?.name || "Uncategorized",
          color: cat?.color || "hsl(var(--muted-foreground))",
          currency: cat?.currency || "USD",
          hourlyRate: rate,
          sec: 0,
          earnings: 0,
          pct: 0,
          entries: [],
        };
        groups.set(id, group);
      }
      group.sec += sec;
      group.earnings += earned;
      group.entries.push(e);

      const d = new Date(s);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
      dMap.set(key, (dMap.get(key) || 0) + sec);
    }
    const groupList = Array.from(groups.values())
      .map((g) => ({ ...g, pct: total > 0 ? g.sec / total : 0 }))
      .sort((a, b) => b.sec - a.sec);
    const perDay = Array.from(dMap.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, sec]) => ({
        day: k.slice(5),
        hours: Number((sec / 3600).toFixed(2)),
      }));
    return {
      totalSec: total,
      totalEarnings: earnedTotal,
      categoryGroups: groupList,
      perDay,
    };
  }, [periodEntries, catMap]);

  const toggleCategoryExpanded = (id: string) => {
    setExpandedCategoryIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const buildPayload = (categoryIds?: string[], scopeLabel = "All categories"): ReportPayload => {
    const idSet = categoryIds?.length ? new Set(categoryIds) : null;
    const filteredCategories = idSet
      ? categoryGroups.filter((c) => idSet.has(c.id))
      : categoryGroups;
    const filteredEntries = idSet
      ? periodEntries.filter((e) => idSet.has(e.category_id || "uncategorized"))
      : periodEntries;
    const filteredTotal = filteredCategories.reduce((sum, c) => sum + c.sec, 0);
    const filteredEarnings = filteredCategories.reduce((sum, c) => sum + c.earnings, 0);

    const globalPayment = isPro ? paymentDetails : null;
    const paymentBuckets = new Map<string, { details: ReportPaymentDetails; names: string[] }>();
    for (const c of filteredCategories) {
      const row =
        c.id === "uncategorized" ? undefined : (catMap.get(c.id) as CategoryBillingRow | undefined);
      const merged = mergeCategoryPayment(row, globalPayment);
      if (!paymentDetailsHasContent(merged)) continue;
      const key = paymentFingerprint(merged!);
      const cur = paymentBuckets.get(key);
      if (cur) {
        if (!cur.names.includes(c.name)) cur.names.push(c.name);
      } else {
        paymentBuckets.set(key, { details: merged!, names: [c.name] });
      }
    }
    const paymentSections: ReportPaymentSection[] = Array.from(paymentBuckets.values()).map(
      ({ details, names }) => ({
        title: names.length === 1 ? `Payment — ${names[0]}` : `Payment — ${names.join(", ")}`,
        details,
      }),
    );

    const paymentBlock =
      paymentSections.length === 0
        ? { paymentDetails: null as ReportPaymentDetails | null, paymentSections: null as ReportPaymentSection[] | null }
        : paymentSections.length === 1
          ? { paymentDetails: paymentSections[0].details, paymentSections: null as ReportPaymentSection[] | null }
          : { paymentDetails: null as ReportPaymentDetails | null, paymentSections };

    return {
      periodLabel: range.periodLabel,
      rangeLabel: range.label,
      scopeLabel,
      totalSeconds: filteredTotal,
      totalEarnings: filteredEarnings,
      ...paymentBlock,
      categories: filteredCategories.map((c) => ({
        name: c.name,
        color: c.color,
        seconds: c.sec,
        currency: c.currency,
        hourlyRate: c.hourlyRate,
        earnings: c.earnings,
        pct: filteredTotal > 0 ? c.sec / filteredTotal : 0,
      })),
      entries: filteredEntries.map((e) => {
        const s = new Date(e.started_at);
        const en = e.ended_at ? new Date(e.ended_at) : new Date();
        const cat = e.category_id ? catMap.get(e.category_id) : undefined;
        const durationMin = Math.max(0, Math.round((en.getTime() - s.getTime()) / 60000));
        const hourlyRate = cat?.hourly_rate ?? null;
        const currency = cat?.currency || "USD";
        return {
          date: s.toLocaleDateString(),
          startedAt: s.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
          endedAt: en.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
          category: cat?.name || "Uncategorized",
          durationMin,
          currency,
          hourlyRate,
          earnings: ((hourlyRate || 0) * durationMin) / 60,
          note: e.note ?? null,
        };
      }),
    };
  };

  const onExport = async (kind: "pdf" | "csv", categoryIds?: string[], scopeLabel?: string) => {
    if (!isPro) {
      setUpgradeOpen(true);
      return;
    }
    const payload = buildPayload(categoryIds, scopeLabel || "All categories");
    try {
      if (kind === "pdf") await downloadReportPdf(payload);
      else await downloadReportCsv(payload);
      if (!payload.entries.length) toast("Exported an empty report — no entries in this period");
    } catch (e: any) {
      toast.error(e?.message || "Export failed");
    }
  };

  return (
    <>
      <div className="flex min-h-0 flex-1 flex-col px-5 pt-7 pb-6">
        <header className="mb-5 shrink-0">
          <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-secondary-fg/65">
            Reports
          </p>
          <h1 className="mt-1 font-display text-[26px] font-semibold tracking-[-0.02em]">
            Time insights
          </h1>
        </header>

        {/*
          Period segmented control. Active uses a primary-tinted pill +
          ring rather than `bg-background`, which on dark mode is pure
          black and disappeared into the parent track. The underlay
          slides between buttons via transform so the selection reads
          as one continuous motion. Buttons are an equal-width 3-col
          grid so the slide hits each pill exactly.
        */}
        <div
          className="shrink-0 mb-5 relative isolate grid grid-cols-3 p-1 rounded-2xl bg-muted border border-border/40 self-start w-[220px]"
          role="tablist"
        >
          {(["day", "week", "month"] as Period[]).map((p) => (
            <button
              key={p}
              type="button"
              role="tab"
              aria-selected={period === p}
              onClick={() => setPeriod(p)}
              className={`relative z-[1] h-8 rounded-xl text-[12px] font-semibold capitalize transition-colors duration-200 pressable ${
                period === p
                  ? "text-primary-foreground"
                  : "text-secondary-fg/85 hover:text-foreground"
              }`}
            >
              {period === p && (
                <motion.div
                  layoutId="reports-period-tab"
                  className="absolute inset-0 rounded-xl bg-primary shadow-sm"
                  transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
                  style={{ zIndex: -1 }}
                />
              )}
              {p}
            </button>
          ))}
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto space-y-5 pb-4 -mx-5 px-5">
          {/*
            Hero-glass top card so Reports has the same luminous primary
            tint at the top of the column that Home's HomeTrackerHero
            provides. Without this, Reports felt flatter / darker than
            the other tabs even though the Shell background is identical.
          */}
          <section className="rounded-[28px] hero-glass border border-border/35 px-5 pt-5 pb-4">
            <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-secondary-fg/70">
              Total tracked
            </p>
            <div className="mt-1.5 flex items-end justify-between gap-3">
              <p className="font-display text-[40px] font-semibold tabular-nums leading-none overflow-hidden">
                <TickingNumber value={fmtHM(totalSec)} />
              </p>
              {totalEarnings > 0 && (
                <div className="text-right">
                  <p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-secondary-fg/70">
                    Estimated pay
                  </p>
                  <p className="font-display text-[22px] font-semibold tabular-nums text-primary overflow-hidden">
                    <TickingNumber value={fmtMoney(totalEarnings, categoryGroups[0]?.currency || "USD")} />
                  </p>
                </div>
              )}
            </div>
            <p className="mt-2 text-[12px] text-secondary-fg/80">{range.label}</p>
          </section>

          {categoryGroups.length > 0 ? (
            <section className="app-card p-4">
              <div className="mb-3 flex items-start justify-between gap-3">
                <div>
                  <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-secondary-fg/70">
                    By category
                  </p>
                  <p className="mt-1 text-[11px] text-secondary-fg/70">
                    Expand a category to see its tracker history for this period.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    if (expandedCategoryIds.size === categoryGroups.length) setExpandedCategoryIds(new Set());
                    else setExpandedCategoryIds(new Set(categoryGroups.map((g) => g.id)));
                  }}
                  className="shrink-0 text-[11px] font-semibold text-primary pressable"
                >
                  {expandedCategoryIds.size === categoryGroups.length ? "Collapse all" : "Expand all"}
                </button>
              </div>
              <div className="h-2 w-full rounded-full overflow-hidden flex bg-muted/40 mb-3">
                {categoryGroups.map((c) => (
                  <div
                    key={c.id}
                    style={{ width: `${c.pct * 100}%`, background: c.color }}
                    className="h-full first:rounded-l-full last:rounded-r-full"
                  />
                ))}
              </div>
              <ul className="space-y-2 enter-stagger">
                {categoryGroups.map((group) => {
                  const isOpen = expandedCategoryIds.has(group.id);
                  return (
                    <li key={group.id} className="overflow-hidden rounded-2xl border border-border/35 bg-background/30">
                      <button
                        type="button"
                        onClick={() => toggleCategoryExpanded(group.id)}
                        className="flex w-full items-start gap-3 px-3 py-3 text-left pressable"
                        aria-expanded={isOpen}
                      >
                        <span
                          className="mt-1.5 h-2.5 w-2.5 rounded-full shrink-0"
                          style={{ background: group.color }}
                        />
                        <div className="min-w-0 flex-1">
                          <div className="flex items-baseline justify-between gap-3">
                            <span className="text-[13px] font-semibold text-foreground/95 truncate">
                              {group.name}
                            </span>
                            <span className="text-[12px] tabular-nums text-secondary-fg/85 shrink-0">
                              {fmtHM(group.sec)}
                            </span>
                          </div>
                          <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] tabular-nums text-secondary-fg/70">
                            <span>{(group.pct * 100).toFixed(0)}% of period</span>
                            <span>
                              {group.entries.length} session{group.entries.length === 1 ? "" : "s"}
                            </span>
                            {group.hourlyRate ? (
                              <span>{fmtMoney(group.hourlyRate, group.currency)}/h</span>
                            ) : (
                              <span>No rate</span>
                            )}
                            {group.earnings > 0 && (
                              <span className="font-semibold text-primary">
                                {fmtMoney(group.earnings, group.currency)} earned
                              </span>
                            )}
                          </div>
                        </div>
                        <ChevronDown
                          className={`mt-0.5 h-4 w-4 shrink-0 text-secondary-fg transition-transform ${
                            isOpen ? "rotate-180" : ""
                          }`}
                        />
                      </button>
                      {isOpen && (
                        <div className="border-t border-border/30">
                          <ul className="divide-y divide-border/30">
                            {group.entries.map((e) => {
                              const s = new Date(e.started_at);
                              const en = e.ended_at ? new Date(e.ended_at) : new Date();
                              const sec = Math.max(0, (en.getTime() - s.getTime()) / 1000);
                              const earned = ((group.hourlyRate || 0) * sec) / 3600;
                              return (
                                <li key={e.id} className="flex items-center gap-3 px-4 py-2.5">
                                  <div className="min-w-0 flex-1">
                                    <p className="text-[11px] text-secondary-fg/75 tabular-nums">
                                      {s.toLocaleDateString(undefined, { month: "short", day: "numeric" })} ·{" "}
                                      {s.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })} -{" "}
                                      {en.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
                                    </p>
                                    {e.note && (
                                      <p className="mt-0.5 truncate text-[12px] text-foreground/80">{e.note}</p>
                                    )}
                                  </div>
                                  <span className="text-right">
                                    <span className="block text-[12px] tabular-nums text-secondary-fg/85">
                                      {fmtHM(sec)}
                                    </span>
                                    {earned > 0 && (
                                      <span className="block text-[10px] tabular-nums text-primary">
                                        {fmtMoney(earned, group.currency)}
                                      </span>
                                    )}
                                  </span>
                                </li>
                              );
                            })}
                          </ul>
                          <div className="grid grid-cols-2 gap-2 px-4 py-3">
                            <button
                              type="button"
                              onClick={() => onExport("pdf", [group.id], group.name)}
                              className="h-8 rounded-xl border border-border/40 text-[11px] font-semibold text-secondary-fg/85 pressable hover:text-foreground"
                              aria-label={`Download PDF report for ${group.name}`}
                            >
                              PDF
                            </button>
                            <button
                              type="button"
                              onClick={() => onExport("csv", [group.id], group.name)}
                              className="h-8 rounded-xl border border-border/40 text-[11px] font-semibold text-secondary-fg/85 pressable hover:text-foreground"
                              aria-label={`Download CSV report for ${group.name}`}
                            >
                              CSV
                            </button>
                          </div>
                        </div>
                      )}
                    </li>
                  );
                })}
              </ul>
            </section>
          ) : (
            <section className="rounded-2xl border border-dashed border-border/40 px-4 py-8 text-center">
              <BarChart3 className="h-6 w-6 mx-auto text-secondary-fg/60 mb-2" />
              <p className="text-[13px] text-secondary-fg/85">No tracked time in this period</p>
              <p className="text-[11px] text-secondary-fg/60 mt-1">
                Start a timer on the Track tab to fill this in.
              </p>
            </section>
          )}

          {period !== "day" && perDay.length > 1 && (
            <section className="app-card p-4">
              <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-secondary-fg/70 mb-2">
                Daily trend
              </p>
              <div className="h-32 -mx-2">
                <Suspense fallback={<div className="h-full w-full rounded-xl shimmer opacity-60" />}>
                  <ReportsTrendChart perDay={perDay} />
                </Suspense>
              </div>
            </section>
          )}

          <section className="space-y-2 pt-2">
            {!isPro && (
              <p className="text-[11px] text-secondary-fg/70 px-0.5">
                PDF and CSV export with billing details is included with Pro.
              </p>
            )}
            <div className="grid grid-cols-2 gap-2">
              <Button
                variant="outline"
                onClick={() => onExport("pdf")}
                className="h-11 rounded-2xl border-border/50 text-[13px] font-medium"
              >
                <FileText className="h-4 w-4 mr-1.5" /> Export PDF
              </Button>
              <Button
                variant="outline"
                onClick={() => onExport("csv")}
                className="h-11 rounded-2xl border-border/50 text-[13px] font-medium"
              >
                <Download className="h-4 w-4 mr-1.5" /> Export CSV
              </Button>
            </div>
          </section>
        </div>
      </div>
      <UpgradeSheet open={upgradeOpen} onOpenChange={setUpgradeOpen} reason="feature" />
    </>
  );
}

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

export default function ResetPassword() {
  const [pw, setPw] = useState("");
  const [pw2, setPw2] = useState("");
  const [busy, setBusy] = useState(false);
  const [ready, setReady] = useState(false);
  const nav = useNavigate();

  useEffect(() => {
    // Supabase puts tokens in the URL hash for recovery flows. Detect a recovery session.
    const sub = supabase.auth.onAuthStateChange((event) => {
      if (event === "PASSWORD_RECOVERY" || event === "SIGNED_IN") setReady(true);
    });
    supabase.auth.getSession().then(({ data }) => { if (data.session) setReady(true); });
    return () => sub.data.subscription.unsubscribe();
  }, []);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (pw.length < 6) return toast.error("Password must be at least 6 characters");
    if (pw !== pw2) return toast.error("Passwords don't match");
    setBusy(true);
    try {
      const { error } = await supabase.auth.updateUser({ password: pw });
      if (error) throw error;
      toast.success("Password updated");
      nav("/today", { replace: true });
    } catch (err: any) {
      toast.error(err.message || "Couldn't update password");
    } finally { setBusy(false); }
  };

  return (
    <div className="min-h-screen w-full bg-background flex justify-center">
      <div className="relative w-full max-w-[400px] min-h-screen flex flex-col">
        <div className="pointer-events-none absolute inset-x-0 top-0 h-[200px]" style={{ background: "var(--gradient-glow)" }} />
        <div className="relative z-10 flex-1 flex flex-col px-6 pt-16 pb-10">
          <h1 className="font-display text-[26px] font-semibold leading-tight text-balance">New password</h1>
          <p className="text-secondary-fg mt-2.5 text-[13px] leading-[1.55]">
            {ready ? "Pick something you'll remember." : "Verifying reset link..."}
          </p>
          {ready && (
            <form onSubmit={submit} className="mt-9 space-y-3">
              <Input type="password" required minLength={6} value={pw} onChange={e => setPw(e.target.value)} placeholder="New password"
                className="h-12 surface-card border-soft rounded-[14px]" />
              <Input type="password" required minLength={6} value={pw2} onChange={e => setPw2(e.target.value)} placeholder="Confirm password"
                className="h-12 surface-card border-soft rounded-[14px]" />
              <Button type="submit" disabled={busy} className="w-full h-12 rounded-[14px] bg-primary text-primary-foreground hover:bg-primary/90 pressable text-base font-medium shadow-card">
                {busy ? "..." : "Update password"}
              </Button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}

import { useProfile } from "@/hooks/useProfile";
import { useAuth } from "@/hooks/useAuth";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { useEffect, useState } from "react";
import { ThemeToggle } from "@/components/app/ThemeToggle";
import { Fingerprint, Sparkles, Bell, Calendar, FileText, Shield, Trash2, HelpCircle } from "lucide-react";
import { Link, useNavigate, useLocation } from "react-router-dom";
import { clearStoredPasskey, enrollPasskey, getStoredPasskey, passkeySupported } from "@/lib/passkeys";
import { toast } from "sonner";
import { useEntitlement } from "@/hooks/useEntitlement";
import { isSimulateProUiAllowed, writeDevSimulatePro } from "@/lib/devEntitlement";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@/components/ui/sheet";
import { UpgradeSheet } from "@/components/app/UpgradeSheet";
import { ProFeatureHighlights } from "@/components/app/ProFeatureHighlights";
import { enablePush, disablePush, pushAvailability, pushAvailabilityCopy } from "@/lib/push";
import { useTour, TOUR_TODAY } from "@/components/app/Tour";
import { VisualMode, useVisualMode } from "@/lib/visualMode";
import { PerfDebugPanel } from "@/components/app/PerfDebugPanel";

export default function Settings() {
  const { profile, update } = useProfile();
  const { signOut, user } = useAuth();
  const tour = useTour();
  const nav = useNavigate();
  const location = useLocation();
  const [name, setName] = useState("");
  const [hasPasskey, setHasPasskey] = useState(!!getStoredPasskey());
  const { entitlement, isPro, devSimulatePro, subscriptionPro, planQuotaUsed, planQuotaLimit, planQuotaRemaining } = useEntitlement();
  const [upgradeOpen, setUpgradeOpen] = useState(false);
  const [proSheetOpen, setProSheetOpen] = useState(false);
  const [calConnecting, setCalConnecting] = useState(false);
  const [visualMode, setVisualMode] = useVisualMode();
  const [pushState] = useState(() => pushAvailability());
  const pushReady = pushState === "ok";
  // Hidden developer panel — tap the version label 10× in 3s to open.
  const [versionTaps, setVersionTaps] = useState(0);
  const [perfPanelOpen, setPerfPanelOpen] = useState(false);
  useEffect(() => {
    if (versionTaps === 0) return;
    const id = window.setTimeout(() => setVersionTaps(0), 3000);
    return () => window.clearTimeout(id);
  }, [versionTaps]);
  useEffect(() => { if (profile) setName(profile.display_name || ""); }, [profile]);

  useEffect(() => {
    const hash = location.hash;
    if (hash === "#pro-features") {
      setProSheetOpen(true);
      return;
    }
    if (hash !== "#week-intention") return;
    const id = requestAnimationFrame(() => {
      document.getElementById("week-intention")?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
    return () => cancelAnimationFrame(id);
  }, [location.hash]);

  const togglePasskey = async () => {
    if (hasPasskey) {
      clearStoredPasskey();
      setHasPasskey(false);
      update({ passkey_enabled: false } as any);
      toast.success("Face ID / fingerprint disabled");
      return;
    }
    if (!user) return;
    if (!passkeySupported()) { toast.error("Not supported on this device"); return; }
    try {
      await enrollPasskey({
        userId: user.id,
        userEmail: user.email || "user@daydraft.app",
        userName: profile?.display_name || user.email || "DayDraft user",
      });
      setHasPasskey(true);
      update({ passkey_enabled: true } as any);
      toast.success("Face ID / fingerprint enabled");
    } catch (e: any) {
      toast.error(e?.message || "Unable to enable passkey");
    }
  };

  const togglePush = async (v: boolean) => {
    if (!user) return;
    if (v && !pushReady) {
      // Don't toast — the inline helper under the row already explains why and
      // what to do. Toasting on every tap is noise.
      return;
    }
    try {
      if (v) {
        await enablePush(user.id);
        update({ notifications_enabled: true });
        toast.success("Notifications enabled");
      } else {
        await disablePush(user.id);
        update({ notifications_enabled: false });
      }
    } catch (e: any) {
      toast.error(e.message || "Unable to update notification settings");
    }
  };

  const calendarClientId = import.meta.env.VITE_GOOGLE_CALENDAR_CLIENT_ID as string | undefined;
  const calendarAvailable = !!calendarClientId;

  const connectCalendar = async () => {
    if (!calendarAvailable) {
      toast("Calendar sync is coming soon — we'll let you know.");
      return;
    }
    if (!isPro) { setUpgradeOpen(true); return; }
    setCalConnecting(true);
    try {
      const redirect = `${window.location.origin}/settings`;
      const scope = encodeURIComponent("https://www.googleapis.com/auth/calendar.readonly");
      const url = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${calendarClientId}&redirect_uri=${encodeURIComponent(redirect)}&response_type=code&access_type=offline&prompt=consent&scope=${scope}`;
      window.location.href = url;
    } finally {
      setCalConnecting(false);
    }
  };

  return (
    <>
      <div className="px-5 pt-12">
        <p className="eyebrow">Account</p>
        <h1 className="type-title mt-2 text-balance">Settings</h1>

        <div className="mt-8 space-y-8">
          <ProCard
            entitlement={entitlement} isPro={isPro} subscriptionPro={subscriptionPro} devSimulatePro={devSimulatePro}
            planQuotaUsed={planQuotaUsed} planQuotaLimit={planQuotaLimit} planQuotaRemaining={planQuotaRemaining}
            onUpgrade={() => setUpgradeOpen(true)}
            onOpenDetails={!isPro ? () => setProSheetOpen(true) : undefined}
          />
          {isSimulateProUiAllowed() && (
            <Section title="Developer">
              <div className="rounded-[14px] border border-dashed border-soft surface-card px-4 py-3 space-y-2">
                <div className="flex items-center justify-between gap-3">
                  <div>
                    <div className="text-[14px] text-foreground">Simulate Pro</div>
                    <p className="text-[11px] text-secondary-fg mt-1 leading-relaxed">
                      Unlocks Pro UI in this browser. Server planning quota still follows your real subscription unless you enable this for testing.
                    </p>
                  </div>
                  <Switch
                    checked={!!devSimulatePro}
                    onCheckedChange={(v) => writeDevSimulatePro(v)}
                  />
                </div>
              </div>
            </Section>
          )}

          {/* 2. Profile — name + appearance grouped */}
          <Section title="You">
            <div className="rounded-[14px] border border-soft surface-card backdrop-blur-sm divide-y divide-border/50 overflow-hidden">
              <div className="px-3 py-2.5">
                <div className="text-[11px] text-secondary-fg mb-1">Name</div>
                <Input value={name} onChange={e => setName(e.target.value)} onBlur={() => update({ display_name: name })}
                  className="h-9 bg-transparent border-0 px-0 focus-visible:ring-0 text-[14px]" />
              </div>
              <div className="px-3 py-3">
                <div className="text-[11px] text-secondary-fg mb-2">Appearance</div>
                <ThemeToggle />
                <div className="mt-3">
                  <div className="text-[11px] text-secondary-fg mb-1.5">Visual mode</div>
                  <div className="grid grid-cols-2 gap-2">
                    {([
                      { key: "standard", label: "Standard" },
                      { key: "neon", label: "Neon" },
                    ] as Array<{ key: VisualMode; label: string }>).map((opt) => (
                      <button
                        key={opt.key}
                        type="button"
                        onClick={() => setVisualMode(opt.key)}
                        className={`h-9 rounded-lg border text-[11px] font-medium pressable ${
                          visualMode === opt.key
                            ? "surface-accent border-accent text-primary"
                            : "surface-soft border-soft text-secondary-fg"
                        }`}
                      >
                        {opt.label}
                      </button>
                    ))}
                  </div>
                  <p className="mt-2 text-[11px] text-secondary-fg leading-relaxed">
                    Standard — calm, clean interface. Neon — brighter accents and glow.
                  </p>
                </div>
              </div>
            </div>
          </Section>

          {/* 4. Notifications + Calendar — connected channels */}
          <Section title="Connections">
            <div className="rounded-[14px] border border-soft surface-card backdrop-blur-sm divide-y divide-border/50 overflow-hidden">
              <div className="px-4 py-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3 min-w-0">
                    <Bell className={`h-4 w-4 ${pushReady ? "text-secondary-fg" : "text-secondary-fg/55"}`} />
                    <div className="min-w-0">
                      <div className={`text-[14px] ${pushReady ? "" : "text-foreground/70"}`}>Daily nudges</div>
                      {pushReady && (
                        <div className="text-[11px] text-secondary-fg/75 mt-0.5">
                          Gentle pings as your day unfolds.
                        </div>
                      )}
                    </div>
                  </div>
                  <Switch
                    checked={pushReady && !!profile?.notifications_enabled}
                    disabled={!pushReady}
                    onCheckedChange={togglePush}
                  />
                </div>
                {!pushReady && (
                  <div className="mt-2.5 rounded-[10px] border border-primary/20 bg-primary/[0.06] px-3 py-2.5">
                    <div className="text-[12px] font-medium text-foreground/90 leading-snug">
                      {pushAvailabilityCopy[pushState].title}
                    </div>
                    <p className="text-[11.5px] text-secondary-fg mt-1 leading-relaxed">
                      {pushAvailabilityCopy[pushState].body}
                    </p>
                  </div>
                )}
              </div>
              <button onClick={connectCalendar}
                className="w-full flex items-center justify-between px-4 py-3 ios-row">
                <div className="flex items-center gap-3">
                  <Calendar className="h-4 w-4 text-secondary-fg" />
                  <div className="text-[14px] text-left">Google Calendar</div>
                </div>
                <span className="text-[12px] font-medium text-secondary-fg/80">
                  {calendarAvailable ? (isPro ? "Connect" : "Pro") : "Soon"}
                </span>
              </button>
              <button onClick={togglePasskey}
                className="w-full flex items-center justify-between px-4 py-3 ios-row">
                <div className="flex items-center gap-3">
                  <Fingerprint className="h-4 w-4 text-secondary-fg" />
                  <div className="text-[14px] text-left">Face ID / fingerprint</div>
                </div>
                <span className={`text-[12px] font-medium ${hasPasskey ? "text-success" : "text-secondary-fg"}`}>
                  {hasPasskey ? "On" : "Off"}
                </span>
              </button>
            </div>
          </Section>

          {/* 6. Help + legal — quiet, terminal items */}
          <Section title="More">
            <div className="rounded-[18px] border border-soft surface-card backdrop-blur-sm divide-y divide-border/50 overflow-hidden">
              <button
                onClick={async () => {
                  await tour.resetAll();
                  nav("/home");
                  setTimeout(() => tour.start(TOUR_TODAY, { force: true }), 400);
                }}
                className="w-full flex items-center gap-3 px-4 py-3 ios-row"
              >
                <HelpCircle className="h-4 w-4 text-secondary-fg" />
                <span className="text-[14px] flex-1 text-left">Replay tutorial</span>
                <span className="text-secondary-fg">›</span>
              </button>
              <Link to="/privacy" className="flex items-center gap-3 px-4 py-3 ios-row">
                <Shield className="h-4 w-4 text-secondary-fg" />
                <span className="text-[14px] flex-1">Privacy</span>
                <span className="text-secondary-fg">›</span>
              </Link>
              <Link to="/terms" className="flex items-center gap-3 px-4 py-3 ios-row">
                <FileText className="h-4 w-4 text-secondary-fg" />
                <span className="text-[14px] flex-1">Terms</span>
                <span className="text-secondary-fg">›</span>
              </Link>
              <Link to="/settings/delete-account" className="flex items-center gap-3 px-4 py-3 ios-row text-destructive">
                <Trash2 className="h-4 w-4" />
                <span className="text-[14px] flex-1">Delete account</span>
                <span>›</span>
              </Link>
            </div>
          </Section>

          <Button onClick={signOut} variant="outline" className="w-full h-11 rounded-xl border-soft surface-card hover:bg-surface-elevated pressable text-[13px]">
            Sign out
          </Button>

          <button
            type="button"
            onClick={() => {
              setVersionTaps((n) => {
                const next = n + 1;
                if (next >= 10) {
                  setPerfPanelOpen(true);
                  return 0;
                }
                return next;
              });
            }}
            className="block w-full text-center text-[11px] text-secondary-fg pt-1 select-none"
            aria-label="App version"
          >
            DayDraft · v1.0
          </button>
          <PerfDebugPanel open={perfPanelOpen} onOpenChange={setPerfPanelOpen} />
        </div>
      </div>
      <Sheet open={proSheetOpen} onOpenChange={setProSheetOpen}>
        <SheetContent side="bottom" className="rounded-t-[24px] border-soft max-h-[85vh] overflow-y-auto">
          <SheetHeader className="text-left">
            <SheetTitle className="font-display text-[17px]">Included with Pro</SheetTitle>
            <SheetDescription className="text-[13px]">
              Full list — same features you unlock at checkout.
            </SheetDescription>
          </SheetHeader>
          <div className="mt-4 pb-6">
            <ProFeatureHighlights onUpgrade={() => { setProSheetOpen(false); setUpgradeOpen(true); }} />
          </div>
        </SheetContent>
      </Sheet>
      <UpgradeSheet open={upgradeOpen} onOpenChange={setUpgradeOpen} reason="feature" />
    </>
  );
}

const Section = ({ title, children }: { title: string; children: React.ReactNode }) => (
  <div>
    <div className="text-[10px] uppercase tracking-[0.14em] text-secondary-fg mb-2 font-medium">{title}</div>
    {children}
  </div>
);

const ProCard = ({ entitlement, isPro, subscriptionPro, devSimulatePro, planQuotaUsed, planQuotaLimit, planQuotaRemaining, onUpgrade, onOpenDetails }: {
  entitlement: ReturnType<typeof useEntitlement>["entitlement"];
  isPro: boolean;
  subscriptionPro: boolean;
  devSimulatePro: boolean;
  planQuotaUsed: number;
  planQuotaLimit: number;
  planQuotaRemaining: number;
  onUpgrade: () => void;
  onOpenDetails?: () => void;
}) => {
  const tier = entitlement?.tier || "free";
  const badge = devSimulatePro && !subscriptionPro
    ? "Pro (simulated)"
    : tier === "pro" ? "Pro"
    : tier === "trial" ? `Trial · ${entitlement?.daysLeftInTrial}d left`
    : "Free";
  const isOverQuota = !isPro && Number.isFinite(planQuotaRemaining) && planQuotaRemaining <= 0;
  const lowFreeDays = !isPro && !isOverQuota && Number.isFinite(planQuotaRemaining) && planQuotaRemaining <= 2;
  // Visual cap: never show "7 of 5" — the over-quota state has its own message below.
  const displayUsed = !isPro && Number.isFinite(planQuotaLimit) ? Math.min(planQuotaUsed, planQuotaLimit) : planQuotaUsed;

  return (
    <div
      className={`rounded-[18px] border backdrop-blur-sm p-4 shadow-card surface-accent ${
        isOverQuota
          ? "border-primary/60 ring-1 ring-primary/20"
          : lowFreeDays
            ? "border-primary/50 ring-1 ring-primary/15"
            : "border-accent"
      }`}
    >
      <div className="flex items-center gap-1.5">
        <Sparkles className="h-3.5 w-3.5 text-primary" />
        <span className="text-[10px] font-semibold text-primary uppercase tracking-[0.14em]">{badge}</span>
      </div>
      <div className="text-[15px] font-display font-semibold mt-2 text-foreground leading-tight">
        {isPro ? "You're on Pro" : isOverQuota ? "Free trial used up" : "Make planning unlimited"}
      </div>
      <div className="text-[13px] mt-1 text-secondary-fg leading-relaxed">
        {isPro
          ? "Calendar sync, pattern-aware AI, and every premium feature stay on."
          : isOverQuota
            ? `You've used all ${planQuotaLimit} free planning days. New plans are paused — upgrade to keep going.`
            : `${displayUsed} of ${planQuotaLimit} free planning days used — then new plans are paused until you upgrade.`}
      </div>
      {!isPro && lowFreeDays && (
        <p className="text-[12px] font-medium text-primary mt-2 leading-snug">
          {planQuotaRemaining === 1
            ? "Just 1 free planning day left. Upgrade so a busy week never blocks the next."
            : `Only ${planQuotaRemaining} free planning days left. Upgrade so a busy week never blocks the next.`}
        </p>
      )}
      {!isPro && onOpenDetails && (
        <button
          type="button"
          id="pro-features"
          onClick={onOpenDetails}
          className="mt-3 text-[12px] font-medium text-primary pressable block"
        >
          What&apos;s included · Full list
        </button>
      )}
      {!isPro && !isOverQuota && (
        <p className="text-[11px] text-secondary-fg mt-2.5 leading-relaxed">
          Each calendar day with tasks counts once. Re-planning or adding more tasks to the same day is free.
        </p>
      )}
      {!isPro && (
        <Button onClick={onUpgrade} className="w-full mt-3 h-11 rounded-xl bg-primary hover:bg-primary/92 text-primary-foreground text-[14px] font-semibold pressable shadow-card">
          See Pro & unlock everything
        </Button>
      )}
      {isPro && subscriptionPro && (
        <button onClick={() => toast("Subscription management will be available soon")}
          className="w-full mt-3 h-10 rounded-[12px] text-[12px] text-secondary-fg border border-soft surface-card pressable hover:text-foreground">
          Manage subscription
        </button>
      )}
    </div>
  );
};

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { LegalLayout } from "./LegalLayout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export default function DeleteAccount() {
  const { user, signOut } = useAuth();
  const nav = useNavigate();
  const [confirm, setConfirm] = useState("");
  const [busy, setBusy] = useState(false);

  const handleDelete = async () => {
    if (!user) return;
    if (confirm !== "DELETE") { toast.error('Type "DELETE" to confirm'); return; }
    setBusy(true);
    try {
      // Cascade-delete user-owned rows (RLS allows users to delete their own).
      // Order matters where FKs exist.
      await supabase.from("blocks").delete().eq("user_id", user.id);
      await supabase.from("plans").delete().eq("user_id", user.id);
      await supabase.from("time_entries").delete().eq("user_id", user.id);
      await supabase.from("time_categories").delete().eq("user_id", user.id);
      await supabase.from("block_templates").delete().eq("user_id", user.id);
      await supabase.from("quick_captures").delete().eq("user_id", user.id);
      // streaks table is no longer surfaced in-app; rows (if any) are left.
      await supabase.from("user_patterns").delete().eq("user_id", user.id);
      await supabase.from("push_subscriptions").delete().eq("user_id", user.id);
      await supabase.from("calendar_tokens").delete().eq("user_id", user.id);
      await supabase.from("subscriptions").delete().eq("user_id", user.id);
      await supabase.from("profiles").delete().eq("id", user.id);

      // Note: removing the auth user itself requires a server-side admin call.
      // Mark email for purge; user is signed out and data is gone.
      toast.success("Your data has been deleted. Signing out…");
      await signOut();
      nav("/auth", { replace: true });
    } catch (e: any) {
      toast.error(e.message || "Failed to delete. Email support@daydraft.app");
    } finally { setBusy(false); }
  };

  return (
    <LegalLayout title="Delete your account">
      <p>This action is <strong>permanent</strong>. Deleting your account will erase:</p>
      <ul className="list-disc pl-5 space-y-1">
        <li>All your tasks, plans, and daily blocks</li>
        <li>Time tracking entries and categories</li>
        <li>Statistics and recaps</li>
        <li>Templates, quick captures, and notification subscriptions</li>
        <li>Connected calendar tokens and subscription records</li>
        <li>Your profile</li>
      </ul>
      <p>You will not be able to recover this data. If you only want a break, you can sign out instead — your data will be preserved.</p>

      <div className="mt-8 p-4 rounded-2xl border border-destructive/30 bg-destructive/5 space-y-3">
        <label className="text-sm font-medium text-foreground">Type <span className="font-mono">DELETE</span> to confirm</label>
        <Input value={confirm} onChange={e => setConfirm(e.target.value)} placeholder="DELETE" className="surface-card" />
        <Button
          variant="destructive"
          disabled={busy || confirm !== "DELETE"}
          onClick={handleDelete}
          className="w-full"
        >
          {busy ? "Deleting…" : "Permanently delete my account"}
        </Button>
      </div>

      <p className="text-xs text-secondary-fg mt-6">
        Need help instead? Contact <a href="mailto:support@daydraft.app">support@daydraft.app</a> — we usually reply within 24h.
      </p>
    </LegalLayout>
  );
}
